INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993196941', 'Espelho De Aumento Articulado 3x Giratório 360º Dupla Face Maquiar Barbear Maquiagem Agrantt', 'Espelho De Aumento Articulado Dupla Face Aço Cromado - Aumenta 3x Para quem tem pouco espaço e não abre mão de produtos de qualidade, esta é a escolha certa. Com estrutura flexível e base para fixar na parede, o Espelho de Aumento Articulado Dupla Face da Agrantt permite maior precisão na hora de barbear, fazer uma maquiagem especial, colocar lentes de contato ou até utilizar como auxiliar no momento de gravar vídeos para a internet. Produzido em aço cromado, que confere qualidade e a durabilidade ao produto, uma das faces do espelho é normal e a outra amplia a imagem refletida em até duas vezes. Sofisticado e elegante, possui ainda movimento giratório do espelho em até 360°, que facilita na direção e focalização da área desejada. Características: > Materiais: - Espelho: Vidro - Estrutura: Aço Cromado > Movimento Do Espelho: Até 360 > Medidas: - Diâmetro Do Espelho: Ø17cm - Medida Do Braço Aberto: 39cm - Medida Do Braço Fechado: 22cm - Altura Total: 27cm - Largura Total: 3cm - Comprimento Total: 22cm - Distância entre os furos: 9cm > Peso: 493g - Marca: Agrantt - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica. - Produto novo, com garantia de fábrica. - Produto a pronta entrega. - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 96.07, 78.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0ygzmdtzlcn53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F23993196941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
