INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8615749604', 'DIARIO DE UMA GAROTA NADA POPULAR VOL 5 - VERUS', 'Nikki Maxwell passa a se interessar por jornalismo quando Mackenzie começa a escrever uma coluna de fofocas, onde relata informações sobre sua paixão, Brandon, as quais Nikki não queria que fossem divulgadas. Então Nikki se junta a equipe do jornal da escola e acaba escrevendo uma coluna de conselhos! No início é divertido, ao responder cartas de outras crianças. Mas quando sua caixa de correspondência fica repleta de pedidos de orientações, Nikki passa a precisar de ajuda. Felizmente ela tem suas melhores amigas Chloe e Zoey ao seu lado ― e em seu teclado também!', 62.9, 62.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-82632-mjkjlp1ir1tw7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F8615749604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299370106', 'Tênis de Academia Treino Unissex - Olympikus', 'Tênis de Academia Treino Unissex – Olympikus O Tênis de Academia Treino Unissex Olympikus foi desenvolvido para quem busca leveza, conforto e estilo durante os treinos e nas atividades do dia a dia. Seu design moderno acompanha uma construção funcional, ideal para exercícios em academia, caminhadas leves e rotinas ativas. A combinação de materiais garante um calçado versátil, confortável e com visual esportivo que se adapta facilmente a diferentes momentos. O grande destaque do modelo é a entressola com tecnologia EVASENSE, que proporciona absorção de impacto, maciez e flexibilidade desde o primeiro calce. Essa tecnologia em EVA contribui para passadas mais suaves e confortáveis, reduzindo o impacto nas articulações e oferecendo sensação de leveza durante o uso prolongado, seja em treinos ou no cotidiano. O cabedal em poliéster com impressão digital e tecnologia HIGH FREQUENCY oferece resistência e visual diferenciado, enquanto o logo em TPU e detalhes em laminado agregam durabilidade e acabamento moderno. A lingueta acolchoada em poliéster e espuma, aliada ao forro interno com espuma, garante conforto contínuo e melhor adaptação ao pé durante a movimentação. Para maior praticidade, o modelo conta com puxador traseiro em fita com arte gráfica, facilitando o calce, além de atacador em poliéster texturizado para ajuste firme. A palmilha em EVA e poliéster contribui para maciez e secagem mais rápida. Já o solado com tecnologia GRIPPER oferece borracha antiderrapante de alta resistência, garantindo estabilidade, segurança e durabilidade em diferentes superfícies. Especificações Marca: Olympikus Gênero: Unissex Indicação: Treino e uso diário Cabedal: Poliéster com HIGH FREQUENCY Entressola: EVA com tecnologia EVASENSE Palmilha: EVA e poliéster Solado: Borracha com tecnologia GRIPPER antiderrapante Fechamento: Cadarço em poliéster', 469.9, 359.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81zug-mko3zhssuf413b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F22299370106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
