INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093744982', '50 ~ 300 FORMINHAS AMARELO XADREZ 4 PÉTALAS - FESTA JUNINA (CHOCO)', 'ESTE KIT OFERECE UMA VARIEDADE DE FORMINHAS DE PAPEL (ENTRE 50 E 300 UNIDADES) COM 4 PÉTALAS E UM CHARMOSO ESTAMPADO XADREZ AMARELO, PERFEITO PARA COMPOR A DECORAÇÃO DA SUA FESTA JUNINA 🌽🔥. IDEAIS PARA EMBALAR SEUS BRIGADEIROS 🍫, BEIJINHOS 🥥, CAJUZINHOS E OUTROS DOCINHOS, ADICIONANDO UM TOQUE RÚSTICO E TRADICIONAL À SUA MESA DE GULOSEIMAS. AS FORMINHAS SÃO ENVIADAS DESMONTADAS PARA EVITAR DANOS DURANTE O TRANSPORTE. TAMANHO: APROXIMADAMENTE 3 CM DE LARGURA X 3 CM DE COMPRIMENTO (BASE) COM 2,5 CM DE ALTURA 📏. MATERIAL: PRODUZIDAS EM PAPEL OFFSET COM IMPRESSÃO XADREZ AMARELO 💛🧺. ATENÇÃO ❗: NÃO ACOMPANHA OS DOCES (AS FOTOS SÃO APENAS SUGESTÕES DE USO 📸). NÃO FAZEMOS PERSONALIZAÇÃO NESTE ITEM 🙅‍♀️. VERIFIQUE O PRAZO DE ENVIO 🚚 ANTES DE FINALIZAR A COMPRA. AS FORMINHAS SÃO ENVIADAS DESMONTADAS PARA PRESERVAÇÃO E FACILIDADE DE ENVIO, MAS SÃO FÁCEIS DE MONTAR 😉. A TONALIDADE DO AMARELO PODE VARIAR LIGEIRAMENTE 🎨 DEPENDENDO DO LOTE E DO SEU MONITOR 🖥️. DEIXE SUA FESTA JUNINA AINDA MAIS ACONCHEGANTE E COM AQUELE CLIMA DE ARRAIÁ! CLIQUE EM "VER MAIS PRODUTO DESSE VENDEDOR" PARA CONHECER OUTRAS OPÇÕES! ✨', 9.85, 9.85, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6zj7dtl3rcg86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23093744982', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397426995', '10 CAIXA (04 DOCES) COM ELA 4x8x8 cm 4931 ( DIA DAS MÃES IDEIA ) OUTLET', 'CAIXA PRACTICE P/4 DOCES DIA DAS MÃES Tamanho da embalagem montada: 4x8x8 cm Confeccionada em papel triplx Premium. As caixas possuem um design único e de fácil montagem. Podem ser utilizadas para embalagem para doces e mimos. ATENÇÃO: - Quantidade no título do anúncio. - Não inclui doces e chocolate (apenas embalagem). - Não personalizamos, cores e temas apenas como está na foto. - CONFIRA O PRAZO DE ENVIO NO ATO DA COMPRA. - A caixa é enviada desmontada para a preservação do produto e otimização e de custo de frete', 21.95, 21.95, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rccf-ltea1zkxjo7zde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F22397426995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44330964246', 'Kit Máscara Para Cílios Olive Green + Blush Stick Cinnamon + BRINDE Original Vegano Vizzela', 'Kit Máscara Para Cílios Olive Green + Blush Stick Cinnamon + BRINDE Original Vegano Vizzela Maquiagens básicas podem perder impacto quando não combinam definição no olhar com cor natural no rosto. O Kit Máscara Para Cílios Big No Panda Olive Green + Blush Stick Cinnamon Vizzela foi desenvolvido para destacar os cílios com pigmentação verde oliva e adicionar um tom quente de marrom canela às maçãs do rosto com acabamento natural. Benefícios Principais A Máscara Big No Panda Olive Green possui pigmentação verde oliva, ideal para transformar maquiagens básicas em produções com mais destaque. O tom valoriza principalmente olhos cor de mel, avelã, castanhos claros e esverdeados. Seu aplicador Big, grande e curvado, auxilia na aplicação da raiz até as pontas, proporcionando volume e curvatura aos cílios. A tecnologia No Panda ajuda a evitar borrões ao longo do dia e permite remoção em formato de película com água morna. O Blush Stick Cinnamon possui textura cremosa, desliza facilmente sobre a pele e permite construir camadas para um acabamento mais leve ou mais intenso. A cor Cinnamon entrega um tom quente de marrom canela com efeito tint natural e saudável. Após esfumado, o produto seca completamente, sem deixar resíduos oleosos ou sensação pegajosa. O kit acompanha um brinde exclusivo da Vizzela por tempo limitado. As cores dos brindes são enviadas de forma sortida, conforme disponibilidade em estoque. Compatibilidade e Aplicação Indicado para maquiagem dos olhos e do rosto, uso diário, produções casuais e maquiagens com destaque de cor. Ideal para quem busca cílios com volume e curvatura, pigmentação verde oliva, blush cremoso em tom Cinnamon e acabamento natural. Especificações Técnicas Produto: Kit Máscara Para Cílios + Blush Stick Marca: Vizzela Produto 1: Máscara Para Cílios Big No Panda Olive Green Cor da Máscara: Verde oliva Pigmentação da Máscara: Verde oliva Aplicador da Máscara: Pincel Big, grande e curvado Efeito da Máscara: Volume e curvatura Tecnologia da Máscara: No Panda Remoção da Máscara: Em formato de película com água morna Fórmula da Máscara: Vegana Selo da Máscara: PETA Oftalmologicamente Testada: Sim Cruelty-Free: Sim, não testada em animais Paraben Free: Sim, livre de parabenos Selo Eu Reciclo: Sim Produto 2: Blush Stick Cinnamon Cor do Blush: Cinnamon Tom do Blush: Marrom canela Textura do Blush: Cremosa Acabamento do Blush: Efeito tint natural Secagem do Blush: Seca completamente após esfumado Resíduo Oleoso: Não deixa resíduos oleosos após esfumado Sensação Pegajosa: Não Uso do Blush: Maçãs do rosto Brinde: Sim, exclusivo da marca Envio do Brinde: Cor sortida conforme disponibilidade em estoque Marca da Loja: Vizzela Observação: Brinde por tempo limitado Observação: Produto original vegano Itens Inclusos 01 Máscara Para Cílios Big No Panda Olive Green Vizzela 01 Blush Stick Cinnamon Vizzela 01 Brinde exclusivo Vizzela em cor sortida conforme estoque Como Usar Aplique a Máscara Big No Panda Olive Green da raiz dos cílios até as pontas, com movimentos de zigue-zague. Para um efeito mais intenso, aplique mais camadas. Aplique o Blush Stick Cinnamon diretamente nas maçãs do rosto e esfume com os dedos, pincel ou esponja até atingir o acabamento desejado. #DicaDeAmiga Para uma maquiagem equilibrada, use o Blush Stick Cinnamon bem esfumado para criar um acabamento natural no rosto e finalize com a Máscara Olive Green para destacar o olhar com um ponto de cor moderno. VIZZELA Somos uma marca 100% brasileira, vegana, cruelty-free certificada pelo PETA e com fórmulas incríveis. Maquiagem que te deixa linda e faz bem para o planeta!', 158.0, 118.8, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/br-11134207-820li-mozs5wda07id7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1633001354%2F44330964246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
