INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898859753', 'Vinho Tinto Brasileiro Seco San Martin 750ml Kit 4 Un', 'Vinho Tinto de Mesa San Martin Bordô Seco 750 mlO Vinho San Martin Bordô Seco é um clássico da vitivinicultura brasileira, produzido com a uva Bordô, conhecida por sua intensidade e caráter marcante. De coloração rubi profunda, apresenta aromas frutados envolventes e um paladar encorpado e seco, que conquista apreciadores de vinhos mais robustos.Na versão garrafa de 750 ml em vidro, une praticidade ao charme tradicional, ideal para refeições em família, encontros especiais ou para apreciar no dia a dia.Harmoniza muito bem com carnes vermelhas, massas ao molho encorpado, queijos curados e pratos típicos brasileiros, realçando os sabores e proporcionando experiências únicas à mesa.Sabor intenso e seco, com boa estrutura Aroma marcante de frutas escuras Garrafa de 750 ml em vidro Ideal para harmonizações mais robustasO San Martin Bordô Seco 750 ml é a escolha certa para quem valoriza tradição e qualidade em cada taça.', 129.0, 99.0, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-824je-me7n6b6xiltt51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F23898859753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
