INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204065061', 'Tangle Teezer The Wet Detangler Orange/Pink - Escova de Cabelo', 'Escova de cabelo para todos os tipos de cabelo. Escova de Cabelo Tangle Teezer The Wet Detangler a melhor opção para desembaraçar os fios molhados, sem danificá-los. A Escova de Cabelo Tangle Teezer The Wet Detangler possui 325 cerdas flexíveis que ajudam a desfazer os nós de modo seguro e confortável. Além disso, conta com um cabo que impede que a escova escorregue nas mãos e facilita na aplicação do shampoo, máscara ou condicionador. *Nova embalagem. Você poderá receber o produto com a embalagem antiga enquanto durarem os estoques. Como Usar: Seque suavemente o cabelo com uma toalha. Com a escova, comece a desembaraçar os fios pelas pontas. Continue a desembaraçar até que consiga escovar da raiz às pontas. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 114.9, 114.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-82621-mjycnsq1k0ee00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204065061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
