INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51253232129', 'Desodorante Roll-on NIVEA Derma Control Defende 50ml', 'O que é? NIVEA Desodorante Roll-on Derma Control Defende é um antitranspirante desenvolvido para oferecer proteção intensa contra o suor e o mau odor, cuidando da pele das axilas com uma fórmula especial que inclui Ácido Hialurônico e Pró-Vitamina B5. Para que serve? Garante proteção de até 72 horas contra o suor e mau odor, enquanto proporciona uma sensação de conforto extra. É ideal para quem tem pele sensível pós-depilação, pois sua fórmula suave ajuda a prevenir irritações e coceira nas axilas. Benefícios e diferenciais: - Proteção antitranspirante de 72h - Ácido Hialurônico puro e Pró-Vitamina B5 - Sem Álcool Etílico - Dermatologicamente Testado - Evita irritação e coceira', 15.2, 15.2, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-81zvz-mid1hmko0npe89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F51253232129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
