INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12210550390', 'Kit 4 Amaciantes de Roupa Comfort Concentrado Puro Cuidado Intense 1,5l', 'Kit 4 Amaciantes de Roupa Comfort Concentrado Puro Cuidado Intense 1,5l Nada é mais suave que o Amaciante Concentrado Comfort Puro Cuidado. Perfeito para pessoas que contam com sensibilidade. Sua fórmula é exclusiva para peles sensíveis, ideal para lavar todo enxoval do bebê. O Amaciante Concentrado Comfort Puro Cuidado é testado dermatologicamente e hipoalergenicamente, garantindo assim saúde e bem estar para você e sua família! * Kit Contém: 4 Amaciantes de Roupa Comfort Concentrado Puro Cuidado Intense 1,5l cada * Compre produtos Comfort.', 169.86, 137.86, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-824j6-met0bjykf18gac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12210550390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297728278', 'Kit 4 Milbemax C para Cães até 5 Kg Elanco Vermífugo - 2 Comprimidos', '- Acompanha adesivos; - Indicado para a prevenção da dirofilariose canina; - Tratamento e controle de infestações intestinais por vermes redondos e chatos (estágios imaturos e adultos) tais como Ancylostoma caninum, Toxocara canis, Toxascaris leonina, Trichuris vulpis; Dipylidium caninum, Taenia spp., Ecchinococcus spp., Mesocestoides spp. * Consulte sempre o médico Veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes O Vermífugo Milbemax C para Cães até 5 Kg indicado para a prevenção da dirofilariose canina, tratamento e controle de infestações intestinais por vermes redondos. Dicas Especiais Modo de usar: Administrado a partir de 2 semanas de idade, e a partir daí, mensalmente até o animal completar seis meses de vida. Cadelas amamentando devem ser tratadas ao mesmo tempo que os filhotes delas. Os cães adultos devem ser tratados 4 vezes por ano, em se tratando de verminose gastrintestinal e mensalmente, para prevenção da infestação pelo verme do coração. REAÇÕES ADVERSAS: Em casos excepcionais, sinais clínicos leves como ataxia, depressão e emese podem ocorrer depois do uso de Milbemax C. Composição Milbemicina Oxima Comprimido2,5 mg Praziquantel por Comprimido25 mg Excipiente qsq125 mg', 182.26, 153.99, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820ls-mn5tyhe6ovlt86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23297728278', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
