INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253191336', 'L''Oréal Professionnel Inforcer Serie Expert - Condicionador 200ml', 'Condicionador para cabelos frágeis e quebradiços. L''Oréal Professionnel Inforcer Serie Expert previne imediatamente a quebra, deixando os fios mais fortes e resistentes. Com L''Oréal Professionnel Inforcer Serie Expert dia após dia a fibra capilar parece inquebrável. Os fios com dificuldade de crescer recebem um tratamento nutritivo que estimula o seu crescimento. Este estimulo é feito em fios já existentes, que crescem mais fortes e saudáveis. Seu cabelo fica mais saudável, macio e brilhante. Como usar: Distribua de maneira uniforme por todo o cabelo lavado e seco com uma toalha. Deixe no cabelo de 2 a 3 minutos e depois enxague completamente.Distribua de maneira uniforme por todo o cabelo lavado e seco com uma toalha. Deixe no cabelo de 2 a 3 minutos e depois enxague completamente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 173.9, 173.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mjy9dw6zb37mbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253191336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
