INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594681840', 'SHORT CANELADO COM ELÁSTICO NA CINTURA ACTION DLK', 'Não importa qual seja sua escolha de treino, o Short Fitness Feminino Canelado Elástico na Cintura da coleção Action é a peça perfeita pra você. Ele oferece todo o suporte necessário para todo tipo de atividade física, seja no treino ao ar livre, academia, crossfit ou artes marciais. Esse Short Fitness Feminino possui modelagem moderna e atemporal, fazendo com que seja sua opção ideal a qualquer momento do dia. O cós em elástico e a compressão média garantem firmeza e segurança para você realizar os movimentos sem preocupações, enquanto suas linhas e recortes realçam a área do quadril, deixando seu look muito mais estiloso e sofisticado. Seu tecido canelado e design clássico trazem muita elegância e conforto à peça Pensando também na prática de exercícios físicos ao ar livre e buscando reduzir o impacto ambiental da moda fitness, essa malha canelada foi desenvolvida com acabamento reciclado, confeccionado a partir de resíduo plástico, a fim de oferecermos peças cada vez mais ecológicas e sustentáveis! Além disso, o material é super elástico e possui caimento modelador, se adequando aos mais variados tipos de curvas.', 93.99, 93.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-821dg-mh23pd3ija4p94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F23594681840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497424759', 'KIT 3 Bermuda Short Masculina Moletinho Casual Adulto', 'Seja Bem vindo a Loja Oficial da DAZE MODAS na SHOPEE. Bermuda moletinho, confeccionada com 100% de poliéster para proporcionar o máximo de conforto. Esta peça foi projetada cuidadosamente para garantir conforto e estilo durante seu dia a dia. A cintura elástica com elastano oferece um ajuste perfeito, permitindo que se mova livremente. Além disso, o cordão ajustável na cintura permite um ajuste personalizado, garantindo um caimento confortável e seguro. Especificações do Produto: > Marca: Daze Modas > Tecido: Moletinho > Bolsos: 2 Frontais > Material: Moletinho > Composição: 100% Poliéster > Modelagem: Curta >Tamanhos: P ao GG Especificações do Modelo: Modelo Veste: M Tamanho do produto que o modelo usou na foto: M Altura: 1.79m Tórax: 101cm Cintura: 87cm Quadril: 100cm Peso: 80 HORÁRIO DE ATENDIMENTO: De Segunda à Quinta das 08h00 às 18h00 De Sexta das 08h00 às 17h00 Seja Bem vindo a Loja Oficial da DAZE MODAS na Shopee.', 154.99, 112.9, NULL, 'Men Clothes > Shorts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8ez4zl958mp76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287750271%2F18497424759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
