INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394323900', 'Mini Central VU+ Digital RGB Para Efeitos Luminosos 12/24V Zendel', 'CENTRAL VU+ - ZENDEL ZD-VU O VU+ é uma central de efeitos para leds endereçáveis, permitindo a conexão de faróis ou fitas led com processamento digital. Conta com um microfone interno que capta o som e ativa o efeito VU automaticamente. CARACTERÍSTICAS • Compatível com fitas led digitais WS2811 e WS2812, além de faróis digitais. • Faz 20 efeitos e 7 cores (Mais de 500 combinações). • 4 Níveis de velocidade. • 8 Níveis de sensibilidade do microfone. • Faz o efeito VU. • Central compacta e de instalação simplificada. PRINCIPAIS VANTAGENS • Compatibilidade com leds endereçáveis Permite conectar diversos tipos de leds endereçáveis, oferecendo mais opções de personalização para seu projeto. • Efeito de resposta ao áudio O microfone interno capta o áudio ambiente e gera efeitos visuais sincronizados, criando uma experiência interativa. • Instalação simples Conexões fáceis e rápidas, ideal para quem precisa de uma solução prática e eficiente para seus sistemas de iluminação. • Compacto e poderoso Design compacto, que não ocupa muito espaço, mas com alto desempenho na criação de efeitos visuais impressionantes. ITENS INCLUSOS • 01 Central VU+', 109.9, 91.99, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rdwb-mddmvccbjj2883', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413702429%2F22394323900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18065988816', 'Bagageiro Churrasqueira Sansão Cromo Forte Aço Maciço Titan / Fan / Start', 'Bagageiros são acessórios úteis em motocicletas para transportar bagagens, equipamentos e outras cargas. O Bagageiro Cromo Forte modelo Sansão TITAN / FAN / START oferece mais agilidade na instalação, pois com seu sistema de fixação que é acoplado na alça original dispensa a remoção da rabeta! A utilização de bagageiros Cromo Forte em motocicletas tem muitas vantagens, incluindo: - Conforto e praticidade: carregar a bagagem na moto ao invés de carregar nas costas é muito mais confortável, especialmente em viagens longas! - Segurança: uma carga bem presa no bagageiro é muito mais segura do que carregar solta na moto ou nas costas! - Capacidade de transporte: o bagageiro aumenta a capacidade de carga da moto, permitindo que o piloto transporte mais itens. Especificações: - Fabricado em Aço Maciço; - Cor: Cromado e Preto; - Pintura Eletrotástica; - Marca: Cromo Forte; - Carga máxima suportada: 6kg. Aplicação: - TITAN 150 2014; - TITAN 150 2015. - FAN 125 / 150 2014; - FAN 125 / 150 2015. - FAN 125 2017. - START 150 / 160 2017; Observações: É importante lembrar que a carga no bagageiro deve ser bem distribuída e bem fixada para garantir a segurança na pilotagem da moto. É recomendado também verificar a capacidade de carga do bagageiro e a capacidade de carga total da motocicleta antes de carregar o bagageiro para evitar sobrecarga. A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada ou por defeitos causados por mal uso. - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 184.11, 109.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj1gu76ewwan28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F18065988816', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9554027217', 'Pedal de Cambio Com Regulagem Pro Tork Biz 100 1998 1999 2000 2001 2002 2003 2004 2005 Cromado', 'O Pedal de Câmbio BIZ 100 Pro Tork é fabricado com o exclusivo Aço 1045T, alta qualidade e resistência para o produto. O ponto de fixação no eixo do câmbio é frisado, apresenta estrias e regulagem. Especificações: - Pintura Antioxidante; - Possui Borracha Injetada; - Disponibilizado na Dimensão Original; - Marca: Pro Tork. Aplicação: - BIZ 100 1998; - BIZ 100 1999; - BIZ 100 2000; - BIZ 100 2001; - BIZ 100 2002; - BIZ 100 2003; - BIZ 100 2004; - BIZ 100 2005. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada. A Sportbay não se responsabiliza pela má instalação do produto. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/9cd366556cdc1bdc42bc44cd8e4b178e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F9554027217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44125213592', 'Giorno Cucina Sentire Bene Masterchef - Lava Louças 500ml', 'Giorno Cucina Sentire Bene Masterchef - Limpeza Eficiente e Frescor Oferece limpeza rápida e eficaz com espuma cremosa, eliminando até gorduras difíceis. Com tecnologia NeoFresh e tensoativo biodegradável, neutraliza odores de alho, cebola e fritura, deixando suas louças impecáveis e a cozinha fresca, com praticidade e sofisticação no dia a dia. Conselho de Aplicação Aplique uma quantidade suficiente do produto diretamente na esponja ou no recipiente a ser limpo. Esfregue as louças normalmente, utilizando água morna para melhores resultados. Enxágue abundantemente.', 42.9, 26.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mg2myu3wykgbab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F44125213592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
