INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198087792', 'Cookies Morango Sem Glúten Star Wars Disney 60 g', 'Descubra a magia do Cookies Disney sem glúten morango e zero adição de açúcares, uma deliciosa opção para quem busca um lanche crocante e cheio de sabor. Cada mordida traz a suavidade e o aroma envolvente da baunilha, para uma experiência única de sabor, combinado com qualidade e rotina saudável.. INGREDIENTES: Fécula de mandioca, farinha de arroz, óleos vegetais (soja, milho e algodão), fécula de batata, gotas de cobertura sabor chocolate sem lactose, fibra de soja não transgênica, fibra de tapioca, farinha de soja não transgênica, flocos de morango, sal, edulcorantes maltitol e sucralose, emulsificantes lecitina de soja, estearoil lactato de sódio e mono e diglicerídeos de ácidos graxos, fermentos químicos bicarbonato de sódio, bicarbonato de amônio, pirofosfato ácido de sódio, fosfato monocálcico, espessante goma xantana, acidulante ácido cítrico e aromas. ALÉRGICOS: CONTÉM DERIVADOS DE SOJA. PODE CONTER AMÊNDOA, AVEIA (SEM GLÚTEN), CASTANHA-DE-CAJU E CASTANHA-DO-PARÁ. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. SEM GLÚTEN, ZERO ADIÇÃO DE AÇÚCARES, ZERO LACTOSE, VEGANO.', 8.49, 7.05, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/br-11134207-820lh-mn01xafvqqkkf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F22198087792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20032341208', 'Coturno Feminino Bota Salto Baixo Tratorado GiGiL', 'Descrição: Calça o tamanho normal, forma padrão Coturno Salto Médio tratorado Material Externo: Napa Sintética Detalhe Colarinho: Espuma na parte do tornozelo. Forro: cacharrel tecido, com espuma. Material Interno: Material Têxtil Super Confortável. Solado: Micro Gel. Altura da Sola: 6,5 cm Altura da sola na frente: 1,5 cm Altura do Cano: 12 cm Palmilha: Confortável, com espuma e com aplique da logo. CONSERVAÇÃO: Para conservar o seu modelo novo e bonito por muito mais tempo é fundamental seguir algumas recomendações: A limpeza deve ser feita com sabão neutro e pano úmido e não deve ficar de molho. Não usar nenhuma fonte de calor para secar. Guardar em local sem umidade e deixar descansar na sombra por 12 horas após o uso. Não utilize Máquina de lavar e secar. Independente do material do seu sapato, não esfregue com força ou passe esponjas grossas. Caso alguma dessas indicações não forem cumpridas, isso poderá danificar os materiais, a cor e a textura do seu calçado.', 99.99, 79.99, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/cc0f522cabfb456e6a8fb699281a67b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F387348115%2F20032341208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251832590', 'Vult Cabelos Recarga de Hidratação Leave-In 10 em 1 100ml', 'Vult Cabelos Recarga de Hidratação Leave-In Spray 10 em 1 revitaliza, fortalece os fios e desfaz nós. Ele é multibenefícios e ainda traz a Tecnologia HD, que reduz a porosidade. Com Colágeno Vegetal e Ácido Hialurônico, usando junto com outros itens da linha, hidrata por até 72 horas. Veja o que mais ele tem: - Proteção UV e térmica de até 230°C; - Fios até 4x mais desembaraçados; - Livre de sal, parabenos, petrolatos, sulfatos e silicones; - Vegano; - Liberado para low poo. Nenhum produto Vult é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 41.99, 41.99, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-822x9-mi527sx43zt2eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675526045%2F58251832590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393542700', 'Kit 2 Bermudas Esportivas Masculinas Hering Sports', 'Kit 2 bermudas em tecido de poliéster texturizado, garantindo respirabilidade. Tecido de fácil cuidado, com elasticidade e movimento. Esse kit contém 1 bermuda na cor azul e 1 bermuda na cor cinza. Detalhes da peça: Tecido de poliéster Texturizado Modelagem reta Recorte lateral Bolsos funcionais', 279.99, 279.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7reo5-m2v4bgyto7wba5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F23393542700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597631019', 'Junta Tampa De Valvula Palio Grand Siena Punto 500 1.0 1.4 8v Evo 2011 A 2020 Sabó', 'JUNTA DA TAMPA DE VÁLVULAS SABÓ - LINHA FIAT FIRE EVO PRODUTO NOVO - ORIGINAL SABÓ - NOTA FISCAL E GARANTIA Mantenha o motor do seu Fiat seco e protegido com a qualidade da Sabó, fornecedora original das grandes montadoras. Esta junta foi desenvolvida especificamente para os motores Fire EVO que utilizam tampa de válvulas de plástico. Fabricada com elastômeros de alta resistência, ela suporta as variações de temperatura e evita vazamentos crônicos que podem atingir as velas e cabos de ignição. DADOS DO PRODUTO Marca - Sabó (Qualidade Original) Referência Sabó - 75629 Referência OEM - 55222898 - 55247076 Material - Borracha Nitrílica de alta performance Condição - Novo na embalagem oficial Garantia - 3 Meses contra defeitos de fabricação APLICAÇÃO COMPLETA FIAT 500 1.4 8V Evo - 2011 a 2017 Fiorino 1.4 8V Evo - 2013 a 2026 (Modelo atual) Grand Siena 1.4 8V Evo - 2012 a 2021 Palio 1.0 8V Evo - 2011 a 2017 Palio 1.4 8V Evo - 2011 a 2017 Punto 1.4 8V Evo - 2014 a 2017 Siena 1.0 8V Evo - 2012 a 2021 Siena 1.4 8V Evo - 2012 a 2021 Uno 1.0 8V Evo - 2010 a 2021 Uno 1.4 8V Evo - 2010 a 2021 !!! ATENÇÃO - IMPORTANTE !!! TIPO DE TAMPA: Esta junta é exclusiva para motores Fire EVO equipados com a TAMPA DE VÁLVULAS DE PLÁSTICO. Se o seu motor for um Fire antigo com tampa de alumínio, esta peça não servirá. VANTAGENS DA JUNTA SABÓ Vedação Precisa - Moldagem perfeita que acompanha as curvas do cabeçote Fire EVO. Resistência Térmica - Não resseca precocemente com o calor do motor, mantendo a elasticidade. Economia - Evita o desperdício de óleo e mantém os componentes eletrônicos limpos. PERGUNTAS FREQUENTES (FAQ) 1. O produto é original Sabó? Sim. Produto 100% original Sabó, enviado na embalagem lacrada com Nota Fiscal eletrônica. 2. Acompanha os anéis dos parafusos? Esta junta é do tipo integrada. Verifique se o seu modelo de tampa exige anéis separadamente. 3. Serve no motor Fire antigo (ex: Palio 2005)? Não. Motores Fire mais antigos usam tampa de alumínio e requerem uma junta diferente. Este anúncio é exclusivo para a linha EVO (Tampa de Plástico). 4. Como confirmo se serve no meu carro? Informe a PLACA ou o CHASSI do seu Fiat no campo de perguntas abaixo e nossa equipe fará a conferência técnica imediata no catálogo oficial! Dúvidas sobre a compatibilidade? Estamos prontos para te ajudar abaixo!', 37.98, 37.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-lxh0anv7862y7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077953334%2F23597631019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392955069', 'Kit 4 Cera Líquida Bravo Brilho Intenso Incolor Revitaliza 750ml', 'Kit 4 Cera Líquida Bravo Brilho Intenso Incolor Revitaliza 750ml A cera líquida Bravo Máximo Brilho Proteção Duradoura 750 ml para chão possui avançado sistema de secagem rápida que proporciona aos pisos um brilho altamente resistente e proteção antiderrapante. Incolor, sua fórmula de polímero exclusiva forma um filme protetor uniforme e, ao mesmo tempo, faz o piso brilhar, sem polimento adicional. * Kit Contém: 4 Cera Líquida Bravo Brilho Intenso Incolor Revitaliza 750ml cada * Compre Produtos Bravo', 184.79, 184.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rcdt-ltwdyfnfaecpb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F22392955069', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293532192', 'MOP SPRAY COM COM GATILHO E DISPENSER BASIC - SIMPLO', '"conheça o mop spray com gatilho e dispenser da Simplo! prático, resistente e moderno, é bom para faxinas rápidas e limpeza diária com menos esforço: substitui a vassoura, o pano e o balde. é ótimo para pisos frios, sintéticos e de madeira. possui gatilho para borrifar o produto direto na superfície: mantém as mãos longe da sujeira e dos produtos químicos. além disso, tem rotação horizontal de 360° + rotação vertical de 180° do cabo: permite alcançar áreas de difícil acesso, como janelas e embaixo dos móveis. tem reservatório para água ou produto de limpeza: pode ser guardado abastecido e sempre pronto para o uso e a microfibra é de alta absorção: limpa com menos esforço e diminui a utilização de produtos químicos! pode: - usar água, álcool, desinfetante, limpador perfumado ou outros líquidos não oleosos. - lavar a microfibra em máquina de lavar (sem amaciante e sem misturar com panos que soltam fiapos). não pode: - utilizar água sanitária, amaciantes, cera líquida, detergente, sabão em pó ou líquidos oleosos. - deixar no sol ou perto de outras fontes de calor. é de aço inoxidável, microfibra e plástico. leve qualidade e beleza para sua casa! medidas: altura: 126cm largura: 39cm comprimento: 11cm"', 165.9, 111.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-825zp-mlgeukl7oh6q7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F23293532192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592933369', 'Pote de vidro 200ml tampa de bambu hermético redondo - Tüd', '"Oii! Tüd bem? Vem saber mais sobre o pote de vidro com tampa de bambu hermético de 200ml da Tüd! Prático, seguro e decorativo, é bom demais para armazenar temperos ou guardar pequenos objetos, como grampos ou algodão :) O que ele tem de bom: • tampa de bambu natural; • anel de silicone para vedar bem; • resistência a altas e baixas temperaturas; • não retém gosto e nem cheiro após a limpeza; • design supermoderno. Materiais: Vidro borossilicato, silicone e bambu. Para limpar, é só utilizar um pano úmido ou lavar em água corrente com sabão neutro. Cuidados com seu novo pote: Não deixe a tampa imersa em água e nem úmida por muito tempo. Coloque apenas a parte de vidro na lava louças e deixe o pote secar em local arejado. A tampa de bambu possui tratamento de verniz natural (Não transfere cheiro ou gosto para sua comida). Medidas: Comprimento: 6,6cm Largura: 6,6cm Altura: 8cm O pote é tüdbom! Organize sua casa com muuuuuuita praticidade e modernidade. A Tüd chegou pra facilitar a sua vida! Somos uma marca brasileira que é tudo de bom :)"', 58.9, 39.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mlg50r4cts7625', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F22592933369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
