INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897989493', 'Chuteira Futsal Topper Letra IV Masculina Camurça Original Leve e Confortável', 'Chuteira Futsal Topper Letra IV Masculina Original Prepare-se para dominar as quadras com a Chuteira de Futsal Topper Letra IV. Leve, resistente e confortável, ela foi desenvolvida para quem busca agilidade, controle e estabilidade em cada jogada. Com design moderno e construção inteligente, entrega excelente ventilação e amortecimento para partidas intensas. Características principais: Tipo de campo: Futsal / Futebol de salão Cabedal: Tecido em Nylon leve e ventilado Biqueira: Reforço em camurça para maior durabilidade Solado: Borracha antiderrapante com alta aderência Entressola: EVA amortecido, reduz impacto e aumenta conforto Forro: Têxtil acolchoado e respirável Peso aproximado (tam. 43): 300 g (super leve) Marca: Topper Modelo: Letra IV Diferenciais: Leve e respirável, ideal para partidas longas Excelente tração e estabilidade nas quadras indoor Amortecimento eficiente com entressola em EVA Produto original com nota fiscal Envio rápido em até 24h úteis após aprovação Garantia e trocas: 30 dias para devolução por defeito de fabricação Reembolso total caso confirmado Envio rápido e seguro pela Sloth, parceira oficial da Topper Dica de tamanho: Se estiver entre dois tamanhos, escolha o maior para um ajuste mais confortável. chuteira futsal topper, chuteira futebol de salão masculina, chuteira leve topper, chuteira topper original, chuteira para quadra indoor', 399.9, 279.9, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7rfi4-m313a6u1a83t9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F18897989493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
