INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23632488693', 'Bactericida de Veículos e Ambientes Sanitizante Fresh 1,5L Vonixx', 'Bactericida de Veículos e Ambientes Sanitizante Fresh 1,5L Vonixx 2 em 1: Aromatiza e desinfeta e elimina 99,99% das bactérias Sanitizante Fresh foi desenvolvido com quaternário de amônio especial, que age na eliminação de fungos e bactérias do interior do veículo ou ambiente, auxiliando na redução de doenças causadas por esses microorganismos e eliminando maus odores. Além disso, o produto também promove agradável aroma no interior do veículo ou ambiente. MODO DE USAR: - Pulverizar o produto no interior do veículo ou ambiente. - Manter portas e vidros fechados por no mínimo 10 minutos para o produto agir.', 32.99, 32.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-23030-rxzcyqm3jqov67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F384950713%2F23632488693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
