INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797925329', 'Jogo de 6 Pratos Fundos 20,5 cm Oxford Unni Damas', 'Com irreverência e atitude, o aparelho de jantar Unni Damas transforma a mesa posta em um verdadeiro cenário de estilo. A estampa quadriculada em preto e off-white faz uma ponte entre o punk dos anos 90 e o minimalismo moderno, criando uma atmosfera única para suas refeições. Feito com impressão digital, o acabamento texturizado agrega uma experiência sensorial ao conjunto, tornando-o visualmente impactante e também agradável ao toque. Ideal para quem busca um toque lúdico e contemporâneo no dia a dia, este conjunto é perfeito para estimular a criatividade em todos os momentos. O conjunto é composto por 6 pratos fundos com 20,5 cm de diâmetro. Conteúdo da embalagem: 06 Pratos Fundos 20,5 cm - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Material: Cerâmica - Cor: Off White - Formato: Redondo - Decoração: Estampado - Formato de venda: Conjunto - Linha/Decoração: Unni Damas - Tipo da embalagem: Papelão pardo - Uso: Resistente a micro-ondas e lava-louças - Quantidade de peças: 6 - Tipo: Fundo - Diâmetro: 20,5 cm ATENÇÃO: Para compras de pessoa jurídica,&nbsp;cadastre&nbsp;os&nbsp;dados exatamente como consta em seu cartão do CNPJ', 194.29, 179.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-m0yutmwvptfl89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F20797925329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
