INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259394636', 'Queijo Mussarela Président', 'O Queijo Mussarela Fatiado Président tem sabor suave, textura macia e fatias sempre soltinhas, perfeito para o preparo de misto quente, lasanhas e diversas outras receitas! Além disso, a embalagem pode ser armazenada fechada na geladeira por até 60 dias, e após aberta, pode ser mantida na mesma embalagem, proporcionando mais praticidade e sabor para o seu dia a dia. *Não contém glúten.', 13.49, 13.49, NULL, 'Food & Beverages > Dairy & Eggs > Cheese & Cheese Powder', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mqneli8a5yj22c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554932%2F58259394636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
