INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298017534', 'Cesto De Roupa Preto 47 L Com Tampa 41 X 31 X 55 Cm', 'Cesto De Roupa Preto 47 L Com Tampa 41 X 31 X 55 Cm Cesto de Roupa Preto 47 L com Tampa 41 x 31 x 55 cmA Cesta de Roupas com Tampa 47 Litros 41 x 31 x 55 cm é perfeita para aliar organização e praticidade no seu dia a dia. São diversas opções cestas com cores que combinam com qualquer ambiente da sua casa. A linha foi desenvolvida priorizando o cuidado com a sua rotina, por isso, possui furos que facilitam a ventilação e bordas maiores que facilitam a pega e transporte. As cestas são produzidas em plástico atóxico (polipropileno) com textura externa para diminuir riscos e arranhões e acabamento fosco na superfície interna. Na lavanderia ou no quarto, para uma casa organizada e com mais cor, as cestas organizadoras são suas aliadas perfeitas para auxiliar no seu dia a dia. Cesto de Roupa Preto 47 L com Tampa 41 x 31 x 55 cm - MedidasMedidas (compr. x larg. x alt.): 41 x 31 x 55 cm Capacidade: 47 litros Cesto de Roupa Preto 47 L com Tampa 41 x 31 x 55 cm - Na sua casa', 122.49, 122.49, NULL, 'Home & Living > Home Organizers > Laundry Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-7rep2-m2civp4ba56oe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23298017534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
