INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250640674', 'Capacete Moto Bieffe Moto X Groovy Old School', 'Moto X Único e despojado Inspirado em competições de motocross da década de 70, o Moto X é um capacete com estilo vintage e elementos modernos que marca presença por onde passa. A pala é acoplada com botões de pressão e seu revestimento interno é produzido em matelassê, oferecendo conforto único. Possui queixeira acentuada com entrada de ar revestida em malha de aço que funciona como um filtro e traz um aspecto ousado para o capacete. Recomendado para passeios urbanos ou off road. Use com óculos de proteção. Características do produto: Gerais: - Casco de alta resistência: produzido com a tecnologia HEAP - High Energy Absorption Polymer; - Revestimento acolchoado: em suede, com acabamento em tecido matelassê, proporcionando mais conforto ao uso. Detalhes na costura em pesponto vermelho; - Sofisticação nos detalhes: cinta com botão de pressão para fixação do óculos na parte traseira do casco. Acompanha pala com fixação por botões de pressão; - Peso: 1268g; - Certificação: NBR7471. Ventilação: - Conforto térmico: entrada de ar frontal e superior com exclusiva malha de aço; exaustão nas laterais.', 599.9, 599.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-821g5-mh2e7bew3ife9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624400687%2F58250640674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
