INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994640068', 'Kit Creme Dental Golgate Total Prevenção Ativa Whitening 4 Unidades 90g Cada', 'Creme Dental Colgate Total Prevenção Ativa Whitening - Leve Mais Pague Menos O creme dental Colgate Total Whitening é seu aliado para limpar e branquear os dentes, deixando um sorriso branco e saudável, graças à sua fórmula desenvolvida para desempenho superior com benefícios preventivos e duradouros que ajuda na remoção de manchas nos dentes. Com escovação 2 vezes ao dia e uso contínuo por 4 semanas. Benefícios: - Pasta dental branqueadora: Creme dental Colgate para uso diário que ajuda a remover manchas nos dentes para manter seu sorriso branco - Cuidados com os dentes: 24 horas de ação contra bactérias com da pasta Colgate Total Whitening. Com escovação 2 vezes ao dia e uso contínuo por 4 semanas. - Saúde bucal: Este creme Colgate é clinicamente comprovado e possui uma fórmula desenvolvida para desempenho superior com benefícios preventivos e duradouros. Creme dental com flúor sem ingrediente antibacteriano. - Dentes saudáveis: Previne problemas bucais antes que apareçam: bactérias nas gengivas, erosão do esmalte, sensibilidade dentária, placa bacteriana, tártaro dental, manchas nos dentes, mau hálito e cárie dental - Sorriso saudável: Tecnología poderosa, patenteada e preventiva para limpar os dentes. Patenteado nos Estados Unidos. - Com o poder do Zinco, protege sua boca de bactérias para uma boa saúde dental. Como Usar? Escove seus dentes adequadamente após cada refeição, três vezes ao dia ou segundo a recomendação de seu dentista. Enxágue completamente depois da escovação. Dicas para cuidados com as gengivas: - Use fio dental diariamente para remover resíduos entre os dentes e evitar irritação nas gengivas. - Escolha escovas de dentes de cerdas macias para evitar danos ao tecido gengival. - Evite alimentos ricos em açúcar e bebidas ácidas, que podem enfraquecer a saúde das gengivas. - Consulte regularmente o dentista para exames e limpezas profissionais. Como Usar? Escove seus dentes adequadamente após cada refeição, três vezes ao dia ou segundo a recomendação de seu dentista. Enxágue completamente depois da escovação.', 43.96, 43.96, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-821dh-mgo474vopcln9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22994640068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40815775598', 'Kit 2 Bermudas Termicas Sem Costura Microfibra Confortavel Para Treino E Atividades Fisicas', 'Bermuda Térmica Delute sem Costura Microfibra Ref. DL001 A Bermuda Térmica Microfibra Sem Costura é a escolha perfeita para os seus treinos e atividades físicas, pois ajuda a manter a temperatura corporal e minimiza a vibração muscular, além de ajudar a evitar assaduras de atrito. Confeccionada com fio de poliamida de alta qualidade com tecnologia Seamless, possui um caimento perfeito, ajustando-se ao seu corpo de forma natural e garantindo máximo conforto e desempenho durante suas atividades. Caracteristicas: - Previne assaduras por atrito. - Tecnologia seamless. - Ajuda a manter a temperatura corporal durante o exercício físico. - Perfeita para uso em Atividades Físicas. Composição: - Poliamida 92% - Elastano 08%', 103.31, 61.99, NULL, 'Men Clothes > Innerwear & Underwear > Thermal Innerwear', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me02i2i5au4j3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800864347%2F40815775598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
