INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798327441', 'Água Micelar Cicatricure 200ml', 'A Água Micelar Cicatricure usa a tecnologia das micelas que agem como imãs, capturando a sujeira, maquiagem e oleosidade, facilmente. Sua fórmula é suave e não possui álcool, além de ser enriquecida com Água de Rosas, que limpa e demaquila desde a primeira passada, removendo até maquiagem à prova d’água, deixando uma sensação de frescor e conforto, sem irritar ou ressecar.', 42.72, 42.72, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-m76ud314pushc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23798327441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
