INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998326555', 'Organizador de Cintos Gravata Relógio 34x10x8 Com 6 Divisórias em Acrílico Para Gavetas e Armário', 'Organizador de Cintos, Gravatas e Relógios 34 cm x 10 cm x 7,5cm com 6 Divisórias em Acrílico Organização e sofisticação para o seu armário. O Organizador Diamond com 6 divisórias é ideal para manter cintos, gravatas, relógios e acessórios sempre organizados, protegidos e de fácil acesso. Fabricado em acrílico cristal, possui design moderno que valoriza o visual da gaveta ou closet, mantendo tudo visível e bem distribuído. Principais Características Tamanho ideal: 34 cm x 10 cm x 7,5cm 6 divisórias individuais, com 1 acessório por compartimento Produzido em acrílico resistente e de fácil limpeza Visual transparente que facilita a visualização dos itens Ideal para gavetas, closets e armários Benefícios Evita que cintos amassem, gravatas se misturem ou relógios risquem. Mantém os acessórios organizados e prontos para uso no dia a dia. Aproveita melhor o espaço interno das gavetas. Perfeito para quem busca praticidade, organização e um acabamento mais elegante no armário. Garanta já o seu e transforme sua rotina com mais organização.', 129.9, 64.9, NULL, 'Home & Living > Home Organizers > Wardrobe Organizers', 'https://cf.shopee.com.br/file/br-11134207-820m7-mp0ssp7d2io6c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316557325%2F22998326555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
