INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51211791545', 'Suporte De Pulso Simples Preto Macio Conforto Antiderrapante Ergonômico Computador Portátil Estudo Escritório Acessórios', '👋👋 Bem-vindo à nossa pequena loja 😊😊 Este é um conjunto de protetores de pulso preto com textura de favo de mel, lançado hoje. Aqui estão algumas características deste produto: ✅ Design simples de cor sólida: este protetor de pulso possui um design simples em preto liso, com aparência discreta e elegante para adicionar um toque de sobriedade à sua mesa. ✅ Base de borracha durável: a base deste protetor de pulso é feita de borracha, o que garante maior durabilidade e possui alguma elasticidade para melhor suporte confortável. ✅ Curva elástica que se adapta ao braço: este protetor de pulso foi projetado com uma curva elástica para se ajustar ao contorno do braço, proporcionando conforto. ✅ Material amigo da pele, respirável e macio: este protetor de pulso é feito de material respirável e amigo da pele, macio e confortável ao toque, além de oferecer suporte ao braço para reduzir a fadiga durante o uso. ✅ Enchimento de esponja para sensação confortável: este protetor de pulso é preenchido com esponja em seu interior, proporcionando uma sensação ainda mais confortável, melhor suporte e amortecimento ao braço, reduzindo a fadiga durante o uso. ✅ Mouse sem travamento e fundo antiderrapante: a superfície do protetor de pulso é lisa e possui um fundo antiderrapante, evitando efetivamente o travamento do mouse e proporcionando uma operação mais suave, além de evitar que o próprio protetor de pulso deslize durante o uso. ✅ Para jogos e trabalho de escritório: este protetor de pulso é adequado para diversas situações, incluindo jogos e trabalho de escritório, proporcionando uma melhor experiência de uso e conforto. 🌈 Em resumo, este protetor de pulso preto possui um design minimalista, durabilidade, suporte confortável, fundo antiderrapante e é adequado tanto para jogos quanto para uso no escritório. 😍 Leve para casa este poderoso e minimalista protetor de pulso agora mesmo! Aguardamos sua compra e ofereceremos o melhor serviço! 🥰', 81.9, 45.84, NULL, 'Computers & Accessories > Peripherals & Accessories > Mouse Pads', 'https://cf.shopee.com.br/file/sg-11134201-823pw-mp7ybi6lv08w24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F51211791545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499494981', 'Truss Uso Obrigatorio - Shampoo 300ml', 'Truss Uso Obrigatorio - Shampoo 300ml Tratamento reconstrutor que chegou para complementar seu ritual de beleza junto ao queridinho Uso Obrigatório;. Limpa suavemente, reduzindo os danos em cabelo com química, hidrata e sela as cutículas. Confere suavidade e brilho aos fios e possui ação antidesbotamento. Claims: Brilho, redução do frizz, selamento das cutículas, color protection e controle da oleosidade. Como Usar Conselho de Aplicação Aplique e massageie, deixe agir por 2 minutos e enxágue. Repita.', 120.49, 118.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-m18kcs1n4fgecf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F20499494981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
