INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22024334885', 'Coifa Do Cambio Vw Passat 1974 Até 1984 C/ Base Preta', 'Coifa Do Cambio Passat 1974 Até 1984 Com Base - Preto. A Coifa da Nat é confeccionada em material ecológico além de possuir a costura reforçada e material em ABS em algumas partes nela, seguimos um rigoroso padrão de fabricação onde é prezado a qualidade e originalidade de encaixe no veiculo. Informações: * Para o Modelo Volkswagen Passat 1974 Até 1984. * Produto Nacional. * Acabamento Sofisticado. * Instalação simples, rápida e intuitiva. * Confeccionado em material ecológico de alta qualidade. * Costura reforçada. Veículos Compatíveis: * Modelo: Volkswagen Golf. * Ano: 1974, 1975, 1976, 1977, 1978, 1979, 1980, 1981, 1982, 1983 e 1984. Dados Técnicos: * Peso: 0,150 kg. * Altura: 25 cm. * Comprimento: 07 cm. * Largura: 15 cm. Cores Disponíveis: * Preto. Conteúdo * 01 Coifa de Alavanca do Câmbio. * 01 Nota Fiscal. Garantia: 3 meses pela Fabrica. * Imagens meramente ilustrativas. Sobre a Marca: A Indústria NAT tem orgulho de ser uma empresa nacional, com sua sede em São Paulo, que está há mais de 20 anos construindo uma história de sucesso no âmbito do desenvolvimento de peças automotivas que acompanham e solucionam as necessidades de consumo do mercado, com o mais alto padrão de qualidade, proporcionando o melhor custo-benefício aos consumidores e sempre buscando ser referência em sua atuação. Seus produtos são produzidos em território nacional e estão presentes em toda América Latina.', 33.9, 22.04, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-23020-d4lrmnzbmjnv73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660182224%2F22024334885', NULL, NULL, '2026-07-28T02:11:31.708458+00: