INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099600196', 'Fita PVC sem Adesivo Hulter HT110BA Branca', 'Fita PVC sem Adesivo Hulter HT110BA Branca Fita De PVC Hulter Branca é usada para proteção, isolamento e acabamento de instalação de ar condicionado. É auto aderente e não adesiva. Ideal para instalações de refrigeração e ar condicionado, previne vazamentos e avarias às tubulações.', 16.9, 16.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rblq-m5ymhuco75vk18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F20099600196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210126607', 'Bis Ao Leite', 'O clássico Bis ao Leite é a combinação perfeita de wafer crocante e chocolate ao leite Lacta, impossível comer um só! Cada embalagem de 100,8g contém 16 unidades embaladas individualmente, perfeito para compartilhar a qualquer hora.', 9.49, 7.79, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqnelal77g26af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F58210126607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19172540486', 'Escapamento Pro Tork Mini 3 [Curva Cromada] Titan 150 Ks/Es 2004/08', 'O Escapamento Mini 3 foi projetado e desenvolvido com tecnologia de primeira linha, este modelo garante respostas mais rápidas da motocicleta, além de produzir um ronco único, sem ultrapassar os limites impostos pelos órgãos de regulação de fabricação. Especificações: - Cores: Azul, Cromado, Dourado, Preto, Prata e vermelho. - Produzido em aço de alta qualidade e resistência; - Modelo: Mini 3. Aplicações: - Titan Ks- Es 150 2004 até 2008. Instalação: - A instalação deve ser feita por um profissional especializado. - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 289.37, 249.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbdyjz2zdrbj31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F19172540486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19422902645', 'Kit Roupa Motocross Calça Insane In Black + Camisa Sportbay Oficial 01 Azul', 'Conteúdo da embalagem: - 1 Camisa; - 1 Calça. Camisa Pro Tork Sportbay Oficial: A Sportbay vem com a inovação no quesito camisa Off Road pois desenvolveu a camisa especialmente para os aventureiros mais exigentes que buscam a união entre o conforto beleza e a máxima proteção durante as trilhas mais difíceis, fabricada em poliéster com grafismos sublimados e modelagem anatômica perfeita. Especificações: - Confeccionada em 100% Poliéster; - Absorve a umidade no corpo para mantê-lo seco e confortável; - Tecido leve que fornece um ajuste preciso sem restringir os movimentos; - Marca: Pro Tork. Dicas: - Recomendamos optar pelo mesmo tamanho utilizado para as camisas casuais. Calça Pro Tork Insane In Black: A Calça Protork Insane In Black é produzida em poliéster 600 fios e elastano. Ela conta com apliques emborrachados estrategicamente posicionados, regulagem na cintura, fechamento por zíper e mais dois botões, costura dupla reforçada, forração interna ventilada, placa de tecido antichama, modelagem anatômica com 13 painéis e articulações elásticas nos joelhos para maior mobilidade. Especificações: - Modelo: Insane In Black; - Confeccionada em Poliéster 600 fios e elastano; - Apliques emborrachados estrategicamente posicionados; - Regulagens na cintura; - Fechamento por zíper e mais dois botões conferindo o ajuste ideal; - Costura dupla reforçada; - Forração interna ventilada; - Placa de tecido antichama na região interna dos joelhos, oferece proteção contra a alta temperatura do motor; - Modelagem ergonômica com 13 painéis; - Articulações elásticas nos joelho; - Marca: Pro Tork Dicas: - Recomendamos optar por um número maior, do que o seu utilizado casualmente, para maior conforto. Exemplo (Se seu número de calça jeans é 38 adquirir o tamanho 40).', 368.21, 239.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/da1641399ef176ac35deba7aca1467fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F19422902645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9353945606', 'Peça de Reposição Capacete Attack Solid Par de Orelhas Laterais Várias Cores Pro Tork', 'Você sempre precisa estar atento ao cuidado com o Capacete, para eventuais quedas resultando em quebra de peças do Capacete, a Pro Tork tem várias peças de reposição incluindo as orelhas laterais Capacete Pro Tork Attack Solid (Par). Especificações: - Cores Disponíveis: AZUL, AZUL ESCURO, BRANCO, PRETO FOSCO e VERMELHO; - Marca: Pro Tork; - Modelo: Attack Solid; - Peça de Reposição; - Valor Referente Ao Par; - Reparo Para Capacete.', 84.11, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljbmdxo0ehit67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F9353945606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14632077774', 'Suporte Farol Aranha Pro Tork Fan 150 2009 - 2015', 'O Suporte para Farol e Aranha do Farol Fan 150 Pro Tork é fabricado em matéria-prima de alta qualidade, garantindo máxima resistência e segurança. Especificações: - Cor: Preto; - Marca: Pro Tork. Aplicação: - Honda Fan 150 2009; - Honda Fan 150 2010; - Honda Fan 150 2011; - Honda Fan 150 2012; - Honda Fan 150 2013; - Honda Fan 150 2014; - Honda Fan 150 2015. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada. A Sportbay não se responsabiliza pela má instalação do produto. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 44.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/b6d32b1e68c5b9f5699fa2b5e316e9c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F14632077774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22395696280', 'Escapamento Escape Gemoto Racing Com Ponteira Para Moto Titan Sport 150 2005 2006 2007 2008', 'O Escapamento Racing Gemoto foi projetado e desenvolvido com tecnologia de primeira linha, este modelo garante respostas mais rápidas da motocicleta, além de produzir um ronco único, sem ultrapassar os limites impostos pelos órgãos de regulação de fabricação. Especificações: - Produzido em aço de alta qualidade e resistência; - Modelo: Racing; - Marca: Gemoto. Aplicações: - TITAN 150 SPORT 2005; - TITAN 150 SPORT 2006; - TITAN 150 SPORT 2007; - TITAN 150 SPORT 2008. Dicas: - A instalação deve ser feita por um profissional especializado. A Gemoto não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 236.74, 214.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md4ozpg3ho1t03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22395696280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392985540', 'Kit Pneu Ira Bunker 90/90-19 + Câmara de Ar Lander/ Bros', 'Kit Pneu Ira Bunker 90/90-19 + Câmara de Ar Lander/ Bros Sobre o Pneu: O Pneu Bunker Adapt da Ira Tires proporciona Controle em qualquer terreno para quem pilota de forma mais arrojada e exige mais do pneu, mesmo em terrenos OFF. Tem desenhos em "V" formam uma "pá" para melhor agarre, principalmente em terrenos OFF. Seus sulcos praticamente horizontais dividem grandes blocos, mantendo áreas de aderência para uso no asfalto. O grandes espaçamentos e sulcos invertidos garantem agarre/tração em curvas fechadas mesmo com lama. Sobre a câmara Federal: As câmaras de ar Federal (By Tortuga), são desenvolvidas com matéria prima de alta qualidade, fabricado por especialistas, caracterizado por mais borracha, maior resistência, mais durabilidade uma alta resistência ao calor. Além disso, conta com o selo de certificação ISO 9001, uma referência internacional em qualidade, um diferencial da empresa. Informações Adicionais do Pneu: - Pneu Ira Bunker 90/90-19 M/c Tt Dianteiro - Necessário uso de Câmara de Ar: Sim - Medida do Aro: 19 - Altura do Pneu: 90 - Largura do Pneu: 90 - Limite de velocidade: 90/90-19: ‹ 150 km/h - Capacidade de carga: 90/90-19: ‹ 200 kg - Garantia de 5 anos contra defeito de fabricação. Informações Adicionais da Câmara: - Medida: M 0519 - Modelo de válvula: TR 4 - Garantia de 3 anos contra defeito de fabricação. Aplicação: - Yamaha: Crosser 150, XTZ 150 Crosser, TDM 225 - Honda: NXR 125 Bros Todas, NXR 150 Bros, NXR 160 Bros, XRE 190 - Traxx: Fly 150, Fly 250 - Shineray: Explorer 150, Discover 250 “POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU ARO', 245.76, 233.48, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5m-lul5dc181veje8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F22392985540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094799986', 'Eudora Kit Batom Glam Micro Plump: Malva Essencial 1,8g + Terracota Retrô 1,8g', 'O Combo Batom Glam Micro Plump entrega em duas cores irresistíveis vários efeitos e benefícios para seus lábios. Com sua poderosa Tecnologia Micro Plump, enriquecida com Bio Hialurônico e Gergelim Oriental, possui maior permeação na pele e efeitos duradouros. Inovador, entrega contorno, definição, efeito micropigmentação e firmeza para seus lábios. MALVA ﻿ O Batom Malva Essencial Glam Micro Plump entrega multiefeitos em um rosa apaixonante que completa qualquer produção com muita sofisticação. Em apenas 5 minutos seus lábios ficam mais volumosos, com efeito matte, semi matte, gloss ou vinílico, alcançado melhores resultados com o uso contínuo de 30 dias. TERRACOTA O Batom Terracota Retrô Glam Micro Plump aumenta o volume dos lábios, enquanto preenche os vincos e as rugas e garante hidratação intensa e firmeza imediata. Em um laranja sofisticado entrega contorno, definição, efeito micropigmentação e resultados duradouros para seus lábios. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 125.98, 125.98, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-82620-mjtyg3rz241y27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F23094799986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205170050', 'Combo Eudora Club 6 Intenso: Desodorante Colônia 95ml + Desodorante Antitranspirante 125ml/75g', 'O Combo Eudora Club 6 Intenso traz uma combinação de itens fundamentais para uma rotina de cuidados masculinos. Idealizado para homens de bom gosto e estilo, os produtos de Club 6 Intenso vão se tornar seus companheiros no dia a dia: DESODORANTE AEROSOL: ﻿ O Desodorante Antitranspirante Club 6 Intenso proporciona uma proteção perfumada com dupla proteção, atuando na desodorização e perfumação do seu corpo. Com 48h de proteção contra mau odor e transpiração, este produto garante mais segurança e autoconfiante para a sua rotina. Além disso, apresenta mais vantagens: -Não contém CFC, sendo inofensivo à camada de ozônio; -Possui cápsulas ativas de fragrância com liberação prolongada. DESODORANTE COLÔNIA: Club 6 Intenso Desodorante Colônia exala bom gosto, estilo e sofisticação. Uma fragrância que traz diferentes ingredientes para te proporcionar a experiência de sentir-se único e exclusivo em meio a tantos. Sua composição traz notas cítricas e especiadas e o exclusivo Cedar Collection, uma coleção de cedros originários de três diferentes regiões do mundo que conferem uma assinatura amadeirada potente à intensa orientalidade da fragrância. Família Olfativa: Oriental Amadeirado. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 203.8, 203.8, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mkmylmm5mo04f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58205170050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203308682', 'Eudora Soul Base Multi 8 em 1 Cor 25 20ml', 'A Base Multi 8 em 1 Soul Eudora é um produto versátil, que veio para revolucionar a sua make e a sua vida. Com efeito soft mate, ela garante brilho, sem deixar a pele oleosa. Além disso, proporciona hidratação por até 12 horas e cor uniformizada o dia todo. O resultado é um rosto macio e hidratado, livre de oleosidade. Conheça outros destaques deste produto incrível: - FPS 15; - Ação antipoluição; - Sensação de refrescância; - Produto cruelty free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 42.99, 39.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-82610-mjhojdfwkp3a0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58203308682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799356714', 'Serra Circular Profissional 1600W 7.1/4 Stanley 220V', 'A Serra Circular Profissional 1600W 7.1/4 Stanley é a ferramenta perfeita para quem busca precisão e potência em cortes de madeira, MDF e outros materiais. Com um motor robusto de 1600 watts e uma lâmina de 7.1/4 polegadas (185 mm), esta serra oferece cortes rápidos e eficientes, garantindo resultados impecáveis em suas tarefas de carpintaria e construção. Sua profundidade de corte ajustável e o ângulo de bisel de até 45 graus permitem realizar cortes angulados e profundos com facilidade, adaptando-se às necessidades de cada projeto. O design ergonômico e a empunhadura emborrachada proporcionam um controle confortável e seguro durante o uso, reduzindo a fadiga e aumentando a precisão. Ideal para profissionais e entusiastas, a Serra Circular Stanley combina robustez e precisão, oferecendo a confiabilidade e o desempenho que você precisa para realizar cortes exatos e de alta qualidade em diversos materiais. Características principais: Potência: 1600 watts Diâmetro da Lâmina: 7.1/4 polegadas (185 mm) Profundidade de Corte: Ajustável para cortes de até 65 mm a 90 graus Ângulo de Bisel: Até 45 graus para cortes angulados Design Ergonômico: Com empunhadura emborrachada para conforto e controle Sistema de Ajuste Rápido: Para profundidade e ângulo de corte Conteúdo: 1 (uma) Serra Circular Profissional 1600W 7.1/4 Stanley 220V 1 (uma) Chave Hexagonal 6mm 1 (um) Guia de corte 1 (um) Manual de instruções 1 (um) Disco de serra com 24 dentes Garantia: Garantia de 2 anos pela fabricante.', 681.9, 584.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-lyp1v0jym1r6cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F21799356714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991248827', 'Fechadura Externa Cromada Paris 2018/09 Hela', 'A Fechadura Externa Cromada Paris 2018/09 da Hela é a combinação perfeita de segurança robusta, durabilidade e elegância contemporânea. Com um acabamento cromado brilhante e um design moderno, esta fechadura é ideal para portas externas, proporcionando proteção confiável e um toque de sofisticação para a entrada de sua residência ou estabelecimento comercial. A Fechadura Externa Cromada Paris Hela é a escolha ideal para quem busca aliar segurança, durabilidade e um design moderno e sofisticado. Perfeita para portas de entrada e externas, esta fechadura proporciona proteção confiável e um visual elegante, sendo um elemento essencial para a segurança e estética de qualquer propriedade. Características Principais: - Design Moderno: Acabamento cromado que oferece um visual contemporâneo e sofisticado, complementando diversos estilos arquitetônicos e decorativos. - Durabilidade: Fabricada com materiais de alta qualidade e resistência, garantindo longa vida útil mesmo em condições climáticas adversas. - Segurança: Equipado com um mecanismo de travamento robusto, projetado para fornecer máxima proteção contra invasões e arrombamentos. - Fácil Instalação: Compatível com portas padrão de madeira ou metal, e inclui todos os acessórios necessários para uma instalação rápida e eficiente. - Ergonomia: Maçaneta desenhada para um manuseio confortável e seguro, oferecendo uma experiência de uso prática e agradável. - Manutenção: Superfície cromada de fácil limpeza e baixa manutenção, mantendo seu aspecto elegante e funcional por muito mais tempo. Aplicações Comuns: - Portas de entrada de residências, garantindo segurança e um visual elegante. - Portas externas de estabelecimentos comerciais como lojas, escritórios e restaurantes. - Portas de áreas de serviço e acessos secundários que necessitam de segurança reforçada. Especificações Técnicas: - Modelo: Paris 2018/09 - Acabamento: Cromado - Material: Liga metálica de alta resistência - Compatibilidade: Portas de madeira ou metal - Espessura da Porta: 30mm a 40mm - Tipo de Fechadura: Externa Dimensões: Maçaneta: 12 cm de comprimento Roseta: Diâmetro de 5 cm Peso: 800 gramas Conteúdo da Embalagem: - 1 Fechadura externa Paris 2018/09 - 2 Maçanetas - 1 Cilindro de segurança com chaves - 1 Conjunto de parafusos e acessórios para instalação - 1 Manual de instalação Garantia: - 1 ano de garantia contra defeitos de fabricação.', 102.9, 68.5, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/sg-11134201-7qvcu-lgxptfu2ocykae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23991248827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43978984336', 'Neutralizador de Odores 500ml Spartan', 'Neutralizador de Odores 500ml Spartan O Spartan Neutra Odor é um neutralizador de maus odores com ação limpadora e desengordurante, indicado para locais com acúmulo de resíduos orgânicos e gordura, como ralos, pias e lixeiras. Sua fórmula contém solvente de fonte renovável e não inflamável e inibidor de maus odores, que remove, emulsifica e solubiliza com eficiência gorduras e oleosidades aderidas nas superfícies, controlando e neutralizando maus odores. Desenvolvido para uso profissional e doméstico, o produto combina eficiência na limpeza com tecnologia de neutralização, sendo ideal para ambientes como cozinhas, banheiros, áreas de lixo e sistemas de esgoto. Indicação de Uso: - Ideal para a limpeza de ralos, lixeiras, abrigos de lixo, caixas de gordura, fossas sépticas , vasos sanitários e áreas com resíduos orgânicos. Diluição: - Neutralização de Odores: Utilizar o produto puro diretamente no local; - Ralos e Pias: Utilize entre 50ml e 100ml do produto puro; - Caixas de Gordura ou Fossas Sépticas: Utilize entre 150ml e 300ml do produto puro; - Abrigos de Lixo ou Lixeiras: 2 tampinhas do produto para 1L de água ou 10ml para 1L de água (1:100); - Limpeza Geral: Diluir 1 parte do produto em 100 partes de água (1:100). Modo de Uso: - Utilize conforme diluição indicada, deixe agir por no mínimo 15 minutos; - Caso o mau odor persista, repita a operação nas dosagens indicadas. Fragrância: Característica PH: 8,0-11,0 Embalagem: 01 frasco de 500ml', 63.58, 63.58, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mlc30vo6i6m876', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F43978984336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597730655', 'Calça Infantil Menino Em Moletom Sem Flanela Malwee Kids', 'Calça infantil confeccionada em moletom sem flanela. Apresentando uma peça com modelagem Tradicional, super confortável para o dia a dia dos meninos. Ela conta com um caimento mais solto na parte de cima e barra ajustada, com cintura em elástico e barra ajustada. Além disso, o moletom é um tecido macio e super confortável perfeito para ser usado nos dias mais frios do ano. O tecido garante aquecimento, estilo e conforto. Aposte com camiseta Malwee Kids! Calça Infantil Em Moletom Sem Flanela Cintura com Elástico Barra Afunilada Situação de Uso: Casual e Dia a Dia.', 69.9, 62.91, NULL, 'Baby & Kids Fashion > Boy Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-lx9vlc4jg5fu4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264817414%2F18597730655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698321203', 'Álcool Em Gel Higienizante Para Mãos Giovanna Baby Classic 60ml', 'O Álcool Em Gel Higienizante Para Mãos Giovanna Baby Classic é um excelente produto para higiene pessoal das mãos, seca instantaneamente, deixando uma sensação de limpeza e toque aveludado com suave perfume, sem ressecar e sem deixar as mãos pegajosas. Vitamina E + esferas hidratantes.', 19.74, 19.74, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd5t-m77fzonat4lu27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23698321203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499467310', 'Desodorante para Pés Tenys-Pé Sabrina Sato Jato Seco 150ml', 'Desodorante Tenys-Pé Sabrina Sato Jato Seco 150ml Antiodor O Desodorante Para Pés Tenys-Pé Baruel Sabrina Sato Jato Seco 150ml foi desenvolvido para quem busca proteção prolongada contra odores e sensação de pés secos ao longo do dia. Possui tecnologia jato seco, que seca rapidamente, não deixa os pés pegajosos e ajuda a manter o conforto em calçados fechados. É ideal para uso diário, principalmente em dias quentes, prática de atividades físicas ou para quem sofre com transpiração excessiva nos pés. Para que serve o Desodorante Para Pés Jato Seco? - Controlar a transpiração dos pés. - Combater o mau odor (chulé). - Manter sensação de pés secos. - Proporcionar frescor ao longo do dia. - Aumentar o conforto ao usar tênis e sapatos fechados. Benefícios e diferenciais: - Ação antitranspirante e antiodor. - Tecnologia jato seco: não molha e não gruda. - Sensação de frescor imediato. - Ideal para uso antes de atividades físicas. - Produto com assinatura Sabrina Sato. Principais ativos: - Agentes antitranspirantes: auxiliam no controle do suor. - Componentes antibacterianos: ajudam a reduzir microorganismos responsáveis pelo mau odor. Como usar o Desodorante para Pés? Agite antes de usar. Aplique o produto a uma distância de 15 cm dos pés. Espere secar antes de calçar meias e/ou calçados. Perguntas frequentes: 1. O Desodorante Tenys-Pé Sabrina Sato Jato Seco evita chulé? Sim. O produto possui agentes que ajudam a controlar a proliferação de bactérias causadoras do mau odor, colaborando significativamente para evitar o chulé quando usado diariamente e com higiene adequada. 2. Pode usar desodorante Tenys-Pé dentro dos sapatos? Sim. Ele pode ser aplicado diretamente nos pés e também dentro dos sapatos e tênis para reforçar a proteção antiodor e garantir sensação de frescor por mais tempo. 3. O Desodorante Tenys-Pé Sabrina Sato deixa os pés molhados? Não. Sua tecnologia jato seco proporciona aplicação rápida e sem umidade, diferente dos sprays tradicionais que podem deixar sensação pegajosa. 4. Quem pode usar o desodorante Tenys-Pé? O produto é indicado para adultos e pode ser utilizado por homens e mulheres. Em caso de crianças ou pessoas com doenças de pele, recomenda-se orientação médica. O Desodorante Para Pés Tenys-Pé Baruel Sabrina Sato Jato Seco 150ml é a escolha certa para quem busca proteção antiodor confiável, ação antitranspirante e conforto diário.', 22.1, 22.1, NULL, 'Beauty > Hand, Foot & Nail Care > Foot Care', 'https://cf.shopee.com.br/file/sg-11134201-823om-mosl9wh32rr6df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23499467310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298311268', 'Sabonete em Barra Dove Branco 90g 6 unidades', 'O Sabonete em Barra Dove Original não é um sabonete comum, é uma barra de beleza feita com tecnologia Syndet, que vai além da limpeza, nutrindo a pele ao mesmo tempo em que remove a sujeira do dia a dia. Sua fórmula com 1/4 de creme hidratante ajuda a repor os nutrientes da pele que podem ser perdidos durante o banho, garantindo 24h de nutrição. O sabonete Dove não retira a hidratação natural da sua pele como os sabonetes em barra comuns, mantendo a sua barreira de proteção natural saudável. Dove Original pode ser usado diariamente no rosto, mãos e no corpo, pois não deixa aquela sensação de pele repuxada e seca. O Sabonete Dove Original é dermatologicamente recomendado. Principais Benefícios: Possui 1/4 de creme hidratante e agentes de limpeza suaves que ajudam a manter a hidratação natural da pele. | 24h de nutrição para a sua pele. | Tecnologia de limpeza Syndet e pH neutro, que ajuda a manter a barreira de proteção natural da sua pele saudável. | Pele macia, bonita e radiante.', 42.52, 42.52, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd4y-m76u7139ndjo15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23298311268', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792994478', 'Máscara Tratamento Loiro Desamarelador Matizador Jacques Janine Blond Yourself 80g', 'A MÁSCARA BLOND YOURSELF É IDEAL PARA CABELOS LOIROS, BRANCOS, DESCOLORIDOS OU COM LUZES. DESENVOLVIDA COM VIOLET FLOWERS COMPLEXE SERISEAL, POSSUI PROPRIEDADES ANTIOXIDANTES E MATIZANTES QUE REDUZEM O TOM AMARELADO DOS CABELOS. SUA FÓRMULA TAMBÉM PROMOVE BRILHOINTENSO, SEDOSIDADE E MACIEZ. Modo de Uso APÓS LAVAR OS CABELOS, APLIQUE A MÁSCARA MECHA A MECHA, DEIXE AGIR DE 5 A 10 MINUTOS E ENXÁGUE. Composição AQUA, CETEARYL ALCOHOL, CETRIMONIUM CHLORIDE, BEHENTRIMONIUM CHLORIDE, ISOPROPYL PALMITATE, PHENOXYETHANOL, ETHYLHEXYLGLYCERIN, BENZYL ALCOHOL, PARFUM, PROPYLENE GLYCOL, LAVANDULA ANGUSTIFOLIA FLOWER/LEAF/STEM EXTRACT, ROSMARINUS OFFICINALIS LEAF EXTRACT, VIOLA ODORATA FLOWER/LEAF EXTRACT, DISODIUM EDTA, BHT, ACID VIOLET 43', 39.9, 32.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvy8qbkbjtea58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23792994478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999649593', 'Hidratante Corporal Monange Q10 Firmador 200ml', 'O novo Hidratante Monange Firmador Q10 com Ação Desodorante e vitamina C e E, aumenta o colágeno da pele, possui ação antissinais e previne a flacidez. Dermatologicamente testado, o produto já começa a dar resultados em até 2 semanas de uso constante, recomenda-se que ele seja aplicado 2 vezes ao dia. Além disso, com ativos provenientes da laranja, o hidratante nutre até a segunda camada da derme, possui uma textura cremosa e pode ser utilizado em todos os tipos de pele.', 27.51, 27.51, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-m77emmvct5akde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F20999649593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799664337', 'Recipiente Moedor Finapod Pro Plus Muse Finamill', 'Recipiente Moedor Finapod Pro Plus Muse Finamill Um moinho, muitos FinaPods! Apenas um Finamill funciona com todos os seus FinaPods. Refil sem bagunça: Abertura com ampla capacidade. Chega de temperos derramados! Design durável: Os elementos de moagem de cerâmica patenteados duram anos. Ajustável sem esforço: Gire o botão de ajuste para controlar o tamanho da moagem para cada tempero. Organize, armazene e empilhe temperos em seus próprios FinaPods dedicados para facilitar a organização.Sucesso entre os especialistas e vencedor de 3 prêmios!! FinaMill obteve sucesso entre os especialistas: -Super fácil de usar e confiável. (Forbes)-Design engenhoso. (Boston Globe)-Revolucione a maneira como você prepara a comida. (Mashable)Seu design elegante e minimalista já ganhou alguns prêmios como o Red Dot em 2022 e o Best of Europe Product 2023.Especificações do produto:- Moa com precisão: ideal para temperos oleosos e do dia a dia, como sal marinho, pimenta-do-reino, cardamomo, cominho e muito mais- Recarga sem bagunça: o design de abertura ampla garante recarga fácil e sem derramamentos- Controle facilmente o tamanho da moagem com um simples giro do botão de ajuste- Lavar à mão com esponja macia e produtos não abrasivos- Não vai a lava louçasFicha técnica:- Código: 4083120012- Marca: FinaMill- Modelo: Pro Plus Muse- Conteúdo da Embalagem: 1 Finapod- Peso: 0,08kg- Dimensões: 7,54cm x 7,63cm x 7,63cm (AxLxP)- Garantia: 2 anos de garantia Altura - 7,54cm Largura - 7,63 Profundidade - 7,63 Peso - 0,08kg Sobre a Marca - A Finamill é uma marca inovadora que transforma o modo como você utiliza especiarias na cozinha. Focada em praticidade e tecnologia, a Finamill desenvolveu um moedor elétrico que permite moer diversos tipos de grãos e especiarias frescas em segundos. O diferencial da Finamill está em seu sistema de cápsulas de moagem intercambiáveis, que facilita a troca rápida de temperos sem mistura de sabores. Com um design ergonômico e fácil de usar, a Finamill é ideal tanto para chefs profissionais quanto para cozinheiros em casa que buscam otimizar suas receitas com frescor e sabor intenso.', 89.9, 89.9, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-7rd63-m7gq5v7f440ocb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F20799664337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897804865', 'Kit 04 Banquetas Cozinha Americana Bancada Giratória Alta Preta', 'Kit 04 Banquetas Cozinha Americana Bancada Giratória Alta Preta Banqueta Gomos A banqueta gomos tem um designer arrojado que proporciona modernidade e beleza ao ambiente. Reforçada e de fácil limpeza. Ideal para bancadas, bares, espaço gourmets e churrasqueiras. Material da Estrutura: Base em aço cromado com regulagem de altura acionado por pistão à gás. Material do Assento: Almofadado Garantia de 3 meses por defeito de fabricação. Altura Máxima considerando o encosto: 113 cm Altura Mínima considerando o encosto: 92 cm Altura mínima até a base do assento: 61 cm Altura máxima até a base do assento: 82 cm Largura interna do assento: 45 cm Profundidade interna do assento: 40 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 6,8 kgs - Giratória - Não Dobrável - Não Empilhável Indicações de Uso: - Não utilizar produtos químicos e abrasivos para limpeza - Limpar com pano umedecido e sabão neutro para melhor conservação - Para uma melhor conservação, aplicar cera automotiva nas partes cromadas Observações importantes: - Produto Enviado: Desmontado - Complexidade de Montagem: Fácil - Manual de Montagem: Acompanha o produto - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. - O produto é enviado desmontado. Portanto, necessita montagem após recebimento. Acompanha Manual.', 1599.0, 1599.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvv-lzqs1la25atj11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%