INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10669570827', 'Carga Gillette Mach3 Leve 8 Pague 6', 'Carga Gillette Mach3 Continua usando descartáveis? Está na hora de mudar para um aparelho de barbear de verdade. Gillette MACH3. Dura até 2x mais do que a descartável líder. Após 10 utilizações, continua a melhor do que uma descartável nova. Experimente o Gel de Barbear MACH3 para um barbear perfeito. *Melhor do que um descartável, mesmo após 15 utilizações. *Cabeça móvel que se ajusta aos contornos da pele. *Fita lubrificante para proteger contra a irritação. *Lâminas mais afiadas montadas individualmente sobre molas para um conforto duradouro duas primeiras lâminas comparado ao Prestobarba 3. *Todas as recargas MACH3 podem ser utilizadas com qualquer máquina de barbear MACH3. *Dez (10) microtensores que alisam a pele para um barbear uniforme e sem esforço. Contém: Carga Gillette Mach3 Leve 8 Pague 6 *Compre Produtos Gillette.', 119.99, 108.99, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/cf97d1df9c3acccf0452576ab6dccc02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F10669570827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099245304', 'Diver Surprise My Pet Faz Xixi Acess. Surpresas - Divertoys', 'Chegaram os pets das bonecas mais queridas e estilosas do momento! Agora você pode comprar o companheiro ideal para a sua boneca favorita. É cada um mais lindo que o outro, que você pode escolher entre a cachorrinha, o unicórnio, a coelhinha e a gatinha. Eles acompanham três acessórios surpresa! Um desses acessórios é o copinho. Será uma caixinha de leite? Copo de café? Ou uma garrafinha de suco? E você ainda poderá dar água para o seu querido pet e ele fará xixi de verdade! Chegou a hora de se divertir com esse lançamento incrível e escolher o pet que mais combina com você. ATENÇÃO: Os acessórios são SURPRESA, sendo impossível escolher. Especificações: Fabricante: Divertoys Ref.: 8226 Cód. Barras: 7898639382269 Idade recomendada: +03 anos. Dimensões da embalagem (AxLxC) 25 x 23 x 10cm Peso: 600g Garantia do vendedor: 7 dias Garantia do fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 119.99, 119.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu8914b9p0usc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F19099245304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799358671', 'Curativo Nexcare Micropore com 35 Unidades 3M', '- Possuem tecnologia Micropore, que permite que a pele respire - Almofada que não adere a ferida - Discretos - Facil Remoção - Almofada que não adere à ferida Com almofadas que não aderem à ferida, os Curativos Feitos de Micropore Nexcare são discretos e desenvolvidos para cobrir e proteger pequenos ferimentos, promovendo o melhor ambiente para a cicatrização sem causar novos machucados. Com tecnologia Micropore®, permitem que a pele respire. Que o curativo não cause outra ferida! Os Curativos Feitos de Micropore Nexcare são desenvolvidos para cobrir e proteger pequenos ferimentos, promovendo o melhor ambiente para a cicatrização sem causar novos machucados. Essenciais para qualquer kit de primeiros socorros, os curativos 3M são perfeitos para o tratamento de pequenas feridas como cortes, arranhões, escoriações e bolhas. Além de discretos, os Curativos Feitos de Micropore Nexcare são confortáveis e feitos com tecnologia Micropore, que permite que a pele transpire. Ideais para peles sensíveis e frágeis e para uso prolongado, os curativos adesivos possuem almofada que não adere à ferida e são mais fáceis de serem removidos. Para aplicar o curativo Nexcare, retire-o e aplique sob a pele. Depois, remova o excesso. Acompanhe o progresso da sua ferida a cada quatro dias, e aplique um novo curativo se necessário. Aplicações sugeridas Cobrem e protegem pequenos ferimentos como cortes, arranhões, escoriações e bolhas Tipo de curativo ideal para peles sensíveis e frágeis e para curativos de uso prolongado', 19.9, 19.9, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-lyy1woaikrl630', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F132871