INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45410761566', 'Tênis Ramarim Chuncky Feminino 25-90131 Casual Ultraconforto Original', 'É produção estilosa que você busca? Marque presença com o Tênis Ramarim Chuncky, perfeito para todas as ocasiões. Garante conforto e qualidade. Confeccionado em material resistente, tem solado emborrachado, palmilha macia e fechamento por cadarço ajustável. Esse tênis casual exibe design moderno com detalhes bicolor e costura reforçada. O artigo garante melhor respirabilidade aos pés. Dica: Combine com produções casuais ou esportivas – short jeans, calça legging ou calça jeans. Você merece as melhores escolhas. Garanta já o seu!', 349.9, 167.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820mh-moh92otjzsw02e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F45410761566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45606013893', 'Chinelo Vizzano Flat Spikes Feminino - Off White', 'Leve as cores desta temporada ao seu estilo com o Chinelo Vizzano Flat Feminino, que tem design flatform e se destaca pelo conforto. Este modelo conta com apliques nas tiras para levar um charme especial ao seu visual. Garanta o seu!', 159.9, 149.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-825zk-mki51e7ipds201', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F45606013893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499196628', 'Coala Essências - Limpador Perfumado de Ambientes Alecrim 120 ml', 'COALA ESSÊNCIAS - LIMPADOR PERFUMADO DE AMBIENTES ALECRIM 120 ml Descrição Com Coala Essências - Limpador Perfumado de Ambientes Alecrim, seu ambiente vai ficar limpo e com um aroma incrível. Além de poder ser usada em todos os ambientes, a Coala Essências - Limpador Perfumado de Ambientes Alecrim também: - Garante a sensação prolongada de limpeza e bem-estar; - Tem perfume duradouro, - Fragrância agradável. Modo de usar Diluir 8 gotas da Essência Limpadora concentrada em 1 litro de água e com o pano úmido e passar sobre a superfície desejada. Precauções Testar o produto em uma pequena área antes do uso, para evitar possíveis manchas. Manter o produto em sua embalagem original, sempre fechada. Guardar sob abrigo da luz do sol, pois o calor excessivo pode danificar o produto e sua eficácia. Além disso, é importante manter fora do alcance de crianças e animais de estimação. Perguntas frequentes O que significa "concentrada"? O termo concentrada significa que antes de usar essa Essência Limpadora ela deve ser diluída em água. Com isso, você tem economia, pois o produto rende e dura mais, com o mesmo efeito que uma fórmula tradicional teria. Quais cuidados devo ter? Testar o produto em uma pequena área antes do uso para evitar possíveis manchas. Manter o produto em um ambiente que não recebe luz solar direta, pois o calor excessivo pode danificar o produto e sua eficácia. Além disso, é importante guardar em um local fora do alcance de crianças e de animais de estimação. Ficha Técnica Nome do Produto: Coala Essências - Limpador Perfumado de Ambientes Alecrim 120 ml Volume: 120 Militros Marca: Coala Essências Aromáticas Número de unidades: 1', 17.9, 16.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rcdf-lslnbf4kfp1b66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F20499196628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29489597267', 'Camiseta São Paulo RetrôMania 1994 Listrada Masculina - Vermelho e Preto', 'Reviva conquistas! Esta Camiseta São Paulo RetrôMania 1994 é ideal para mostrar seu amor pela história do Clube da Fé. Com design inspirado no manto histórico de 1994, a camisa retrô São Paulo revive a conquista da Copa Conmebol, quando o Expressinho Tricolor bateu o Penãrol na épica final. O estilo clássico traz a essência daquele time, enquanto as listras em vermelho, branco e preto mantêm a tradição. Por fim, os detalhes e o escudo bordado elevam seu estilo ao máximo. Leve a essência com você e celebre um passado glorioso. Compre sua camiseta São Paulo masculina!', 229.9, 199.9, NULL, 'Men Clothes > Tops > Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rdvu-md4zj2z14dtld2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F29489597267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599116005', 'Liqui Moly Oil Additiv Aditivo Condicionador Metais Mos2 Molibdénio 300ml', 'Liqui Moly Oil Additiv Descrição Aditivo de motor com base em disulfeto de molibdénio (MoS2). Esta suspensão forma em todas as superfícies de fricção e deslizantes uma película lubrificante de elevada resistência. Deste modo reduz-se o atrito, garante-se uma performance mais suave dos grupos e é possível um maior rendimento do motor. Testado para turbo e catalisador. Características - Reduz o consumo de óleo e de combustível - Reduz o desgaste durante o funcionamento - Sem formação de depósitos - Máxima estabilidade térmica - Totalmente permeável em filtros - Misturável com todos os óleos de motor à venda no mercado - Aumenta a suavidade de funcionamento Campos de Utilização Adicionar ao óleo lubrificante de motores, compressores, bombas, especialmente para motores de veículos (motores a gasolina, flex, GNV e diesel). É possível a mistura com todos os óleos para motores à venda no mercado. Aplicação Adicionar 5% de Oil Additiv ao óleo para motores (50 ml por litro de óleo). Em motocicletas com embreagens em banho de óleo, adicionar 2% (20 ml por litro de óleo). Pode ser adicionado ao óleo para motores a qualquer momento. Agitar antes de utilizar.', 362.76, 181.38, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8259u-mg8aaha7dix723', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984422268%2F23599116005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55203287292', 'Boneco Funko Pop! Bob Esponja O Filme - Bob Esponja Fantasma', 'Adicione diversão e nostalgia à sua coleção com o Boneco Funko Pop! Bob Esponja Fantasma. Inspirado no filme icônico, este colecionável em vinil retrata Bob Esponja em sua versão fantasmagórica, com detalhes fiéis ao personagem. Com aproximadamente 9,5 cm de altura, é ideal para fãs de Bob Esponja e colecionadores Funko que desejam completar sua linha de personagens do universo submarino mais amado do entretenimento infantil.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-81ztg-mienz537ykn5a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F55203287292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57104537134', 'BODY SPLASH FEMININO VAKINHA AO LEITE 200ML - PRIMACIAL PERFUME GOURMAND', 'Body Splash Vakinha Ao Leite 200ml Perfume Feminino Gourmand | Perfume Feminino Doce Cremoso Uma fragrância que lembra leite cremoso misturado com chocolate ao leite, criando um aroma suave, aconchegante e extremamente confortável. Não é aquele doce pesado, é um cheiro macio, envolvente e delicado, que dá sensação de pele cuidada e cheirosa o tempo todo. Logo na primeira borrifada, aparece o toque cremoso do leite com um fundo levemente achocolatado. Aos poucos, a baunilha entra trazendo ainda mais conforto, enquanto o musk deixa um rastro limpo, aveludado e viciante. Perfeito para quem ama fragrâncias doces, mas quer algo suave, elegante e fácil de usar no dia a dia. Pirâmide Olfativa: Topo: Leite Fresco, Chocolate ao Leite Coração: Baunilha, Cacau Suave Fundo: Musk Aveludado, Notas Cremosas Quando Usar: 🌤️ Dia: Excelente 🌙 Noite: Muito bom 🍁 Melhor desempenho em clima ameno ou dias mais frescos 📦 Detalhes do Produto: ✔ Conteúdo: 200ml ✔ Body splash feminino doce e cremoso ✔ Fixação leve a moderada ✔ Ideal para reaplicar ao longo do dia ✔ Fragrância confortável e envolvente 💡 Dica de uso: Aplique após o banho e reaplique ao longo do dia para manter a pele sempre perfumada e destacar o efeito cremoso da fragrância.', 99.9, 64.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mje667vos9ojef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F57104537134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794222063', 'Pistola Airsoft Spring Gk-v307 + Bbs Combat 500 0,20g', 'Pistola Airsoft Spring Gk-v307 + BBs Combat 500 0,20g Modelo com ação Spring(mola) onde é necessário movimentar o slide para frente e para trás antes de apertar o gatilho para efetuar os disparos. Fabricada em polímero de alta densidade, Essa glock é indicada para lazer ou até mesmo coleção com excelente custo benefício para você! Você pode utilizar esferas plásticas BBs 0,12g para que tenha um alcance maior nos disparos. O magazine também é em polímero e possui capacidade para até 11 bbs. Características: - Calibre: 6mm - Marca: Vigor - Modelo: Glock GK-V307 - Código: 25207668 - Ação: Spring (mola) - Modo de disparo: Mono tiro - Velocidade: 150 fps/ 45 m/s* (0,20g) - Capacidade magazine: 11 rounds - Peso: 230g - Tamanho do Cano: 190 mm - Diâmetro do cano: 6,08 mm - Massa de mira: Fixa - Alça de mira: Fixa - Material: Polímero - Cor: Preta - Ponteira laranja: Polímero - Hop up: fixo - Trava de segurança: Não possui Itens Inclusos: - 1x Pistola Spring Vigor Glock GK-V307 Airsoft - 1x Magazine - 1x Pacote com 500 BBs 0,20g Combat Airsoft - 1x Nota Fiscal Informações Adicionais: - As imagens são meramente ilustrativas - Este produto deve ser transportado com sua nota fiscal - A venda deste produto é destinada apenas a maiores de 18 anos', 156.8, 141.12, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdxh-mc9az3ckw0uz22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F618731843%2F23794222063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593937386', 'Ração Quatree Supreme Dermasense Cães Adultos - 15Kg', 'Ração Quatree Supreme Dermasense Cães Adultos - 15Kg A Ração Quatree Supreme Dermasense Cães Adultos é um alimento premium especial desenvolvido para cães adultos de raças médias e grandes, com fórmula avançada à base de cordeiro e salmão, combinados com mandioca e maçã. Elaborada com proteínas selecionadas e ingredientes de alta digestibilidade, contribui para o bem-estar gastrointestinal, nutrição equilibrada e suporte à saúde da pele e da pelagem, oferecendo uma alimentação completa para o dia a dia do seu pet. Benefícios: Indicada para cães adultos de raças médias e grandes Fórmula com cordeiro e salmão, com proteínas selecionadas e de fácil digestão Auxilia no aproveitamento eficiente dos nutrientes Contribui para o bem-estar gastrointestinal Contém prebióticos, probióticos e beta-glucanas Possui fonte de EPA e DHA Enriquecida com vitaminas, minerais e taurina Conta com ingredientes naturais na composição Livre de ingredientes transgênicos Sem antioxidantes artificiais BHT e BHA Ajuda no cuidado da pele e da pelagem Alimento completo e balanceado para a rotina do animal Especificações: Marca: Quatree Supreme Produto: Dermasense adultos raças médias e grandes Princípio ativo: Não se aplica Categoria: Alimento completo para cães Indicação: Cães adultos de raças médias e grandes Porte recomendado: Médio e grande Idade recomendada: Adultos Material: Ração seca Peso/Volume: 15kg Apresentação: Saco de 15kg Formato de venda: Unidade Observações Importantes: Fornecer conforme a recomendação diária indicada na embalagem Realizar a transição alimentar de forma gradual Manter água limpa e fresca sempre disponível Conservar a embalagem em local seco, fresco e arejado Após aberto, manter o produto bem fechado para melhor conservação Em caso de necessidades nutricionais específicas, consulte o médico-veterinário Produto não substitui orientação profissional', 299.99, 299.99, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-820l4-mnyhxbbshg5d18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23593937386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43661650529', 'Espelho Grande do Pinterest Retrô Corpo Inteiro 110x60cm Moldura Couro 3cm para Banheiro Mod Curves', 'Apresentamos o espelho Curves de 110x60 cm, uma peça que se distingue por sua elegância contemporânea e funcionalidade excepcional. Ideal para adicionar um toque de sofisticação a qualquer espaço, este espelho é perfeito tanto para ambientes residenciais quanto comerciais, complementando a decoração com um design moderno e refinado. O espelho Curves é projetado com atenção meticulosa aos detalhes, garantindo qualidade e estilo superiores. Sua estrutura é composta de EVA reforçado, proporcionando durabilidade e leveza, enquanto a borda em couro ecológico, disponível nas cores preto, caramelo, gelo e café, oferece um acabamento sofisticado. Este modelo, diferentemente de outros, não possui costura dupla, conferindo-lhe uma aparência mais suave e minimalista. A instalação deste espelho é prática e segura, graças à chapinha metálica que já acompanha o produto. Este sistema de fixação garante que o espelho fique firmemente instalado, proporcionando tranquilidade e estabilidade. Este espelho é a escolha perfeita para aqueles que buscam uma peça versátil e estilosa, capaz de transformar qualquer espaço em um ambiente de bom gosto e modernidade. Seja em uma sala de estar, corredor ou escritório, o espelho Curves se integra harmoniosamente, oferecendo não apenas funcionalidade, mas também um elemento decorativo impressionante. ESPECIFICAÇÕES TÉCNICAS Marca: Rei dos Vidros Modelo: Curves 110x60 cm Espelho: Guardian Estrutura: EVA reforçado com borda em couro ecológico Formato do espelho: Retangular Medidas: 110x60 cm CORES DISPONÍVEIS Preto Caramelo Gelo Café GARANTIA Oferecemos uma garantia de 100% contra defeitos de fabricação por 90 dias, cobrindo quaisquer imperfeições como manchas no espelho, defeitos no couro ou distorções na imagem refletida. PERGUNTAS FREQUENTES Como é garantida a entrega do espelho? E se ele chegar danificado? Asseguramos que o espelho será entregue em perfeitas condições. Se houver qualquer dano durante o transporte, enviaremos um novo espelho prontamente. Nossa embalagem é projetada para proteger o produto durante o envio, garantindo segurança e integridade na entrega em qualquer região do Brasil. Qual é a espessura do espelho? O espelho tem espessura de 3 mm, utilizando a renomada marca Guardian para garantir durabilidade e qualidade superior. Qual é a composição da borda do espelho? A borda é feita de couro ecológico, proporcionando uma aparência elegante e sofisticada. Como é feita a instalação do espelho? A instalação é simplificada por uma chapinha metálica que acompanha o espelho, garantindo uma fixação segura e estável na parede. Qual é o tamanho do espelho? O espelho possui dimensões de 110x60 cm, proporcionando uma ampla área de reflexão. Como é calculado o prazo de entrega? O prazo de entrega depende da sua localização. Ao contratar o frete, você receberá uma estimativa de tempo de entrega fornecida pela transportadora. Ainda tem dúvidas? Estamos sempre prontos para ajudar! Envie suas perguntas e teremos prazer em respondê-las :-)', 399.9, 144.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81z1k-min2o3j524g11d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F599271358%2F43661650529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55159125220', 'Lovito Blusa Casual Detalhe Gola Moda Feminina BRBLB1287BRL1318', '✅DESTAQUES -❤️Fresco - Confortável ✅DESCRIÇÕES Estampa: Liso Coleção: Ano Todo Tamanho Plus: Não Composição: Poliester 96% 4%Elastano Tipo de Modelagem: Top Transparência: Não Elasticidade: Alta Região de Origem: Brasil ✅O PACOTE INCLUI 1 Top ✅INTRODUÇÃO À LOVITO A Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas elegantes e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 44.9, 24.9, NULL, 'Women Clothes > Tops > Tanks & Camisoles', 'https://cf.shopee.com.br/file/br-11134207-820mb-mnlh8ptetlhe90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F55159125220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
