INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23120968384', 'Lenço Umedecido PetMais Cães Macho Azul Com 75 Unidades', '- Indicado para cães; - Auxilia na higiene do seu cão, de forma prática; - Hidrata e limpa a pele do animal; - Com um grande potencial de limpeza e desengordurante; - Ideal para banhos a seco em filhotes que ainda não podem tomar banho; - Tamanho do lenço: 19cm x 11,5cm. O Lenços Umedecidos é especialmente formulado para uma rápida e eficiente higienização de cães machos. Ideal para cães que dormem na cama do dono, de forma prática e higiênica, produto com alto poder bactericida, desinfeta e hidrata a pele do animal. O lenço umedecido é ideal para limpeza da pele, pelos, orelhas, focinho, patas, após o xixi e o cocô principalmente após os passeios na rua, em animais que sobem nos sofás e camas. Recomendamos para manter a higiene entre os banhos, nos filhotes antes das vacinas, nos pós-operatórios, em cães idosos, em viagens, nos dias frios e chuvosos. São descartáveis, higienizam e perfumam suavemente seu amiguinho. Modo de usar Retire a tampa e remova o lacre de proteção, puxe o lenço a partir do centro, passe a ponta pelo orifício na tampa e feche novamente. Retire um a um os Lenços Umedecidos e passe nas áreas que deseja limpar. Jogue os lenços utilizados no lixo e após o uso feche a tampa para conservar a umidade.', 14.9, 11.92, NULL, 'Mom & Baby > Bath & Body Care > Wipes', 'https://cf.shopee.com.br/file/sg-11134201-23020-dog8yabzkzmv2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F23120968384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
