INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799197892', 'Limpa Freios e Peças Desengraxante Anti Ruidos Limpa Peças Motor Óleo Rodas W-max', 'O Limpa Freios e Peças W-Max é um desengraxante com alto poder de limpeza. Limpa e desengraxa peças em geral sem deixar resíduos. Características: - À base de solvente orgânico de alto poder de limpeza; - Altamente volátil (secagem rápida) e com baixo odor; - Não precisa de enxágue para limpeza da peça; - Rápida eliminação de óleo, graxa, fuligem e resíduos oleosos que causam ruídos; - Isento de silicone; - Isento de Acetona. Principais Vantagens: - Limpa sem danificar peças plásticas, borrachas e partes elétricas, sem deixar resíduos; - Seca em segundos; - Reduz o tempo de operação; - Não danifica peças pintadas; - Produto com alta pressão (jato forte) que auxilia na remoção da sujeira; - Aumenta a eficiência da frenagem. Nuvem de Tags: Limpa Freios, Limpeza de Freios, Desengraxante de Freios, Sistema de Freios, Limpeza De Peças, Spray p/ Manutenção, Wurth, W-max.', 54.9, 47.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrsszzxg5fz818', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F20799197892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
