INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46158371344', '10 SACOLA GRANDE 23X27 CHARMOSA 4129 ( DIA DAS MÃES JANGO 2026 ) OUTLET', 'INFORMAÇÕES IMPORTANTES E DICAS DE USO ✔ Acompanha alças resistentes Proporcionam praticidade e segurança no transporte, além de valorizar a apresentação do seu produto. ✔ Produto enviado desmontado A sacola é enviada desmontada para reduzir custos com frete e evitar avarias no transporte. A montagem é simples e rápida. ✔ Perfeita para valorizar seus produtos ✔ Material ideal para datas sazonais e presentes Ótima opção para lembranças especiais, presentes personalizados e kits gourmet. ✔ Imagens e vídeos disponíveis para divulgação Todo o material visual deste anúncio pode ser baixado e utilizado livremente para promover seus produtos. ⚠ Imagens meramente ilustrativas O produto refere-se somente à embalagem. Não acompanha doces ou acessórios decorativos. Não recomendamos acomodar: ✖ Produtos acima de 23cm de largura ✖ Produtos acima de 27 cm de altura ✖ Produtos acima de 1,2 kg ? Dica de apresentação: Utilize papel de seda, tags ou laços para deixar a embalagem ainda mais sofisticada e segura durante o transporte. ⚠ Atenção aos prazos de entrega Recomendamos sempre considerar o prazo das transportadoras ao programar sua produção, especialmente em períodos de alta demanda. ⚠ Atenção: As cores do produto podem sofrer pequenas variações devido à configuração da tela do seu dispositivo Altura: 27,00 cm Largura: 23,00 cm Comprimento: 26,00 cm', 75.85, 75.85, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/sg-11134201-81zum-mn2ruo0f3ls51a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F46158371344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
