INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4382469474', 'Correia Alternador Ford Fusion 2.3 16v 2008 Continental', 'Correia alternador Ford Fusion 2.3 16v 2008 - Continental Contitech - A correia Poly V da linha Elite® apresenta um novo estilo de ranhura na diagonal e novos materiais na sua fabricação. Os resultados obtidos por cada um desses importantíssimos detalhes faz com que o produto final apresente um desempenho incomparável com modelos anteriores. A performance da correia Poly V nas mais severas condições de trabalho é evidente pela: Maior flexibilidade e menor temperatura de trabalho Durabilidade - maior vida útil Maior Flexibilidade Melhor Abraçamento Menor Temperatura de Trabalho Maior Durabilidade Redução de Trincas Prematuras Operação Silenciosa Intercambialidade', 129.9, 129.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdlqdhvylqk9c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353894917%2F4382469474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192485098', 'AGUA SAN PELLEGRINO MINERAL COM GÁS 750ML', 'Você está comprando: AGUA SAN PELLEGRINO MINERAL COM GÁS 750MLPaís de origem: ItáliaSOBRE O PRODUTO: Água de perfil aromático, discreto e efervescência delicada. Ideal para ser servida com vinho tinto. Reverenciada como o Champagne das águas minerais, a água italiana S. Pellegrino é conhecida em todo o mundo como simbolo de vida italiano ("Nazionalitá"). Sua fonte está localizada a 70 km de Milão, na cidade de S.Pellegrino Terme, região da Lombardia, norte da Itália. Começou a ser engarrafada em 1899 e décadas depois vem se consolidando como a água preferida dos grandes Chefs e Sommeliers do mundo, além de ser parceira dos melhores prêmios de gastronomia do mundo. Com sua "perlage" (borbulhas) delicadas e equilibradas, acompanha e valoriza vinhos tintos e pratos a base de carne e molhos intensos.', 53.58, 53.58, NULL, 'Food & Beverages > Beverages > Water', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-lm7qz05dtbrkcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F22192485098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41470754073', 'Cadeira de alimentação bebê portátil 3 em 1 Styll Baby Seggura cadeirão Infantil Desmontável', 'Cadeira de Alimentação Infantil 3 em 1 STYLL BABY A Cadeira de Alimentação Infantil 3 em 1 Styll Baby foi desenvolvida para acompanhar o crescimento da criança e facilitar o dia a dia dos pais. Com design moderno, prático e seguro, ela oferece 3 formas de uso em um único produto: Cadeira Alta – ideal para as refeições à mesa junto com a família. Booster Portátil – pode ser fixado em cadeiras comuns, permitindo o uso em qualquer ambiente. Cadeirinha Infantil – adaptada para brincadeiras e momentos de lazer, oferecendo conforto e praticidade. Indicada para crianças a partir de 6 meses até 23 kg, essa cadeira é versátil e se ajusta às diferentes fases da infância, garantindo conforto e segurança em todas as etapas. Segurança e Conforto Possui cinto de segurança de 5 pontos, que mantém a criança firme e bem protegida. Conta com barreira entre pernas, evitando que a criança escorregue. O apoio para os pés é removível e regulável em até 2 posições, trazendo ergonomia durante o uso. A bandeja oferece 3 opções de ajuste, acompanhando o crescimento da criança. Praticidade e Funcionalidade Acompanha tiras com fivelas, permitindo prender o assento em cadeiras comuns para uso como booster. Estrutura resistente em aço e plástico de alta qualidade, garantindo durabilidade. Fácil de montar e de limpar, ideal para o dia a dia corrido das famílias. Produto aprovado pelo INMETRO, atendendo às normas de segurança (ABNT NBR 15991). Especificações Técnicas Idade recomendada: a partir de 6 meses Peso máximo suportado: 23 kg Funções: Cadeira Alta, Booster de Alimentação e Cadeira Infantil Material: aço e plástico resistente Altura aberta (Cadeira Alta): 86 cm Altura aberta (Cadeira Infantil): 48 cm Altura aberta (Booster): 36,5 cm Certificação INMETRO: Nº registro 013509/2024 Conteúdo da embalagem: 1 cadeira de alimentação Styll Baby Marca: Styll Baby Produto original, com nota fiscal e garantia. Certificado pelo INMETRO, garantindo segurança. Versátil e ajustável, acompanha as diferentes fases da infância. Design moderno, funcional e de fácil higienização.', 350.9, 229.9, NULL, 'Mom & Baby > Feeding Essentials > Highchairs & Booster Seats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meznpd96r9qd5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504754787%2F41470754073', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
