INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993175994', 'Armário de Cozinha Kit 6 Portas e Genova Kits Paraná', 'Kit Cozinha Gênova 6 Portas e 1 Gaveta – Cor Nogueira Off White | Kits ParanáO Kit Cozinha Gênova será o charme da sua cozinha. Com um design diferenciado, ele conta com um nicho decorativo superior, ideal para acomodar vasos, flores e outros itens decorativos. Dimensões do ProdutoAltura: 176 cm Largura: 121,5 cm Profundidade: 26,1 cm Peso Total: 42,95 kg Características e Especificações TécnicasModelo: Gênova Material: MDP 12 mm e 15 mm Ambiente de Uso: Cozinha Quantidade de Portas: 6 (em MDP, com abertura por batente e dobradiças metálicas) Quantidade de Gavetas: 1 (com corrediça metálica tipo trilha) Possui Prateleiras: Sim (em MDP 12 mm) Possui Pés: Sim (5 pés em polipropileno, cor nogueira) Possui Puxadores: Sim (7 puxadores em polipropileno, cor nogueira) Inclui Tampo: Sim Tipo de Pintura: Ultra Violeta Acabamento Externo: Verniz alto brilho Peso Suportado Total: 60 kg Necessita Fixação na Parede: Não Fabricante: Kits Paraná Garantia do Fabricante: 90 dias EntregaO produto será entregue em 2 volumes Manutenção e LimpezaUtilize um pano levemente umedecido com água, seguido de um pano seco. Evite exposição direta ao sol para prevenir alterações na cor. Não utilize escovas ou produtos abrasivos. Observações ImportantesMontagem e desmontagem: não estão inclusas no valor do produto e devem ser feitas por um profissional qualificado. Transporte e entrega: Certifique-se de que as dimensões do produto são compatíveis com elevadores, portas e corredores do local da entrega. Não realizamos transporte via escada, içamento externo ou desmontagem de portas e janelas. Para edifícios e condomínios, a entrega será realizada na portaria. Recebimento do produto: Verifique as condições da embalagem antes de assinar o comprovante de recebimento. Caso haja avarias, não aceite o produto. Imagens meramente ilustrativas: Não acompanham objetos de decoração. A tonalidade pode variar devido ao tratamento das imagens, calibração do monitor ou percepção visual.', 593.9, 439.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-m650amr03zb461', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1302727497%2F23993175994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
