INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799866436', 'Boneco Funko Pop! Os Simpsons - Marge com Maggie', 'Encante sua coleção com o Boneco Funko Pop! Marge com Maggie! Esta figura traz Marge Simpson, a matriarca carinhosa de Springfield, segurando a adorável Maggie, em uma peça detalhada que captura toda a essência da família mais divertida da TV. Com aproximadamente 13 centímetros de altura, o colecionável em vinil é perfeito para fãs da série e colecionadores que desejam adicionar um toque especial e nostálgico à sua prateleira. Não perca a chance de ter essa dupla icônica na sua coleção de The Simpsons!', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824jf-mehnsng58nwg7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F20799866436', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
