INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597987675', 'Kit Vassoura + Rodo 30cm + Pá Para Lixo Com Cabo Noviça', 'Kit composto por: - 1 Vassoura Multiuso Original com Cabo Concept Noviça Bettanin (139 x 31,5 cm AxL) - 1 Rodo Pequeno com Cabo Ballena Concept 30cm Noviça Bettanin - 1 Pá de Lixo com Cabo Concept Noviça Bettanin 128,5 x 26 x 25 cm AxLxC) A Vassoura Multiuso Original com Cabo Concept Noviça Bettanin possui tecnologia multiuso DUO, pois o produto traz cerdas macias na parte externa e cerdas firmes na parte interna. Combinando dois tipos de cerdas, as vassouras com essa inovação tem plumagem densa e podem ser usadas tanto nos ambientes internos como nos externos, incluindo a varrição de tapetes. O Rodo Pequeno com Cabo Ballena Concept Noviça Bettanin é indicado para uso interno, sendo ideal para limpeza de lavanderias. O modelo possibilita puxar a água com maior eficiencia e agilidade. O tamanho pequeno possui borracha com 30 cm de extensão. A Pá de Lixo com Cabo Concept Noviça Bettanin liberta suas mãos para varrição, evitando o contato com a sujeira, devido ao cabo longo que facilita o manuseio. Ela possui borracha flexivel e aderente que facilita o recolhimento de pequenos residuos.', 99.9, 67.9, NULL, 'Home & Living > Home Care Supplies > Brooms', 'https://cf.shopee.com.br/file/sg-11134201-7repu-m8xms5gkp3px67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F21597987675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
