INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7686330341', 'Kit 2 Borracha Porta Tipo Original Fiat 147 1982 1983 1984', 'Detalhes do Produto: Kit 02 Borracha De Porta Tipo Original Brasilia e Variant II 1973 Até 1982, Chevette e Chevy 1983 Até 1994 e Fiat 147 1976 Até 1986 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Brasilia 1973 1974 1975 1976 1977 1978 1979 1980 1981 1982 Variant II 1973 1974 1975 1976 1977 1978 1979 1980 1981 1982 Chevette 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Chevy 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Fiat 147 1976 1977 1978 1979 1980 1981 1982 1983 1984 1985 1986 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor de 2 borrachas (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 02 Borrachas de porta (02 anos de garantia)', 107.84, 107.84, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.