INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258136391', 'Guarda Roupa Casal 3 Pts com Espelho e pés Atlas Amêndoa/Branco/Amêndoa', 'Guarda-Roupa Atlas – Organização, praticidade e elegância no seu quarto O Guarda-Roupa Atlas é a escolha ideal para quem busca funcionalidade sem abrir mão de um design moderno e clean. Com portas de correr e espelho central, ele amplia visualmente o ambiente e traz mais praticidade para o dia a dia. Produzido em MDP de alta qualidade com chapas de 12 e 15mm, oferece resistência e excelente acabamento. Seu interno diferenciado com 7 nichos permite organizar roupas, acessórios, malas e objetos de forma inteligente. Conta ainda com espaço dedicado para sapatos, mantendo tudo no seu devido lugar, além de puxadores em ABS, que garantem leveza e durabilidade no uso diário. O espelho frontal é um grande diferencial, trazendo mais funcionalidade e ajudando a compor um ambiente mais sofisticado. Dimensões ideais para diversos tamanhos de quarto:Altura: 212 cmLargura: 170 cmProfundidade: 51 cm', 1399.9, 999.9, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-81zte-mmklq10crzep9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1372644554%2F58258136391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
