INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697813036', 'Guarda-Roupa 2 Portas Kappesberg Adapt Branco/Nogueira', 'Para quem sempre sonhou com um quarto planejado, o Modulado Adapt da Kappesberg é a escolha ideal. Produzido em MDP, material de alta qualidade, o Roupeiro 2 portas N534 é ideal para quem busca por uma melhor otimização do espaço. Espaçoso e muito versátil, ele garante ainda mais beleza e funcionalidade. Com duas portas e uma divisão interna entre prateleiras e cabideiro, ele é ideal para guardar peças de roupa dobradas e calçados, deixando seu espaço sempre organizado. E com pintura de sete camadas, ele conta com uma combinação de cores única, entre o branco, com acabamento em brilho, e o nogueira, com pintura fosca e acabamento touch, combinando facilmente com todos os ambientes, além de garantir a sensação de aconchego e conforto. Os destaques ficam por conta do sistema de amortecimento nas portas, proporcionando um fechamento suave e sem ruídos, do puxador em MDF, e da montagem interna ajustável, podendo ampliar a quantidade de gavetas ou prateleiras, completando os diferenciais do produto e deixando você com o quarto que sempre sonhou. Renove seu quarto com toda a qualidade e beleza que o Modulado Adapt da Kappesberg oferece e aproveite cada momento. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1512.88, 899.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-824iy-me610ub3ikn8f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F18697813036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191291662', 'VINHO CONCHA Y TORO RESERVADO SAUVIGNON BLANC 750ML', 'Um varietal fácil de beber, o Vinho Santa Helena Reservado Sauvignon Blanc é ideal para ser degustado em momentos informais, com qualidade, bom preço e tradição. Desenvolvido nas melhores regiões vinícolas do Chile, reúne uma variedade especial de uvas, combinadas com seus notáveis aromas de lichia, goiaba e intensas notas herbáceas, trazendo ao paladar excelente acidez, que ressalta seu sabor frutado e sua sensação refrescante. Excelente opção para acompanhar uma grande variedade de pratos.Com um visual amarelo Claro Com Reflexos Esverdeados, olfato de frutas Brancas, Cítricas E Tropicais, já na boca é Leve, Frutado E Bastante Fresco.', 35.9, 35.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7qvfd-lh59r2sii30r5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F23191291662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22095793111', 'WHISKY JACK DANIELS FIRE 1000ML', 'Jack Daniel''s Tennessee Fire é a mistura perfeita do Jack Daniel''s Tennessee Whiskey Old Nº7 com um licor de canela. O Tennessee Fire apresenta aroma potente e picante de canela, sem perder os traços marcantes do Jack Daniel''s: o carvalho e a baunilha estão bem presentes. Pode ser apreciado em ocasiões mais informais, como festas e baladas, até em clima de praia. A sugestão é consumir puro e bem gelado, direto do congelador, mas também vai muito bem em drinks! De acordo com as leis que regulamentam a produção de whisky nos Estados Unidos, Jack Fire não pode ser considerado um tennessee whiskey e nem mesmo um whiskey, é apresentado no rótulo da garrafa como um Cinnamon Liqueur Blended with Jack Daniel?s Tennessee Whiskey (Licor de Canela misturado com Jack Daniel''s Tennessee Whiskey). Na legislação brasileira se enquadra na categoria das bebidas compostas.', 169.9, 169.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-7qvg1-lh59kxv9sokkdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22095793111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194950587', 'Elma Chips Stiksy Palitinho Salgado', 'Stiksy, o palitinho salgado da Elma Chips que você adora! Crocante e delicioso, é perfeito para qualquer hora e lugar. Feito com ingredientes selecionados e assado, Stiksy é uma opção saborosa e prática para matar a fome.', 11.79, 11.79, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-8258k-mqnelk50fwun19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F23194950587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259658465', 'Nestlé Choco Trio Chocolate', 'O Chocolate NESTLÉ Choco Trio é uma barra deliciosa que combina o melhor do chocolate de alta qualidade com uma camada crocante de biscoito de chocolate na parte superior. Com recheio cremoso de chocolate, essa mistura oferece o equilíbrio perfeito entre a crocância e a suavidade, proporcionando um sabor irresistível a cada pedaço. ALÉRGICOS: Contém glúten, lactose, derivados de leite, de soja, de trigo, de centeio e de aveia. Pode conter amendoim, avelã, castanha-de-caju, cevada e látex natural.', 12.99, 12.99, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-8258g-mqnel7628rnz1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F58259658465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
