INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997089381', 'Ventilador de Teto Britânia Silencioso 131W Cristal BVT05B', 'Torne o ambiente ainda mais refrescante com o Ventilador de Teto Britânia 3 em 1 Silencioso Cristal BVT05B. O melhor Ventilador de Teto, pois ele é 3 em 1. Sim! Funciona como ventilador, exaustor e luminária. Ele é a união de design e funcionalidades que deixam qualquer lugar ainda mais agradável. Com ele você garante mais autonomia e praticidade com um Ventilador de teto com controle remoto! Além disso, ele possui 3 velocidades e função reversa para, além de ventilar, fazer a função de exaustor, tirando odores e ajudando na circulação do ar. Um Ventilador de teto moderno e clean, com 3 pás em policarbonato transparente que garantem mais resistência e durabilidade. Desfrute de um Ventilador de Teto potente e silencioso, tudo no mesmo produto. É comodidade, conforto e qualidade para você! • Luminária para duas lâmpadas • 3 em 1: funciona como ventilador, exaustor e luminária • Função reversa: Seleciona entre os modos exaustor ou ventilador • Baixo consumo de energia e alta performance de vento • Silencioso: Ideal para qualquer tipo de ambiente • 3 Velocidades: Baixa, média e alta no modo ventilação e exaustor • Controle remoto para fácil utilização • 3 pás em policarbonato transparente • Desmontável - facilita a limpeza • Potência de 131W.', 579.9, 579.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-823r4-mord92zq6tcf3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F18997089381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
