INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47604414304', 'Tênis Infantil Menino Kidy K360 Energy Preto Confortável Calce Fácil Escolar', 'O Tênis Super Calce Fácil foi pensado para crianças que estão sempre em movimento e para pais que buscam um tênis fácil de calçar e cheio de tecnologia. O modelo combina o charme do preto com o toque moderno do crepe, trazendo um visual versátil que combina com qualquer ocasião. Seu solado em TR anatômico e superflexível garante estabilidade e segurança, absorvendo o impacto e proporcionando um caminhar leve e natural. Com o sistema Super Calce Fácil, o tênis veste com rapidez sem cadarços, sem complicação. E a tecnologia Respi-Tec cuida do conforto interno, permitindo a circulação do ar para que os pezinhos fiquem secos, frescos e longe do chulé. Tamanhos: do 28 ao 36; Fechamento: Calce Facil; Cabedal: Têxtil; Forro: Têxtil; Palmilha: EVA; Sola: PVC;', 189.99, 169.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mj9zri10ke1175', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F47604414304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
