INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394272726', 'Torradeira Duo 127v 700w Vermelha Multi - GO065', 'Torradeira Duo 127V 700W Vermelha Multi - Com Controle de Tostagem para Torradas Perfeitas Sempre Comece o dia com mais sabor e praticidade com a Torradeira Duo Vermelha Multi! Ideal para preparar torradas crocantes e quentinhas em poucos minutos, ela une funcionalidade inteligente com um design moderno que valoriza sua cozinha. Com ajuste de tostagem e ejeção automática, você garante o ponto ideal do pão com total segurança e praticidade. Seu acabamento black piano traz sofisticação ao ambiente, enquanto os recursos pensados para o dia a dia facilitam ainda mais sua rotina. Por que escolher a Torradeira Duo Multi? - Praticidade em Dobro: Toste duas fatias ao mesmo tempo com rapidez, ideal para cafés da manhã e lanches rápidos. - Controle Personalizado: Escolha entre 6 níveis de tostagem, do levemente dourado ao super crocante, de acordo com seu gosto. - Mais Segurança: Sistema de desligamento automático que ejeta as torradas no ponto certo e evita queimar. - Design Moderno e Sofisticado: Com acabamento em black piano, traz elegância para qualquer estilo de cozinha. - Versatilidade com Aberturas Largas: Acomoda diversos tipos e espessuras de pães, garantindo um resultado uniforme. - Botão Cancelar: Interrompa o processo de tostagem a qualquer momento, com um simples toque. - Fácil de Limpar: Bandeja coletora de migalhas removível que facilita a higienização diária. - Armazenamento Prático: Porta-fio na base para manter sua cozinha sempre organizada. Escolha a Torradeira Duo Multi e leve mais agilidade, controle e estilo para os seus momentos à mesa! Ficha Técncia Marca: Multi Modelo: Torradeira Duo 127v 700w Vermelha Multi - GO065 Cor: Vermelha Tensão: 127v Potência: 700W Coletor de Migalhas: Sim Desligamento Automático: Sim Aberturas Extralargas: Sim Dimensões: 11.5 x 15.5 x 23cm Peso do Produto: 777g Garantia; 1 Ano Imagens meramente ilustrativas.', 120.89, 109.9, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-mcqhmcludatcba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F22394272726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999835509', 'Cicatricure Neuro-Zen Antirrugas - Creme Facial 50g', 'Cicatricure Neuro-Zen Antirrugas - Hidrata, Suaviza e Revitaliza Cicatricure Neuro-Zen é o creme facial antirrugas com tecnologia avançada que combate sinais de estresse em apenas 7 dias. Formulação leve com melatonina, niacinamida e ácido hialurônico, hidrata profundamente, suaviza linhas de expressão e devolve luminosidade natural à pele Conselho de Aplicação Aplique duas vezes ao dia, pela manhã e à noite, sobre a pele limpa e seca. Use a quantidade necessária no rosto, pescoço e colo, massageando suavemente do centro para fora. Na região dos olhos, aplique com toques leves das pontas dos dedos, de dentro para fora, até a completa absorção. Evite o contato direto com os olhos.', 167.1, 102.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-mbsi11dicqz15a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21999835509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
