INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14286304787', 'Livro As aventuras de Sherlock Holmes | Arthur Conan Doyle', 'As aventuras de Sherlock Holmes Sherlock Holmes é um detetive britânico enigmático e pedante do final do século XIX e início do século XX. Ele utiliza a metodologia científica e a lógica dedutiva para solucionar seus casos e conta com a ajuda de seu fiel amigo e parceiro dr. Watson. Observação, perspicácia e um pouco de intuição são alguns dos instrumentos usados por Sherlock Holmes para desvendar os seis curiosos casos reunidos nesta obra e narrados pelo atento doutor Watson. Título , As ,aventuras ,de ,Sherlock ,Holmes Coleção , Sherlock ,Holmes Autor , Arthur ,Conan ,Doyle Páginas , 208 Formato , 23 ,x ,16 ,x ,1 ,cm Peso , 240g ISBN , 9788594318558 Editora , Ciranda', 11.38, 11.38, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/991690e641d2dc9388cd5ffd632b037e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F14286304787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8028774397', 'A Arte De Pastorear - David Hansen', '📝 Descrição: A Arte de Pastorear, escrito por David Hansen, é um livro inspirador que retrata as diversas facetas do ministério pastoral com sensibilidade e profundidade. Com linguagem acessível e criativa, Hansen compartilha experiências reais e reflexões teológicas que revelam o coração do pastor como servo, líder e discípulo. A obra destaca a importância da espiritualidade autêntica, da escuta pastoral e da presença significativa no cuidado com pessoas. Ideal para pastores, líderes ministeriais, estudantes de teologia e todos que desejam compreender o chamado pastoral como uma arte moldada pela graça de Deus. 📄 Ficha técnica: Título: A Arte de Pastorear Autor: David Hansen Editora: Shedd Publicações Ano de publicação: 2005 ISBN: 9788588315105 Idioma: Português Número de páginas: 200 Formato: Brochura Dimensões: 21 cm x 14 cm Peso: 300 g Categoria: Liderança cristã, teologia pastoral, espiritualidade Indicação etária: A partir de 14 anos 🔍 Palavras-chave: a arte de pastorear, david hansen, ministério pastoral, liderança cristã, shedd publicações, teologia prática, cuidado pastoral, espiritualidade, livro para pastores, vocação ministerial', 55.74, 55.74, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/8e9185c5fc3e42a6ec5bfbcd71458f7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F8028774397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
