INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492840363', 'Combo 5 Litros Óleo do Motor Original Nissan 5W30 GF5 API SN 100% Sintético Aplicado nos Veículos (Tiida, March, Livina)', 'ÓLEO DE MOTOR DE NISSAN COMPLETO SINTÉTICO 5W30 SN / GF-5 Tecnologia Sintética de Alto Desempenho Recomendado para motores a gasolina / a gasolina da Nissan que requerem um óleo de motor SAE 5W-30 • Recomendado para os modernos motores a gasolina / gasolina da Nissan, particularmente o HR12DDR, Modelos HR12DE e MR16DDT • Projetado para uso em condições de condução exigentes, incluindo cidade, país e auto-estrada • Projetado para uso em todos os climas • Consulte o Manual do Proprietário do seu veículo ou o Manual de Oficina da Nissan para obter informações sobre cronogramas de manutenção O NISSAN MOTOR OIL SINTÉTICO COMPLETO 5W-30 SN / GF-5 atende ou excede os requisitos de: • API: SN • ILSAC GF-5 Ótima limpeza do motor • Excepcional estabilidade térmica e resistência à oxidação • Proteção constante dos componentes do motor • Melhoria da economia de combustível • Minimização das emissões de escape prejudiciais Aplicado nos Veículos ( Tiida, March, Versa, Sentra, Livina )', 288.77, 288.77, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rcfc-lrkf7zpvdf7k45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F641270782%2F22492840363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
