INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698078886', 'Tinta Dourado Uso Geral 350ml - Tekbond', 'Tinta Dourado Uso Geral 350ml Marca: Tekbond INSTRUÇÕES DE USO: PREPARO DA SUPERFÍCIE: 1. Proteja as partes que não serão pintadas com papel, papelão ou plástico. 2. Aplique de 2 a 3 demãos em camadas bem finas. 3. Entre cada demão de verniz, aguarde um intervalo de 1 a 3 minutos. 4. Para o toque aguarde um intervalo de 30 minutos. 5. Para manuseio da peça aguarde um intervalo de 3 horas. 6. Cura total em 24 horas e para testes mecânicos, recomendamos 72 horas. Rendimento aproximado: 1,7 m2 a 2,1 m2 por embalagem. OBSERVAÇÃO: AGITAR BEM A LATA ANTES DO USO E ENTRE AS DEMÃOS. SE OCORRER O ENTUPIMENTO DA VÁLVULA, RETIRE O BICO E MERGULHE-O EM THINNER OU ACETONA. SE NECESSÁRIO DESOBSTRUA O ORIFÍCIO COM UMA AGULHA. ARMAZENAMENTO: Manter em local coberto e ventilado (temperatura inferior a 50° C). Nestas condições, o produto em sua embalagem original e lacrada tem garantia de 3 anos a partir da sua data de fabricação.', 28.22, 28.22, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-81zww-mn5pkbn8vo5g3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F641270782%2F19698078886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52007322901', 'Suplemento BCAA 300g Black Skull Guaraná /Melancia – Fórmula Original', 'Suplemento BCAA 300g Black Skull Guaraná – Fórmula Original Suplemento alimentar em pó com aminoácidos de cadeia ramificada (BCAA), recomendado para complementar o consumo diário de nutrientes, especialmente para pessoas que praticam exercícios físicos. Destaques do Produto: ✔ Possui BCAA (Leucina, Isoleucina e Valina) ✔ Preparo e ingestão simples ✔ Sabor guaraná ✔ Indicado para rotina de exercícios ✔ Marca consolidada no mercado Detalhes do Produto: Marca: Black Skull Categoria: Produto alimentar em pó Peso: 300g Sabor: Guaraná Recomendação: Adultos ≥ 19 anos Itens Inclusos: 1x BCAA em Pó 300g - Sabor guaraná ⚠️ Informação Importante: Este produto não é um medicamento. Não ultrapassar a recomendação diária de consumo indicada na embalagem. Conservar fora do alcance de crianças. Este produto não é recomendado para gestantes, lactantes e crianças, exceto sob orientação de médico ou nutricionista. Envio ✔ Produto original ✔ Disponível para envio imediato ✔ Despacho ágil', 69.0, 59.0, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mlxmjq8o0kjldd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F554865709%2F52007322901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797423342', 'Cesto Organizador 4,5 Litros Flow CFW200 - Ou', 'Cesto Flow 4,5 Litros - Ou Os Cestos Flow da Ou são aliados essenciais na organização de qualquer ambiente, oferecendo praticidade e eficiência no armazenamento de diversos itens. Com capacidade de 4,5 litros e medidas de 34x15x9 cm, proporcionam espaço suficiente para guardar produtos de limpeza, roupas ou acessórios, mantendo cada espaço da casa organizado de forma fluida e eficaz. Seu design ergonômico conta com uma pega em formato redondo para encaixe confortável dos dedos, tornando o manuseio mais simples e confortável. Fabricados em PP (Polipropileno), os Cestos Flow são resistentes e duráveis, garantindo sua utilização por longos períodos. Simplifique sua rotina diária e mantenha sua casa organizada com os Cestos Flow da Ou. Especificações Marca: Ou Modelo Cesto Flow 4,5 Litros Material: PP (Polipropileno) Capacidade: 4,5 litros Medidas: 34x15x9 cm Peso: 175g', 37.9, 29.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbqoxy28ab8928', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F22797423342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
