INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799003972', 'Coxim Motor Gm Ipanema 1989 a 1997 - 514856 - ACX02013', 'Coxim Motor Gm Ipanema 1989 a 1997 514856 ACX02013 (Dianteiro) (Lado Direito) (Sem Ar Condicionado) São divididos em 3 grupos: coxins do motor, coxins do câmbio e coxins do amortecedor. A função do coxim de motor/câmbio é ser o ponto de apoio do motor no chassi, fazendo a absorção da vibração do motor e evitando que seja transmitido para o veículo. O uso de coxins danificados diminuirá significativamente a vida útil do motor/câmbio do veículo.', 70.2, 70.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblp-lmqg0a7jmehcc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20799003972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
