INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299925508', 'Fita Dupla Face Acrílica 12mm x 2m Interno Tekbond', 'Fita Dupla Face Acrílica 12mm x 2m Interno Tekbond A Fita Dupla Face Acrílica 12mm x 2m Interno Tekbond é a escolha prática e eficiente para quem busca fixação segura em diferentes tipos de superfícies. Com alta aderência, ela proporciona uma colagem firme e duradoura, substituindo pregos, parafusos e colas convencionais em diversas aplicações internas. Seu formato de 12mm de largura por 2 metros de comprimento garante versatilidade para pequenas e médias tarefas de fixação no dia a dia, tornando-se indispensável para reparos e acabamentos. Com adesivo acrílico de qualidade, a fita se destaca pela resistência e pela praticidade no manuseio, permitindo uma aplicação limpa e rápida, sem necessidade de ferramentas. Ideal para colar quadros, objetos decorativos, acessórios de cozinha, banheiro ou escritório, ela garante ótimo desempenho em ambientes internos. Além disso, sua transparência proporciona um acabamento discreto e elegante, sem interferir na estética do ambiente ou do objeto fixado. A fita dupla face Tekbond também contribui para um resultado duradouro, pois mantém a fixação estável mesmo com o passar do tempo. Desenvolvida para atender diferentes necessidades de fixação interna, ela alia tecnologia, praticidade e eficiência em um único produto. Seja para organizar, decorar ou realizar pequenas instalações, essa fita é a solução inteligente para quem busca agilidade, resistência e acabamento impecável em seus projetos.', 25.9, 25.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-824j2-mezqhu2i36z3a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F18299925508', NULL, NULL, '2026-07