INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251551956', 'Conjunto Menino Camiseta e Short Up Baby', 'Conjunto para menino que une praticidade e conforto. A camiseta de algodão leve conta com gola arredondada, mangas curtas e estampa criativa. Já o short em poliéster com elastano oferece elasticidade, cós com elástico regulável, cadarço funcional e estampa colorida. Um look alegre para brincar, passear ou curtir o dia.Tecido: Camiseta: Meia Malha (Algodão) | Short: Microfibra (Poliéster e Elastano)Composição: CAMISETA: 100%algodão,SHORT: 93%poliéster 7%elastanoModelagem: AmplaComprimento Mangas: CurtaComprimento: CurtoForro: NãoCintura: MédiaDecote/Gola: RedondoFechamento: Cadarço', 174.9, 87.45, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-822xw-mhwbh1lqfbwheb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58251551956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259443057', 'Azeite Extra Virgem Gallo', 'O azeite de oliva extra virgem Gallo é o sabor original de Portugal, perfeito para adicionar harmonia e confiança em todos os seus pratos. Com um perfil equilibrado de frutado, amargo e picante, este azeite clássico é ideal para: * Cozinhar e temperar saladas, massas, carnes e peixes * Preparar pratos quentes e frios * Harmonizar com queijos, pães e outros petiscos', 38.49, 27.99, NULL, 'Food & Beverages > Cooking Essentials > Oil', 'https://cf.shopee.com.br/file/sg-11134201-8257v-mqnem4ukzr4ba4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259443057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493968819', 'Pneu 205/60R15 Aplus 91V Aro 15', 'DESCRIÇÃO DO PRODUTO O Pneu Aplus A609-6 205/60R15 91V TL foi desenvolvido para oferecer segurança, conforto e excelente desempenho no uso urbano e rodoviário. Com desenho moderno da banda de rodagem, garante ótima aderência em piso seco e molhado, proporcionando mais estabilidade em curvas, frenagens seguras e uma condução mais confortável. É uma excelente opção para veículos de passeio e sedãs médios, oferecendo bom equilíbrio entre durabilidade, estabilidade e ótimo custo-benefício no dia a dia. PRINCIPAIS BENEFÍCIOS Excelente aderência em piso seco e molhado Maior estabilidade em curvas e frenagens Rodagem confortável e silenciosa Desgaste uniforme da banda de rodagem Boa eficiência no consumo de combustível Ótimo custo-benefício Condução segura em estrada e cidade Boa durabilidade Estabilidade em altas velocidades Ideal para uso diário ESPECIFICAÇÕES TÉCNICAS Marca: Aplus Modelo: A609-6 Medida: 205/60R15 Índice de carga: 91 (615 kg por pneu) Índice de velocidade: V (até 240 km/h) Construção: Radial Tipo: TL (sem câmara) Aro: 15 Quantidade: 1 pneu (unitário) Categoria: Passeio / Sedãs médios COMPATIBILIDADE Volkswagen Polo Volkswagen Golf Volkswagen Fox (versões compatíveis/adaptadas) Volkswagen Jetta (versões compatíveis/adaptadas) Fiat Linea Fiat Bravo Fiat Argo (versões compatíveis/adaptadas) Chevrolet Vectra Chevrolet Astra Chevrolet Zafira Ford Focus Ford Fusion (versões compatíveis/adaptadas) Renault Fluence Renault Megane Honda Civic (versões compatíveis/adaptadas) Honda Accord (versões compatíveis/adaptadas) Nissan Sentra Nissan Sylphy (versões compatíveis/adaptadas) Hyundai Elantra Hyundai i30 (versões compatíveis/adaptadas) Kia Cerato Kia Forte Toyota Corolla (versões compatíveis/adaptadas) Outros veículos com medida 205/60R15 PERGUNTAS FREQUENTES O PNEU É NOVO? Sim, produto novo de fábrica. ELE É SILENCIOSO? Sim, proporciona rodagem confortável com baixo ruído. TEM BOA DURABILIDADE? Sim, possui desgaste uniforme e longa vida útil. PODE USAR EM ESTRADA? Sim, indicado para uso urbano e rodoviário. PRECISA DE CÂMARA? Não, é modelo TL (Tubeless), sem câmara. INFORMAÇÕES IMPORTANTES Produto novo e original Não trabalhamos com pneus remold Garantia de 5 anos pelo Fabricante.', 449.42, 349.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rff1-m9i2sxp8kxif26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311743114%2F23493968819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
