INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299204629', 'Conjunto Infantil Menino Nature Aveludado Colorittá Bege', 'O Conjunto Colorittá é composto por camiseta em malha linho e bermuda em moletom eco linho estampado. A camiseta de mangas curtas possui estampa frontal com a palavra "Nature" e detalhes flocados, que dão um toque aveludado e charmoso à peça. Já a bermuda conta com elástico no cós, bolsos laterais e estampa de folhas tropicais, transmitindo a essência do verão. Ideal para passeios e momentos de lazer, esse conjunto é uma escolha cheia de personalidade para os dias mais quentes. Aposte!Detalhes da peça: • Conjunto composto por camiseta e bermuda • Feito em malha linho e moletom eco linho estampado • Possui mangas curtas • Estampa tropical com folhas • Detalhes aveludados • Elástico no cós • Possui bolsos • Ideal para passeios e momentos de lazer Modelo gerado por IA para fins ilustrativos. Em caso de dúvidas, considere a foto oficial sem modelo.', 139.9, 83.94, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mr1tmnrqrbb476', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F22299204629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
