INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093335649', 'Maçaneta externa porta dianteira Kombi 1975 a 2013', 'Maçaneta Externa da Porta Dianteira Esquerda ou Direita VW Kombi Clipper 75>13 / Worker / Delivery / Titan / Tractor - Sikar Automotive A Sikar Automotive oferece a Maçaneta Externa Preta para portas dianteiras da VW Kombi Clipper, Worker, Delivery, Titan e Tractor, ideal para reposição com excelente acabamento e alta durabilidade. Fabricada em metal resistente, a peça se destaca pela robustez e compatibilidade com uma ampla gama de veículos da Volkswagen, de 1975 a 2018. Especificações do produto: - Produto novo, de ótima qualidade; - Cor: Preto; - Material: Metal; - Acompanha duas chaves (uma principal e outra reserva); - Modelo original, ideal para reposição; - Pronta entrega; - Garantia de 6 meses após emissão da nota fiscal. **Conteúdo da embalagem: - 1 Maçaneta externa para porta (serve tanto para o lado esquerdo quanto direito). Veículos aplicáveis: - Volkswagen Kombi Clipper: 1975 a 2013; - Caminhões Worker / Delivery / Titan / Tractor: 1981 a 2018. Informações importantes: - Verifique a compatibilidade do produto com o seu veículo; - Valor referente a 1 peça; - Garantia de 180 dias (6 meses); - Recomendamos instalação por profissional; - A loja Sikar Automotive não se responsabiliza por má instalação; - Envio rápido: o produto será postado em até 24 horas após o pagamento; - Consulte o valor do frete diretamente no Mercado Livre. Com garantia e nota fiscal, essa peça é uma solução prática e confiável para quem busca reposição de qualidade para veículos comerciais da linha Volkswagen.', 98.5, 68.22, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-m0i035e1r6de12', 'https://shope.ee/an_redir?origin_link=h