INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198258489', 'Correia Poly V Alternador GOLF 1.8 8V 1995 1996 1997 1998 - 98416 - 6PK1153', 'Correia Poly V Alternador GOLF 1.8 8V 1995 1996 1997 1998 CONTITECH 6PK1153 - ALTERNADORA/AR /BOMBA ÁGUAAs correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 102.71, 102.71, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5y-m6u442gmkrvl2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22198258489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598318371', 'Kit Jogo De Chave De Fenda 6 Peças Tramontina Ponta Chata Cruzada E Tipo Clip Reparos Elétricos', 'Jogo De Chaves De Fenda 6 Peças Tramontina Se você busca qualidade, praticidade e durabilidade, o Jogo de Chaves de Fenda Tramontina MASTER Yellow 6 Peças é a escolha ideal para completar sua caixa de ferramentas. O kit traz chaves com ponta chata, ponta cruzada e uma chave clipe, que pode ser facilmente fixada em cintos e alças, oferecendo versatilidade no dia a dia. Produzidas em aço especial cromado, com cabos de polipropileno injetado de alta resistência, garantem segurança, conforto e longa vida útil. Característica: > Jogo com 6 chaves de fenda variadas; > Ponta chata e cruzada, atendendo diferentes necessidades; > Inclui chave clipe para prender em cintos e facilitar o transporte; > Hastes fabricadas em aço especial cromado; > Cabos de polipropileno injetado de alta resistência; > Excelente durabilidade e segurança no manuseio; > Produzidas e testadas conforme normas específicas. Especificações: > Linha: MASTER Yellow; > Modelo: Jogo de Chaves de Fenda 6 Peças; > Material da haste: Aço especial cromado; > Material do cabo: Polipropileno injetado; > Uso: Doméstico / Oficina / Profissional; > Função: Apertar e afrouxar parafusos. - Marca: Tramontina - Garantia: 12 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 55.33, 41.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gr-mfclnjwcxqfh99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F19598318371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692532727', 'Cano Refrigeracao ASTRA 2.0 16V 1999/2005 Com Ar - 63452 - VC416', 'Cano Refrigeracao ASTRA 2.0 16V 1999/2005 Com Ar GL / GLS - 2.0 16v Gasolina - Com Ar - Ligação Mangueira do Reservatório de Água O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 62.43, 62.43, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rate-maiu28qx6gk069', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22692532727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22721013064', 'Caneca Térmica Street Rose Contigo | 414 ml', 'A Caneca Térmica Street Rose Contigo | 414 ml combina a praticidade de manter bebidas quentes ou frias por horas com um design sofisticado em cores metálicas chamativas. A caneca mantém as bebidas quentes por até 5 horas ou frias por até 15 horas, sendo perfeita para tomar café enquanto trabalha em casa ou dá uma volta rápida pelo bairro. A alça confortável torna a hora de tomar suas bebidas favoritas mais agradável e a tampa à prova de respingos mantém sua bebida dentro da caneca quando fechada. O fundo emborrachado é antiderrapante e ajuda a evitar que a caneca escorregue, faça barulho ou risque as superfícies, para que você se sinta confiante ao colocá-la sobre qualquer superfície. A caneca cabe convenientemente na maioria das máquinas de café. O corpo e a tampa podem ser lavados na prateleira superior da lava-louças. Principais característicasAlça em aço inoxidável elegante que permite beber com mais facilidadeTampa à prova de respingosTanto o corpo quanto a tampa podem ir na prateleira superior da lava louçasFundo emborrachado, antiderrapante, ajuda a evitar que a caneca escorregue ou risque as superfíciesLivre de BPA; Conserva por mais tempoBebidas quentes por até 5 horasBebidas frias por até 15 horas Garantia3 meses Capacidade414 ml Cuidados e manutençãoLavar bem antes de cada uso;Deslize a tampa para abrir antes de enxaguar ou lavar;A tampa e o corpo em aço inoxidável são seguros para ir na prateleira superior de sua lava louças;Sempre guarde a caneca com a tampa removida para permitir que as partes sequem completamente. Conteúdo da embalagem1 Caneca Térmica Street Rose1 Manual', 79.9, 79.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-82590-mr1llfjh6zuv82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859051456%2F22721013064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
