INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797677986', 'Formula Infantil Aptamil Profutura Gold 1 800g', 'Aptamil Profutura Gold 1 é uma fórmula infantil para bebês de 0 a 6 meses, quando for necessário recorrer à alimentação com mamadeira por orientação médica. Ele contém probióticos e ácidos graxos que contribuem com o desenvolvimento cerebral, sistema visual e para o favorecimento do sistema imunológico. O Ministério da Saúde informa: o aleitamento materno evita infecções e alergias e é recomendado até os 2 (dois) anos de idade ou mais. O Ministério da Saúde informa: após os 6 (seis) meses de idade continue amamentando seu filho e ofereça novos alimentos.', 145.19, 145.19, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd4n-lvdbsk4pdas1ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F20797677986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
