INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394777516', 'Jogo de Cama Casal Buddemeyer Cotton Áureo', 'CARACTERÍSTICA DO PRODUTO: Com acabamento impecável e detalhes exclusivos nas fronhas, este jogo combina praticidade e elegância Com sua maciez excepcional e design funcional, o Jogo de Cama Cotton Áureo Buddemeyer transforma o cotidiano em uma experiência de puro bem-estar. Ideal para quem busca versatilidade, frescor e qualidade superior. Buddemeyer - conforto e qualidade que transformam seu sono. CONTEÚDO DA EMBALAGEM: Contém: 1 sobrelençol 220x240cm + 1 lençol 140x190x35cm + 2 fronhas sem abas 50x70cm COMPOSIÇÃO: 100% Algodão TIPO DE MATERIAL: Algodão DESCRIÇÃO: Jogo de Cama Solteiro Buddemeyer Cotton Áureo - Essencial, versátil e incrivelmente aconchegante, a Coleção Cotton Áureo é confeccionada em puro algodão com fibras longas, proporcionando um toque macio e confortável. Pensado para transformar as noites de descanso e renovar o estilo do seu quarto, este jogo de lençol de design clean é enriquecido por detalhes de alfaiataria no sobrelençol e nas fronhas, e a moldura em viés. Os acabamentos criam a base perfeita para combinações modernas e elegantes. Disponível para colchões de até 35 cm de altura, o Cotton Áureo é a peça-chave para quem valoriza o conforto elevado em cada detalhe. Buddemeyer - conforto e qualidade que transformam seu sono. INSTRUÇÕES DE CUIDADO: Lave antes de usar; Lave cores escuras separadamente; Use sabão neutro ou de coco para preservar as características; Evite alvejantes e produtos à base de cloro; Secadora em baixa temperatura; Não passar e não lavar a seco.', 315.68, 284.11, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-8262m-ml50c1xkfsw2b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F23394777516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597669406', 'Calça Básica Masculina Em Moletom Flanelado', 'Calça Básica Malwee confeccionada em moletom flanelado. Modelo possui modelagem tradicional que acompanha as linhas do corpo com muito conforto, cós elástico e punho tubular aplicado. As calças básicas Malwee são atemporais e indispensáveis no guarda-roupa masculino por serem versáteis e feitas para durar, já que possuem a melhor durabilidade do mercado. O moletom flanelado é um tecido que garante aquecimento e estilo e com a textura flanelada interna, o item torna-se ainda mais macio e aconchegante para o uso no dia a dia. Combine com camiseta básica Malwee e tênis esportivo! Modelagem: TradicionalCós: Com elástico', 119.9, 107.91, NULL, 'Men Clothes > Pants > Pants', 'https://cf.shopee.com.br/file/sg-11134201-7rd61-lu8a4a34meml2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F18597669406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201859049', 'Kit Compacto Coala Chá Branco', 'Coala Difusor de Aromas Chá Branco Coala Difusor de Aromas é um excelente aromatizador de ambientes, mantendo o perfume por mais tempo. Além de garantir o aroma, o jogo de varetas que acompanha o produto compõe com o frasco e decora o ambiente com design moderno. Com a variedade de fragrâncias é possível variar o uso entre os ambientes, garantindo sensações únicas em cada um. O Difusor de Aromas Coala garante uma sensação confortável e duradoura no ambiente. Para ter o melhor resultado no uso, confira algumas dicas: Limpador Perfumado de Ambientes Chá Branco Com Coala Essências - Limpador Perfumado de Ambientes Chá Branco, seu ambiente vai ficar limpo e com um aroma incrível. Além de poder ser usada em todos os ambientes, a Coala Essências - Limpador Perfumado de Ambientes Chá Branco também: - Garante a sensação prolongada de limpeza e bem-estar; - Tem perfume duradouro, - Fragrância agradável. SABONETE LÍQUIDO CHÁ BRANCO 500ml O Sabonete Líquido Chá Branco Coala é o que faltava no seu dia-a-dia. Sua fórmula limpa delicadamente sua pele, deixando seu rosto, suas mãos e seu corpo macio e cheiroso.', 55.15, 53.5, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi6798v2e96r24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F58201859049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797727346', 'Tiras MedLevensohn On Call Plus 50 unidades', 'Compatíveis com o Monitor de Glicemia On Call Plus; Intervalo de medição entre 20 e 600 mg/dL; Indicadas para uso pessoal (autoteste) e profissional; Amostra aspirada rapidamente e sem contato direto com o monitor: Previne contaminação cruzada; Utilizadas para medição de glicose em sangue total fresco e em pacientes neonatos; Sem interferência de maltose, galactose, xilose e lactose.', 79.93, 79.93, NULL, 'Health > Medical Supplies > Health Monitors & Tests', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-lzfnnd8v2k6v79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23797727346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493048242', 'Protetor Solar Nivea Sun Protect & Hidrata FPS70 200ml', 'O Protetor Solar Sun Protect & Hidrata da Nivea é ideal para quem quer proteção sem deixar de lado a hidratação. Sua fórmula oil free possui pantenol, que hidrata e repara a barreira da pele, conferindo uma leve textura não pegajosa. Além disso, conta com alta proteção contra os raios UVA e UVB, oferecendo proteção imediata e prevenindo os danos causados pela exposição solar. O produto é dermatologicamente testado e de rápida absorção, bem como é altamente resistente a água e ao suor.', 100.98, 100.98, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd54-lvjdzx8jwhfb28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23493048242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18468514960', 'Kit 02 Pares Meia Corrida Ciclismo HUPI Carbono Preto e Branco', 'Kit Contém: 01 ParMeia Hupi Carbono Preto 01 Par Meia Hupi Carbono Branco Conforto, design, tecnologia e qualidade são adjetivos que descrevem perfeitamente as meias HUPI. Testado e aprovado por atletas de diversas modalidades, a meia HUPI é um item indispensável para você. Praticar esportes com conforto e máximo desempenho é o seu objetivo, e também o nosso. Por isso a meia HUPI apresenta diversos destaques que fazem dela um item fundamental. O material utilizado na fabricação da meia é importado da Alemanha. Os fios de elastano e poliamida formam um conjunto cheio de vantagens. O principal destaque é o conforto, proporcionado pela transpiração que a meia oferece, deixando os pés secos e bem protegidos. A combinação da matéria prima assegura a flexibilidade oferecendo maior liberdade de movimento, sem que a peça laceie, perdendo sustentação. Na região dos dedos e calcanhar, os fios são dispostos em direções diferentes do restante da meia, fazendo com que a modelagem se torne muito mais anatômica, acompanhando o desenho dos pés. Esta característica também prolonga a durabilidade, impedindo o desgaste. Características: Cano médio 15cm; Semi Compressiva; Composição:97% Poliamida | 3% Elastano; Conteúdo: 2 pares de meia; Tamanho único: Veste do 36 ao 42.', 148.55, 129.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-22120-mnkwurlix2kv3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F18468514960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
