INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098937098', 'Sapatênis Masculino Ferracini Couro Camurça Solado Amortecedor Gel Branco Marrom 2271A', 'O Sapatênis Esportivo Pulse traz cores versáteis e solado com tecnologia de conforto. Esse design moderno alia proteção e estabilidade aos pés, garantindo caminhar seguro por diferentes superfícies, oferecendo um estilo formal que combina com versatilidade e autenticidade. Características Principais: •Estilo: Formal e Urbano. •Materiais: Couro. •Solado: TR. •Cadarço: Elástico. •Conforto: Solado em TR com tecnologia Float.', 379.9, 379.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824g3-mf4es0bc66trdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733934100%2F23098937098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
