INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298648524', 'Lixadeira Roto Orbital 5" BDERO100 - Black+Decker 127V', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL 🛠️ Lixadeira Roto Orbital 5" 127V 180W BDERO100-B2 Black+Decker Eficiência, conforto e acabamento perfeito em um só equipamento! 📌 Descrição do Produto: A Lixadeira Roto Orbital Black+Decker BDERO100-B2 é ideal para trabalhos em madeira, metal, superfícies pintadas e plásticas. Com potência de 180W e base de 5" (125mm), ela oferece um acabamento superior com menos marcas no material, graças ao seu movimento roto-orbital. 🔧 Características: Potência: 180W Tensão: 127V Base: 5" (125mm) com sistema de velcro Velocidade: 12.000 órbitas por minuto Sistema de coleta de pó com saco coletor para um ambiente de trabalho mais limpo Empunhadura emborrachada, ergonômica e confortável Interruptor selado contra pó, aumentando a durabilidade da ferramenta ✅ Ideal para: Lixamento de portas, móveis, pisos, janelas e peças metálicas Acabamento em superfícies curvas e planas Trabalhos DIY e profissionais 📦 Acompanha: 1 Lixadeira Roto Orbital BDERO100-B2 1 Coletor de pó 1 Lixa com sistema hook & loop (velcro) 💡 Garanta agora mesmo essa ferramenta prática, eficiente e com a qualidade Black+Decker! 📍 Envio rápido e com nota fiscal. Produto novo e com garantia!', 373.04, 329.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rasp-may853eaa9z7dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F23298648524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
