INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46806148614', 'Revitalizador de Plásticos Internos e Externo Restaurax 240ml Vonixx', 'RESTAURAX 240ML - RESTAURADOR DE PLÁSTICOS DESCRIÇÃO: Restaurax renova e restaura superfícies plásticas, como para-choques, painéis e laterais de portas. Sua fórmula contém polímeros especiais que também protegem as peças contra as ações do tempo, evitando degradação precoce do material. DURABILIDADE: Até seis meses de proteção nos plásticos internos e sessenta dias nos plásticos externos. MODO DE USO: 1. Limpar bem a superfície e em seguida aplicar o produto com um aplicador de espuma até a completa restauração. Se necessário, repetir a operação. 2. Para manter o plástico sempre novo, repetir a aplicação do produto a cada 60 dias na parte externa e a cada 6 meses na parte interna. Obs: Para um resultado com menos brilho, realizar acabamento com um pano de microfibra.', 58.92, 58.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-820l6-mlc4uj1xut514b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F46806148614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
