INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18175041644', 'Lixeira de Cozinha Escritório Banheiro 5L com Tampa', '🗑️ Lixeira 5L – Design Sofisticado para Cozinha, Escritório ou Banheiro Leve mais elegância e funcionalidade aos seus ambientes com a Lixeira 5L com Tampa. Ideal para cozinhas, escritórios e banheiros, ela une praticidade e um visual moderno com acabamento premium. Sua tampa com efeito cromado fosco dá um toque de sofisticação, enquanto o corpo em plástico resistente garante durabilidade no uso diário. ✅ Destaques do Produto: • Design moderno com acabamento cromado na tampa • Compacta e versátil: perfeita para qualquer ambiente • Capacidade ideal de 5L para o lixo do dia a dia • Material durável e de fácil limpeza • Tampa com encaixe firme, que evita odores 📐 Especificações Técnicas: • Marca: SellNeeds • Capacidade: 5 Litros • Dimensões: 18,7 x 18,7 x 25 cm (CxLxA) • Material: Plástico Polipropileno (corpo) e PSAI de alto impacto (tampa) • Cores disponíveis*: – Preto com Dourado – Preto com Prateado – Branco com Dourado – Branco com Prateado *Envio conforme disponibilidade de estoque.', 56.84, 36.65, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2gle85rk7677', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F18175041644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
