INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259980483', 'PCV + respiro anti chama Volkswagen Golf MK4.5 2009 a 2014', '030103464A + 032103493AA PCV + respiro anti chama Volkswagen Golf MK4.5, 2009/2014, 1.6 Flex - 104cv Catálogo de Aplicações GoParts SOMOS CONCESSIONÁRIA VOLKSWAGEN COM MAIS DE 50 ANOS NO MERCADO! VWMONVEP NA CIDADE DE MONTES CLAROS – MG. PRODUTO NOVO E ORIGINAL VOLKSWAGEN HORÁRIO DE ATENDIMENTO: - SEG A SEX 08:00 – 18:00 - SAB 08:00 – 12:00 IMPORTANTE QUE LEIA TODAS AS INFORMAÇÕES DA DESCRIÇÃO NOTA FISCAL E GARANTIA: - TODAS AS PEÇAS COMPRADAS CONOSCO ACOMPANHAM NOTA FISCAL E GARANTIA. - GARANTIA DE FÁBRICA DE 3 MESES (CASO A PEÇA SEJA INSTALADA EM OUTRA OFICINA NÃO AUTORIZADA VOLKSWAGEN) - GARANTIA DE FÁBRICA DE 01 ANO (CASO INSTALE EM QUALQUER CONCESSIONÁRIA VOLKSWAGEN AUTORIZADA) - A GARANTIA VOLKSWAGEN É NACIONAL, PODE SER ATENDIDA EM QUALQUER CONCESSIONÁRIA VOLKSWAGEN DO BRASIL. ATENÇÃO! - ANTES DE EFETUAR A COMPRA TIRE SUAS DÚVIDAS SOBRE DISPONIBILIDADE E APLICAÇÃO DA PEÇA NO CAMPO DE PERGUNTAS, CASO SEJA NECESSÁRIO INFORME O NÚMERO DE CHASSI DO VEÍCULO. - PREÇO EXCLUSIVO PARA CLIENTES PESSOA FÍSICA (CPF). PARA EMPRESAS E PESSOAS JURÍDICAS CONFIRMAR VALORES NO CAMPO DE PERGUNTAS. CASO CONTRÁRIO A SUA COMPRA PODERÁ SER CANCELADA COM AVISO PRÉVIO. - NOSSOS ANÚNCIOS PODEM CONTER IMAGENS MERAMENTE ILUSTRATIVAS.', 260.06, 260.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-mcx107obd33t8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1653299428%2F58259980483', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192757268', 'Par De Alto Falantes 5 Bomber Original Montadoras 100w Rms', 'Alto Falante Bomber BBR 5 Polegadas 100W RMS 4 Ohms Bobina Simples Par Detalhes do Produto O alto falante Bomber da linha BBR de 5 polegadas foi desenvolvido especialmente para quem quer qualidade sonora com ótimo custo benefício. São feitos com materiais de qualidade, reproduzem todas as faixas sonoras e podem ser instalados em qualquer tipo de carro ou projeto de som automotivo. Compatibilidade Universal Modelo Disponível Bomber BBR Especificações Técnicas Tamanho de 5 polegadas Potência de 100W RMS (par) Impedância de 4 ohms Cone injetado em IMPP Bobina corpo em Kapton Suspensão em borracha Ímã de fluxo magnético Sensibilidade: 85 dB/W/m Fo: 100 Hz Resposta de frequência: 70 20.000Hz Medidas: 10,2 x 6,5 x 11,1 cm Peso: 650 gramas', 90.69, 80.64, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpju2l4kxtf398', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F22192757268', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50304902022', 'Conjunto Infantil Feminino Líder De Torcida', 'Descrição: Conjunto Infantil Feminino Líder De Torcida Conjunto em meia malha 50% algodão e 50% poliéster lindo. Cropped bege com estampa frontal e saia lilás com estampa rotativa e amarração frontal! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Verão - Gênero: Feminino - Tecido Peça: Meia Malha - Composição: 50% Algodão e 50% Poliéster - Faixa Etária: 1 à 12 anos - Evento: Não - Garantia: 1 Mês - Tipo de Manga: Curta - Tipo de Roupa: Conjunto - Tabela de Medidas: Tabela de Medidas Cropped: Tamanho | Busto | Comprimento 2 | 31CM | 25CM 3 | 33CM | 28CM 4 | 34CM | 31CM 6 | 35CM | 35CM 8 | 37CM | 38CM 10 | 40CM | 40CM 12 | 42CM | 42CM Tabela de Medidas Saia: Tamanho | Cintura | Comprimento 2 | 20CM | 24CM 3 | 21CM | 26CM 4 | 22CM | 28CM 6 | 23CM | 30CM 8 | 24CM | 32CM 10 | 24CM | 34CM 12 | 25CM | 36CM', 39.9, 32.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mjo1nfmqkvt13f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F50304902022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
