INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212910272', 'Vinho Tinto Fino Chileno Arrivo 31 Cabernet Sauvignon 750ml', 'VINHO TINTO CHILENO ARRIVO 31 CABERNET SAUVIGNON 750ML O sabor do Chile para transformar momentos simples em experiências especiais Nem toda ocasião precisa de uma garrafa cara para ser memorável. Seja em um churrasco com amigos, um jantar em família ou um momento de descanso após um dia corrido, o importante é ter um vinho agradável, equilibrado e que agrade facilmente diferentes paladares. Produzido no Chile com uvas 100% Cabernet Sauvignon, o Arrivo 31 apresenta aromas de frutas vermelhas maduras e delicadas notas de especiarias. No paladar, entrega uma experiência macia, equilibrada e fácil de beber, tornando-se uma excelente escolha tanto para apreciadores quanto para quem está começando a descobrir o universo dos vinhos. Sua versatilidade permite harmonizações perfeitas com carnes grelhadas, churrascos, massas ao molho vermelho, pizzas e tábuas de queijos. É aquele vinho que se adapta a diferentes ocasiões e sempre faz bonito à mesa. Destaques do Produto ✅ Vinho Tinto Chileno ✅ Uvas 100% Cabernet Sauvignon ✅ Aroma de frutas vermelhas maduras ✅ Toques suaves de especiarias ✅ Paladar macio e equilibrado ✅ Fácil de beber e harmonizar ✅ Excelente custo-benefício ✅ Garrafa de 750ml Harmoniza com 🍷 Churrascos 🍷 Carnes vermelhas 🍷 Massas com molhos encorpados 🍷 Pizzas 🍷 Queijos variados Informações Técnicas Tipo: Vinho Tinto Seco Uva: Cabernet Sauvignon Origem: Chile Teor Alcoólico: 13% Volume: 750ml Embalagem: Garrafa de vidro Um vinho para brindar bons momentos O Arrivo 31 Cabernet Sauvignon reúne sabor, qualidade e excelente custo-benefício em uma garrafa que combina perfeitamente com o dia a dia. Uma escolha segura para compartilhar com amigos, presentear alguém especial ou simplesmente aproveitar um bom momento com uma taça de vinho. Leve agora o sabor e a tradição dos vinhos chilenos para a sua mesa. 🍷', 199.0, 119.0, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-820l9-mppizm7awg7552', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F58212910272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
