INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297633577', 'Relógio Mondaine Feminino 1 Ano De Garantia Dourado Original', 'Procurando um presente perfeito? Encontrou! Dê um lindo Mondaine de presente para você mesmo, ou para alguém querido! *1 ANO DE GARANTIA MONDAINE - Produto com NOTA FISCAL* *ACOMPANHA SEMI JOIAS COLAR E BRINCOS* Atuamos somente com produtos 100% ORIGINAIS! Leve em um especialista de sua região para comprovar. Ficha Técnica PROVA D''ÁGUA: Sim - selo de resistência 5 ATM (resistência até 50 metros de profundidade) MATERIAL DO VIDRO: Cristal mineral resistente a riscos MAQUINÁRIO: Analógico - quartzo - bateria MATERIAL DO RELÓGIO: Liga de aço banhado a ouro COR DO FUNDO: Dourado Medidas TAMANHO DA CAIXA (mostrador): 4,3 cm (43 mm) ESPESSURA DA CAIXA (mostrador): 0,9 cm (9 mm) LARGURA DA PULSEIRA: 1,6 cm (16 mm) CIRCUNFERÊNCIA DA PULSEIRA: 26 cm Acompanha Relógio Mondaine, colar e brincos, caixa original Mondaine, manual de instruções em português, certificado de garantia e nota fiscal. A Mondaine produz as joias que acompanham o relógio de forma sortida, portanto as mesmas podem variar das imagens Nossos produtos são todos tratados com máximo cuidado, profissionalismo e atenção. Enviamos o seu relógio em uma embalagem reforçada, protegida por dentro e por fora. COMPRE COM SEGURANÇA Revendedor autorizado Mondaine', 259.9, 199.0, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/br-11134207-820mg-mqqb2in0ar5u7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400298075%2F18297633577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497381649', 'Pulseira de Milanese para Apple Watch 38 / 40 / 41MM Prata - Gshield', 'DESCRIÇÃO Deixe o seu Apple Watch com a sua cara! A Pulseira de Milanese para Apple Watch da Gshield, é moderna, flexível e confortável! Envolve o pulso de forma suave e se ajusta com perfeição. A regulagem pelo fecho magnético torna mais simples e cômodo o ajuste de comprimento no pulso. Se tiver dúvidas utilize o campo de perguntas no final da página ou leia as avaliações de outros consumidores. ESPECIFICAÇÕES Cor: Prata Marca: Gshield Regulagem: Fecho Magnético Material: Aço inoxidável Milanese COMPATIBILIDADE Compatível com Apple Watch 38 / 40 / 41MM ITENS INCLUSOS 1x pulseira Para Apple Watch 38 / 40 / 41MM GARANTIA 3 meses contra defeitos de fabricação + Garantia Vitalícia Co-Participativa AINDA TEM DÚVIDAS? Use o campo de perguntas no fim da página ou leia as avaliações de outros consumidores. TAGS Pulseira para smartwatch - pulseira para apple watch - pulseira para xiaomi mi band * Imagens meramente ilustrativas. Selos, ilustrações ou informações que constam na embalagem podem ser diferentes do produto disponível em estoque.', 65.97, 65.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7qvdj-lhs7f3q01zvy8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F21497381649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41624542687', 'Melatonina 30 caps Softgel Qualidade do Sono Ciclo Circadiano Íntera Calm - Soldiers', 'Suplemento Alimentar de Melatonina, Triptofano, Vitamina B3 e B6 em Cápsulas Principais benefícios: Fórmula desenvolvida para auxiliar na regulação do sono e no metabolismo energético. combina ativos que contribuem para o bem-estar físico e mental, favorecendo o relaxamento e o equilíbrio do organismo. Melatonina e triptofano: atuam na regulação do ciclo do sono. vitamina b3 (niacina): contribui para o metabolismo energético e manutenção da pele e mucosas vitamina B6: auxilia no sistema imune, na formação das células vermelhas do sangue e no metabolismo de proteínas e energia. RECOMENDAÇÃO DE USO: Ingerir 1 cápsula ao dia. INGREDIENTES: Óleo de girassol, L-triptofano, óleo de coco, água purificada, polpa de maracujá em pó, nicotinamida, cloridrato de piridoxina, melatonina, gelificante gelatina, umectante glicerol, emulsificante lecitina e corantes dióxido de titânio, amaranto, azul brilhante e óxido de ferro preto. ALÉRGICOS: Pode conter soja, leite, peixes, ovos, amendoim, amêndoa, avelãs, castanha-de-caju, castanha-do-pará, macadâmias, nozes, pecãs, pistaches, pinoli, castanhas, crustáceos (krill e caranguejo), trigo, centeio, cevada, aveia e suas estirpes hibridizadas e seus derivados. contém glúten Não contém quantidades significativas de carboidratos, açúcares totais, açúcares adicionados, proteínas, gorduras trans, fibras e sódio.', 75.9, 35.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820m7-moh8d87kcxdy60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347988064%2F41624542687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
