INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8675779004', 'Chicote de Pesca Cachimbo de Aço Para 2 Anzóis Summer', 'Chicote Cachimbo de Aço Para 2 Anzóis Summer, o chicotinho foi projetado para que você tenha mais praticidade em suas pescarias, pois basta apenas prender o anzol ou garatéia no snap, colocar o chumbo, e amarrar na linha do seu molinete/carretilha, e isto apenas na primeira pescaria, pois para as outras basta apenas você cortar da linha do seu molinete/carretilha e já deixar pronto com anzóis e chumbadas, com este chicotinho você terá mais eficácia em suas pescarias, pois terá como você amarrar 2 anzóis em um único chicote. Ideal para usar em pescarias no mar e praia. ESPECIFICAÇÕES: Marca: Summer Modelo: Chicotinho de Pesca P-2 Tamanho: 79cm Capacidade P/: 2 Anzóis Resistência: 21,6lbs', 21.89, 21.24, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rbna-lp5l939gm420a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F8675779004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
