INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22296882570', 'Tênis De Luzinha Menino Tenis Infantil Menino Led Colorida Sapato Infantil', 'Tênis Infantil com Luz de Led Colorida O Tênis de luzinha foi criado para as crianças super descoladas e que adoram se divertir. Ideal para passeios em família, e para a prática de esportes ou para ir à escola. O Tênis Led Colorida possui características esportivas. Seu solado possui pontos de flexão, que tornam o caminhar dos pequenos mais saudável. Cabedal em Mash Respirável, o tênis Calce Fácil permite maior respiração aos pezinhos. Ele cai perfeitamente em um look esportivo-casual. Composição do Calçado: Material: Têxtil Forro: Têxtil Palmilha: EVA Sola: Antiderrapante Tabelas de Medidas: Nº 20 – 13,8 cm Nº 21 – 13,8 cm Nº 22 – 15, cm Nº 23 – 15,2 cm Nº 24 – 15,8 cm Nº 25 – 16,4 cm Nº 26 – 17,4 cm Nº 27 – 18,0 cm', 113.9, 63.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98s-llm4k3vu9yeyae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F22296882570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
