INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793393953', 'Limpador de Parabrisa Citroen C5 ano 01 a 03 Universal', 'Descubra a excelência em limpeza de para-brisa com nossa linha de produtos premium. Projetados para oferecer durabilidade superior e desempenho sem ruído, nossos limpadores em silicone garantem uma visibilidade impecável, independentemente das condições climáticas. Encontre a solução ideal para manter sua visão nítida e sua jornada segura em todas as viagens. Compatível com: Limpador de Parabrisa Citroen C5 ano 01 a 03 Universal. Acompanha: 1 - Palheta Limpador de Para-brisa dianteiro Motorista 24" 1 - Palheta Limpador de Para-brisa dianteiro Passageiro 18" 1 - LIMPA PARA-BRISAS FORCE ONE 100ML Universal Investindo em qualidade e confiança, nossos produtos também incluem a garantia do fabricante de 90 dias. Adquira já e desfrute de uma visibilidade máxima com nossos limpadores de para-brisa premium', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdwr-m0q6rn7yxmxxae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1362877346%2F23793393953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294155630', '10 Discos De Corte 75mm X 1,40mm X 10mm Vonder', 'Conteúdo da Embalagem: 10 Discos de corte. Proporciona cortes rápidos e menor geração de calor e rebarbas. Indicado para corte de metais, inclusive aço inox. Utilizado em cortadores pneumáticos. Não utilizar em serra mármore. Detalhes Técnicos Modelo:DCV Diâmetro do disco de corte:75 mm Espessura:1,4 mm (+/-1/16") Tipo de disco:Tipo 41 Diâmetro do furo:10 mm Grão:G 46 Número de telas do disco:2 Rotação máxima do disco (rpm):20.300/min Segue norma(s):ABNT NBR 15230 e ABNT NBR 16245', 61.4, 45.37, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rav1-mawzd7psrnxl6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22294155630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48157151076', 'Jogo Chaves Fenda/Phillips CrV 8 Peças Denzel', 'Jogo de chaves composto por 8 peças ideal para trabalhos de montagem, manutenção e reparos gerais. Reune chaves tipo fenda e Phillips fabricadas em aço CrV, oferecendo resistência e desempenho em aplicações domésticas e profissionais. Compacto e completo, o conjunto atende diferentes bitolas de parafusos, facilitando a escolha da ferramenta correta sem necessidade de múltiplos kits. Acabamento e liga CrV garantem maior durabilidade e confiabilidade no uso cotidiano. Características: Modelo: 1221355 Referência: 1221355 Marca: Denzel Material: CrV (aço cromo-vanádio) Quantidade de peças: 8 Tipos: Fenda e Phillips Benefícios: Versatilidade para diversos tipos e tamanhos de parafusos. Maior durabilidade graças ao aço CrV. Conjunto completo reduz a necessidade de ferramentas adicionais. Adequado para uso doméstico e profissional. Facilita a execução de reparos e montagens com praticidade. Conteúdo da embalagem: 1 jogo com 8 chaves (Fenda e Phillips).', 130.83, 80.88, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82628-mlqu6ltco0edc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F48157151076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53057082531', 'Cavalete para Veículo Reforçado Ajustável 2T 280-420 MM 2 Peças STELS', 'O Cavalete para Veículo Reforçado Ajustável STELS é ideal para apoiar e estabilizar o veículo durante serviços de manutenção e reparos. Com capacidade de 2 toneladas e ajuste de altura entre 280 e 420 mm, oferece suporte seguro e versátil para diferentes necessidades de elevação. Construído em material reforçado e vendido em conjunto de 2 peças, o conjunto proporciona estabilidade e praticidade para uso em oficinas ou uso doméstico, facilitando posicionamento seguro do veículo e maior segurança durante intervenções. Características: Modelo: 5162155 Referência: 5162155 Marca: STELS Capacidade: 2T Altura ajustável: 280-420 mm Peças: 2 Benefícios: Suporte seguro para manutenção com capacidade de 2 toneladas. Ajuste de altura permite uso em diferentes tipos de veículos. Construção reforçada para maior durabilidade e estabilidade. Conjunto com 2 peças facilita apoio bilateral do veículo. Prático para oficinas e uso doméstico, aumentando a segurança do trabalho. Conteúdo da embalagem: 2 Cavaletes ajustáveis para veículo (conjunto com 2 peças).', 243.46, 165.82, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mloxf0krdbsw58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F53057082531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
