INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793839446', 'Haskell Lamelar - Máscara Líquida 200ml', 'Haskell Lamelar - Máscara Líquida 200ml A Máscara Líquida Lamelar é um tratamento intensivo e imediato de apenas 8 segundos. Ela foi especialmente desenvolvida para promover restauração ultraprofunda, repondo a massa capilar e proporcionando força extra aos fios. Ela reduz a porosidade e a aspereza das lâminas danificadas e alinha a fibra capilar. Indicada para todos os tipos de cabelo. Vegano, sem parabenos e corantes. No e low poo. Conselho de Aplicação Agite antes de usar. Após lavar os cabelos, aplique a Máscara Líquida Lamelar nos cabelos molhados e massageie todo o comprimento por 8 segundos. Em seguida, enxágue bem.', 156.15, 94.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5t-m7l9chbkpq6f48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23793839446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
