INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210767236', 'Kit 2 Pneus Moto Metzeler Roadtec Scooter 90/90-12 44J + 100/90-10 61J TL', '** PRODUTO NOVO ** GARANTIA DE FÁBRICA DE 5 ANOS ** EMISSÃO DE NF **O FATURAMENTO É REALIZADO APENAS PARA CONSUMO, SENDO VETADO O FATURAMENTO PARA REVENDA. ** SOBRE O PNEU: O novo produto concebido para todo o tipo de Scooters de a 10 a 16 polegadas, inspirado no multipremiado ROADTEC™ 01. O ROADTEC™ Scooter proporciona uma versatilidade e flexibilidade extrema em uma ampla gama de condições climáticas, temperatura ambiente e de asfalto, tanto em zonas urbanas como nos arredores.', 614.0, 540.32, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-820ll-moa317hwsj5z48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081431407%2F58210767236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8354024028', 'Pedal de Cambio Retrátil Pro Tork Modelo Original XL 250R 1982 1983 1984 1985 1986 Preto', 'O Pedal de Câmbio Retrátil XL 250R Pro Tork é fabricado em matéria-prima de alta qualidade, garantindo máxima resistência e segurança. Especificações: - Fabricado em Aço 1045T; - Modelo Original; - Cor: Preto; - Peça de reposição; - Marca: Pro Tork. Aplicação: - XL 250R 1982; - XL 250R 1983; - XL 250R 1984; - XL 250R 1985; - XL 250R 1986. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 84.11, 45.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/8bfe2a5580f8704853c4a497134ca355', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F8354024028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097556990', 'Panela Elétrica de Arroz Britânia PA5X BR 5 Xícaras', 'A Panela Elétrica de Arroz PA5X da Britânia proporciona muito mais praticidade em seu dia a dia e deixa sua cozinha mais moderna e suas refeições mais saborosas. Ela acompanha colher e copo medidor, possui tampa vedada, com alça, botão de travamento e saída de vapor. Ela faz todo o trabalho para você, te proporcionando mais comodidade e praticidade além de deixar seus alimentos mais saborosos, conservando seus nutrientes. Segurança e beleza também fazem parte das suas inúmeras vantagens. Ela possui desligamento automático, design moderno e pode ser levada a mesa, justamente pelo seu modelo moderno e arrojado. Ela deixa seus alimentos mais saborosos e seu dia a dia muito mais pratico. Características: Capacidade para 5 xícaras de arroz Capacidade 1 Litro Sistema de aquecimento automático Luzes indicadoras de funcionamento Faz diversos tipos de arroz Acompanha colher e copo medidor Tampa vedada, com alça, botão de travamento e saída de vapor Coletor de água Desligamento automático Lâmpada piloto Potência 400W Dimensões do Produto: Altura: 23 cm Largura: 20 cm Profundidade: 20 cm Peso: 1,66Kg Garantia do fornecedor de 12 meses.', 199.99, 199.99, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8wejz3p7neh64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F23097556990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694861426', 'Painel Suspenso Para TV Até 55 Polegadas Evo HB Móveis', 'O Painel Suspenso para TV até 55 Polegadas Evo HB Móveis é a escolha ideal para quem deseja um ambiente moderno, organizado e sofisticado. Com design contemporâneo e linhas elegantes, ele valoriza a decoração da sala e proporciona melhor aproveitamento do espaço. Indicado para TVs de até 55 polegadas, o painel é perfeito para compor salas compactas ou médias, deixando o ambiente mais clean e funcional. Seu formato suspenso facilita a limpeza e contribui para um visual mais leve e atual. Fabricado com materiais de qualidade, o painel oferece resistência, durabilidade e excelente acabamento, garantindo segurança para sua TV e um toque especial na decoração. ✨ Benefícios do Produto: ✔ Ideal para TVs de até 55'''' ✔ Design moderno e elegante ✔ Estrutura suspensa que facilita a limpeza ✔ Ótimo aproveitamento de espaço ✔ Combina com diversos estilos de decoração ➡️ Especificações Técnicas: Modelo: Evo Marca: HB Móveis Indicação: TV até 55 polegadas Material: MDP/MDF Acabamento: Pintura UV Produto entregue desmontado, necessita montagem Não acompanha: Suporte para TV Detalhes curvos: Na porta e no nicho lateral Prateleira superior com: Espessuras de: 25mm Porta basculantes com dobradiças metálicas: 01 Produzido em: MDP e MDF de 25mm, 15mm e 12mm Produto entregue desmontado, necessita montagem ➡️ Dimensões do Produto: Altura: 135cm Largura: 136 cm Profundidade: 28cm Peso: 29,85kg Garantia: 3 meses ⚠️ Observações Importantes: As imagens são meramente ilustrativas e não acompanham objetos de decoração e eletros; Pode haver alguma diferença de tonalidade entre a imagem e o produto, por conta do tratamento de imagens e a calibração de cores da sua tela; Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados ou imprevistos com a entrega do produto; A Lojas MM não se responsabiliza por montagens e instalações dos produtos.', 419.9, 419.9, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-82627-mky16ko31fk431', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F22694861426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23695875845', 'Escapamento Escape Para Moto Gemoto Racing 3 Trioval Titan Esd 150 2004 2005 2006 2007 2008', 'O ESCAPAMENTO GEMOTO RACING 3 TRIOVAL TITAN ESD 150 2004 - 2008 PRETO PONTEIRA foi projetado e desenvolvido com tecnologia de primeira linha, este modelo garante respostas mais rápidas da motocicleta, além de produzir um ronco único, sem ultrapassar os limites impostos pelos órgãos de regulação de fabricação. Especificações: - cores: Preto; - Produzido em aço de alta qualidade e resistência; - Marca: Gemoto. Aplicações: - TITAN ESD 150 - 2004; - TITAN ESD 150 - 2005; - TITAN ESD 150 - 2006; - TITAN ESD 150 - 2007; - TITAN ESD 150 - 2008; - A instalação deve ser feita por um profissional especializado. A Gemoto não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 352.53, 212.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lhhr9kwdruxae5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23695875845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20296905560', 'Escapamento Escape Pro Tork Next Para Moto Titan 150 Fan 150 Titan 160 Start 160', 'O Escapamento Next Titan/Fan 150/Titan/Start 160 Pro Tork foi projetado e desenvolvido nos Estados Unidos, com tecnologia de primeira linha, este novo modelo garante respostas mais rápidas da motocicleta, além de produzir um ronco esportivo único, sem ultrapassar os limites impostos pelos órgãos de regulação de fabricação. Especificações: - Cores disponíveis: Azul, Dourado, Preto, Rosa, Verde, Vermelho; - Fabricado em Alumínio; - Modelo: Next; - Marca: Pro Tork. Aplicação: - Titan 150 ES/ESD 2014; - Titan 150 ES/ESD 2015; - Fan 150 ES/ESD 2014; - Fan 150 ES/ESD 2015; - Start 160 2016; - Start 160 2017; - Start 160 2018; - Titan 160 2016; - Titan 160 2017; - Titan 160 2018. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa -se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 420.95, 263.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lgc7msmtyb273c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20296905560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697763516', 'Kit Forno Celeste Kappesberg 100% MDF 4 Portas Nogueira 70cm', 'Sua cozinha com toda a beleza e praticidade do Kit Forno N729 da Cozinha Celeste da Kappesberg. Produzido em chapa MDF de 15mm, ele garante robustez, firmesa e qualidade, além de um acabamento perfeito. Com sete camadas de pintura na cor nogueira, tanto na parte interna quanto na externa, seu acabamento touch, com a textura dos veios da madeira, além de combinar com todos os ambientes, garante a sensação de conforto e aconchego ao espaço, remetendo aos tons da natureza e deixando sua cozinha perfeita. A peça ideal para quem busca por otimização de espaço, contando com quatro portas e quatro prateleiras, além de prateleira reforçada em 25mm para eletrodomésticos, como forno ou microondas. Fechando ótimas combinações com balcões e aéreos, o destaque fica para as dobradiças com amortecimento, garantindo um fechamento suave e sem ruídos, incluindo mais durabilidade. E seus puxadores metálicos na cor dourada completam o design e a qualidade da cozinha, deixando seu ambiente ainda mais estiloso. Renove seu espaço e o deixe ainda mais completo com a Cozinha Celeste da Kappesberg. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O rodapé possui 16 centímetros de altura; O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1494.42, 929.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8260r-ml3ur28bcr9h14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22697763516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597928623', 'Mesa Diretor Kappesberg Office Platinum 190cm', 'A perfeita união entre elegância e funcionalidade com a Linha de Escritório Office Platinum da Kappesberg. Moderna, os produtos unem beleza e resistência, garantindo uma composição única. Versátil, a Mesa Diretor R803 é perfeita para o ambiente de estudo, escritório ou home office. Com 77cm de altura, 1,90m de largura e 70cm de profundidade, seu tampo é produzido em chapa MDP de 15mm e 25mm com acabamento BP, matéria-prima de alta qualidade e mais resistente contra riscos e arranhões. Com as bordas engrossuradas de 40mm, o tampo, na cor chumbo, proporciona elegância e sofisticação ao espaço, sendo perfeito para ambientes sóbrios, enquanto a estrutura da mesa é metálica, com tubo quadrado pintado com tinta epóxi na cor preto fosco, o que garante maior resistência e durabilidade contra a umidade. Uma combinação com um design único, garantindo beleza e destaque ao seu ambiente. Os diferenciais ficam por conta do passa fio, na parte superior do tampo, garantindo organização e praticidade, e das sapatas reguláveis, permitindo fácil ajuste em todos os pisos e proporcionando estabilidade. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1122.02, 799.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mm9d8gvqccgf6d', 'https://shope.ee/an_r