INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493843057', 'Bagageiro CG 160 Titan160 Fan160 Start 160 2025+ Bráz', 'Bagageiro Honda CG 160 Titan/Fan/Start Preto 2025 em diante Bráz Aumente a capacidade de carga da sua Honda CG 160 com o Bagageiro da Bráz Acessórios. Ideal para motociclistas que buscam praticidade e robustez no transporte de volumes. Compatível com sistemas de fixação de baús de diversas marcas líderes do mercado, este acessório oferece soluções de transporte adaptáveis às necessidades de cada piloto. Características Técnicas: - Conteúdo: Bagageiro Bráz + Manual de instalação; - Material: Tubo de aço carbono 5/8" e Chapa de aço carbono 2mm; - Acabamento: Pintura epóxi eletrostática; - Dimensões: 39 x 6 x 32cm. - Peso: 2,1 kg; - Cor: Preto Fosco; - Fixação: Instalação direta nos pontos de ancoragem originais da moto; Principais Benefícios: - Instalação simples e versátil para baús de diversas marcas líderes do mercado; - Mais espaço para transporte de volumes, sem afetar a estabilidade da sua motocicleta; - Design robusto para garantir a fixação segura da carga, evitando deslocamentos indesejados durante o trajeto; Garantia: - 3 meses contra defeitos de fabricação. Aplicação: - Honda CG 160 Titan 2025+ - Honda CG 160 Fan 2025+ - Honda CG 160 Start 2025+ Garanta mais praticidade e segurança para sua Honda 160 com o Bagageiro Bráz Acessórios e otimize seus transportes e viagens!', 196.51, 186.69, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/sg-11134201-823oc-morhulwogaa4cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951482108%2F23493843057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
