INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593867575', 'Desodorante Rexona Feminino Roll On Active Emotion 50ml', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Rexona Women Active Emotion traz nova fórmula com micro cápsulas especiais que se depositam na superfície da pele e, quando uma situação emocionante causa transpiração, as cápsulas liberam a proteção desodorante. Por isso, você é capaz de tudo. E sem transpirar. Faça o que fizer, Rexona não te abandona.', 7.9, 7.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rdwo-mc9a5dvlqk3b3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F23593867575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
