INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898200288', 'Passadeira a Vapor Alta Potência 1300w 1,6L Roupa Onistek ON-PR901', 'Passadeira a Vapor Onistek ON-PR901 oferece alto desempenho, praticidade e versatilidade para quem busca eficiência no cuidado com roupas. Com potência de 1300W e vazão de vapor entre 32 e 35g/min, proporciona um alisamento rápido e eficaz, mesmo em tecidos mais resistentes. Possui 10 modos selecionáveis, permitindo ajuste preciso para cada tipo de tecido, garantindo segurança e resultado ideal em todas as peças. Conta com um tanque de água de 1,6L, oferecendo maior autonomia durante o uso e reduzindo a necessidade de reabastecimento. Atinge temperatura de vapor de até 98°C, ideal para higienizar e desamassar com facilidade. Disponível nas versões 110V e 220V, adapta-se às diferentes necessidades do usuário. ESPECIFICAÇÕES: - Modelo: ON-PR901/110V e ON-PR901/220V - Potência: 1300W - Vazão de Vapor: 32-35g/min - Voltagem: 127V ou 220V - 60Hz - Temperatura do Vapor: 98°C - Capacidade do Tanque de Água: 1,6L - Modos de Operação: 10 seleções para diferentes tecidos CONTEÚDO: 1 Passadeira a Vapor', 362.5, 355.25, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/sg-11134201-7rasa-mabm627s398qa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F19898200288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
