INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201717358', 'Piso De Banheiro 50x70cm Juliet Karsten', 'Confeccionada em 100% algodão com fio de dupla torção, a Toalha de Piso Juliet da Karsten possui gramatura de 680g/m², o que garante excelente absorção, maciez e uma sensação acolhedora ao sair do banho. Seu corpo em jacquard confere textura sofisticada, enquanto o acabamento cotton eleva o visual com um toque refinado. A tecnologia Karsten Softmax intensifica a suavidade e o desempenho da peça, tornando o uso ainda mais agradável no dia a dia. A toalha é pré-encolhida e possui tratamento antipilling, o que assegura maior durabilidade e conservação da aparência, mesmo após-Lavagens repetidas.', 41.9, 41.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-822xr-mi24cyxwq51ec7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F58201717358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
