INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797727790', 'Haste de Aterramento EV 10mm X 1200mm - EV166', 'As Hastes de aterramento são usadas para permitir que através do aterramento, essas correntes de fuga serão transmitidas para a terra, de modo a evitar o acúmulo dessas correntes na carcaça do equipamento. Desse modo, seu equipamento estará protegido contra danos maiores, de modo que sejam absorvidos sem maiores danos', 27.37, 21.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rd5p-lwzrupt7jmiy65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F19797727790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
