INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197473496', 'Lona Polietileno Laranja 3X3 Metros Resistente Para Caminhão/Piscina/Camping/Construção Civil/Náutica 954 - 6168033000', 'Lona Polietileno Laranja 3X3 Metros Resistente Para Caminhão/Piscina/Camping/Construção Civil/Náutica 954 - 6168033000 A lona é produzida com tecido trançado de polietileno; possui ilhoses metálicos em cada canto e ao redor da bainha a cada 1 metro. O material é versátil, altamente resistente. Características: - Marca: Nove 54 - Referência: 6168033000 *Imagens meramente ilustrativas. Espeficiações técnicas: - Material: Polietileno de alta e baixa densidade, com aditivo que protege contra os raios ultravioleta - Cor: Laranja - Ilhoses metálicos a cada 1 metro - Possui fio sintético ao redor da bainha para maior resistência - Tamanho: 3 x 3 metros - Excelente material - Impermeável - Fácil de limpar - Prático - Indicado para agricultura, construção civil, náutica, camping, pesca, recreação, utilidades domésticas, entre outros Conteúdo da Embalagem: - Lona Polietileno Laranja 3X3 Metros 954 - 6168033000', 45.5, 45.5, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/sg-11134201-7r9ar-ln7pcn7bo3zgd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F21197473496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097806556', 'Caixa Organizadora com Gavetas de Plástico OPV 080 17,0 cm x 12,5 cm x 6,5 cm Vonder - 6108080000', 'Organizador plástico, 17,0 cm x 12,5 cm x 6,5 cm, OPV 080, VONDER 6108080000 Indicado para acondicionar peças e acessórios de pequeno porte, material de pesca, parafusos, pregos, porcas, remédios, entre outros. Características: - Marca: Vonder - Modelo: OPV 080 *Imagens meramente ilustrativas Especificações técnicas: - Material: Polipropileno com cantos emborrachados - Comprimento: 17,0 cm - Largura: 12,5 cm - Altura: 6,5 cm - Capacidade de carga (kgf): 3 kgf - Cor do organizador para ferramentas: Transparente e amarelo - Massa aproximada (peso): 0,203 Kg Conteúdo da embalagem: - 1x Organizador Plástico. - 11x Divisões - 1x Trava, cantos emborrachados - 1x Bandeja.', 62.0, 62.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-lxu3a6az101ydd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F18097806556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898029959', 'Ventilador De Parade Ventisol 50cm 6 Pás Preto Bivolt', 'O Ventilador De Parede Ventisol 50cm 6 Pás Preto Bivolté a solução ideal para quem busca potência, eficiência e design moderno em um único produto. Com uma hélice de 6 pás, este ventilador garante uma circulação de ar superior, proporcionando frescor e conforto em ambientes de médio e grande porte. Sua capacidade de oscilação permite a distribuição uniforme do ar, alcançando todos os cantos do cômodo de forma rápida e eficaz. Detalhe do produto: Diâmetro de 50cm: tamanhoideal para garantir um excelente alcance de ventilação, sem ocupar muito espaço. Bivolt (110V/220V): Sistema adaptável a qualquer rede elétrica, garantindo versatilidade e fácil instalação. Potência de 200W: potenteo suficiente para proporcionar uma ventilação rápida e eficaz, mantendo o ambiente agradável mesmo nos dias mais quentes. Proteção Térmica: Sistema de segurança integrado que desliga automaticamente o motor em caso de sobreaquecimento, aumentando a vida útil do produto e garantindo mais segurança ao usuário. Rolamento: A tecnologia de rolamento proporciona maior durabilidade e desempenho mais silencioso durante o uso. Grade de Aço e Hélice Cinza: A grade robusta de aço garante maior resistência e durabilidade, enquanto a hélice cinza oferece um toque de sofisticação ao design. Regulagem de Inclinação: Permite ajustar a direção do fluxo de ar conforme a necessidade, proporcionando conforto personalizado.', 513.9, 282.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7repd-m2vggoxw4k9zcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F23898029959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
