INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993174693', 'Regulador De Voltagem 12v Ys 250 Fazer 2006 A 2009 Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Regulador de Voltagem 12V YS 250 Fazer 2006 a 2009 Gauss Tenha o máximo de desempenho e segurança em suas viagens e passeios com os produtos Gauss.Este Regulador de voltagem é perfeito para a sua moto trazendo o melhor desempenho e segurança da Gauss para seu veículo. O Regulador de Voltagem vendido possui as seguintes características: - Qualidade do equipamento original da moto - Embalagem com selo de segurança garantindo a procedência e autenticidade Dúvidas Frequentes Porque escolher a Gauss? Qualidade e referência de mercado garantida! Com mais de 20 anos de tradição no mercado automotivo a Gauss comercializa mais de 28 milhões de peças por ano, todo esse trabalho é certificado pelas normas da ISO 9001 o que comprova a qualidade dos produtos comercializados. Compatibilidade com os seguintes veículos: Yamaha YS 250 Fazer 2006 Yamaha YS 250 Fazer 2007 Yamaha YS 250 Fazer 2008 Yamaha YS 250 Fazer 2009 Especificações Técnicas do Veículo: Veículo: YS 250 Fazer Montadora: Yamaha Ano: 2006 a 2009 Especificação Técnica - Regulador de Voltagem: Origem: Importado Voltagem Alternador: 12 Modelo: Ys Cilindrada: 250 Complemento: Fazer 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 92.99, 92.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kq2kkaa2dh15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22993174693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16673364021', 'Manta Forro de Capô March 2012 2013 2014 2015 2016 2017 2018 2019 2020 Anti Ruido Termica', 'Manta Termo Acústica Forro de Capô Modelo Original Auto-Colante Completo com Kit de Presilhas de Fixação Aplicação: Nissan March 2012 2013 2014 2015 2016 2017 2018 2019 2020 Dados Técnicos: • Feltro Isolante Automotivo de 5mm Espessura • Tratamento Betumado Auto-Extinguível - Parte Escura do Feltro • Isolante Termo Acústico • Camada Adesivada a Base d''água • Acompanha Kit de Presilhas para Furos Originais do Capô • Corte a Laser Especifico para Cada Veículo • Preserva a Pintura do Capô • Diminui o Ruído do Motor • Mantem a Originalidade • Maior Durabilidade em Serviços de Cristalização e Polimentos. • Completo Pronto para Instalar • Não Necessita de Ferramentas - Faça você Mesmo. Marca: • GRUD Acessórios Automotivos - Pioneira na fabricação de Mantas e Forros, Apresenta no mercado automotivo os mais avançados e eficientes produtos de isolamento termo acústico. OBS: Atenção aos modelos Similares de Baixo Custo, Sem as Presilhas, Com Adesivo Fraco e Cortadas à Mão, Correndo o Risco do Forro Cair sobre o Motor, Nossas são com Adesivos de Alta Performance, Presilhas Especificas e Corte a Laser. Garantia: 3 Meses / SAC Pós Venda Conteúdo: • 1 Manta para Capô Adesiva • 1 Kit com Presilhas de Fixação • 1 NF-e Pronta Entrega.', 59.9, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/18e6608e4bd9c903edc51afb69021c62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388235108%2F16673364021', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
