INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297538645', 'Fralda Huggies Tripla Protecao M 42 Unidades', 'A Fralda Huggies Tripla Proteção contém a tecnologia X-Protect, que permite que a fralda fique mais seca, tenha maior absorção e um sistema melhor de antivazamento. Isso sim é uma Tripla Proteção Garantida. A fralda possui também fechos macios com sistema abre e fecha e é dermatologicamente testada.', 73.91, 73.91, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-lvez613lvcqgbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23297538645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
