INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40967796373', 'Retrovisor Ranger 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 Fixo', 'Código do produto: 208257 Retrovisor Ranger 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 Fixo VALOR ANUNCIADO REFERENTE A UNIDADE. Os retrovisores são peças essenciais que viabilizam a segurança, tanto do motorista quanto dos passageiros, como por exemplo nas ultrapassagens. Composto por materiais da mais alta qualidade, nossos retrovisores tem todas as qualificações procuradas. Compatível com: FORD - Ranger 2013 - Ranger 2014 - Ranger 2015 - Ranger 2016 - Ranger 2017 - Ranger 2018 - Ranger 2019 - Ranger 2020 - Ranger 2021 - Ranger 2022 Especificações Técnicas: - Regulagem: Fixa - Material da Carcaça: Plástico ATENÇÃO O valor anunciado é referente a unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 328.35, 328.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-824jg-mebbi2ak1ybnc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F40967796373', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
