INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393897727', 'Kit Reparo Rolamento Dianteiro Mitsubishi L200 4x4 (99-07) L300 (95-99) Pajero (92-19) - IRB915', 'Os Kits de Rolamentos contam com rolamento interno, rolamento externo, graxa e retentor para aplicação! Especificações Técnicas: • Marca: IRB Automotive • Cód. da montadora: 713619140 • Posição: Roda Dianteira • Cód. de similares: ASH006K / VK0051DM / VKBA1915 Aplicações: - Mitsubishi L200 2.5 4x4 (1992 – 2007) - Mitsubishi L300 2.5 (1995 – 1999) - Mitsubishi Pajero 2.5 (2006 – 2019) - Mitsubishi Pajero 2.8 (1992 – 2006) - Mitsubishi Pajero 3.0 (1992 – 2005) - Mitsubishi Pajero 3.5 (1998 – 2019) - Hyundai Galloper 2.5 / 3.0 V6 (1992 – 1997) Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. IRB é uma marca que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar ano, modelo e se o veículo é com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 139.9, 124.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8kv5hd4f9jl8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F23393897727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208825814', 'Calcinha Caleçon Modeladora Sem Costura Segunda Pele', 'Com cós alto de 15 cm que proporciona máxima sustentação e definição da cintura, a Calcinha Caleçon Modeladora Sem Costura Segunda Pele é ideal para quem busca uma modelagem que envolve a região abdominal com estabilidade, criando um efeito mais uniforme no corpo. O cós mais alto atua de forma abrangente na região da cintura e abdômen, oferecendo compressão média a alta com conforto. Confeccionada em poliamida de alta qualidade (85% poliamida e 15% elastano), a peça oferece respirabilidade e alta elasticidade, adaptando-se ao corpo com precisão juntamente ao acabamento termofusionado, que evita marcações e relevos sob as peças. ONDE USAR Perfeita para acompanhar você em diferentes momentos: • No dia a dia, com sustentação prolongada • Com roupas ajustadas, ajudando a modelar a silhueta • Em ocasiões especiais, para um visual mais uniforme • Em viagem, quando conforto contínuo faz toda a diferença PRINCIPAIS INFORMAÇÕES • Tecnologia sem costura: não marca na roupa • Efeito segunda pele: leve, confortável e imperceptível • Acabamento termofusionado: ajuste perfeito ao corpo • Efeito modelador: compressão média que valoriza a região abdominal • Cós de 15 cm: alta sustentação e definição da cintura • Modelo Caleçon: máxima cobertura com estabilidade', 129.9, 77.94, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/br-11134207-820l6-mn1p88simu4k44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1571987839%2F58208825814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
