INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799834522', 'Amortecedor Original Cofap Gol Parati Saveiro G2 G3 G4 + Kit', 'Conteúdo: 01 Amortecedor Dianteiro + 01 Batente com 01 Coifa Marca: Amortecedor: Cofap / Batente e Coifa: Similar Ref: Amortecedor: 32208 / Batente e coifa: G61395 Garantia: 24 meses p/ os amortecedores / 03 meses demais peças APLICAÇÃO: VOLKSWAGEN GOL - 1980 A 1994 FURGÃO MODELOS ANTIGOS SAVEIRO - 1982 A 2009 EXCETO GERAÇÃO 5 A Cofap é uma das maiores empresas de autopeças do Brasil e na campanha divulga a versatilidade de sua linha de suspensão para diferentes condições de dirigibilidade. O QUE É E COMO FUNCIONA? O amortecedor é um componente do sistema de suspensão dos veículos destinado ao controle das oscilações da mola. Localizado na região inferior do veículo, é um elemento de ligação entre a suspensão e a carroceria, que controla os movimentos das molas, e faz com que a roda do veículo mantenha a aderência ao solo. QUANDO SUBSTITUIR? A estabilidade, conforto e segurança ficam diretamente comprometidos se os amortecedores não estiverem atuando corretamente. Isso é verificado pela dificuldade no controle do veículo em curvas, freadas, pulos descontrolados das rodas e desgaste prematuro (ou irregular) dos pneus e demais componentes da suspensão. É importante a verificação periódica dos amortecedores, bem como dos demais componentes da suspensão, sempre que o veículo passar por uma revisão.', 148.0, 148.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbi8gujrcn362f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1118422269%2F20799834522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693127091', 'Lampada Led Farol Baixo Toyota Corolla 2015-2017 20000lm', 'Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - Lampada Led v10 HB3 - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Compatível Com: Lampada Led Farol Baixo Toyota Corolla 2015-2017 20000lm Lâmpadas Super Led ? 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! PAR DE LÂMPADAS SUPER LED V10 Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 64.9, 64.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxbh29max4eqed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23693127091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
