INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794190031', 'Mini Processador Oster Chrome 110V', 'Mini Processador Oster Chrome 110VCompacto e eficiente, é ideal para as tarefas diárias na cozinha. Design compacto com recipiente para até 3 xícaras. Pica, mói e tritura de maneira fácil e rápida até os alimentos mais duros. Motor de 125W com 2 velocidades – alta e baixa – e função pulsar. Diferenciais: 125W de potência 2 velocidades Lâminas em inox Especificações Técnicas: Modelo: 003320-017-000 / 003320-057-000 Tensão: 127V ou 220V (Não é Bivolt) Código do Produto: 003320 Potência: 125W Consumo: 0,13KWh Dimensões [LxAxP]: 215 x 175 x 130 mm Peso: 1,04 kg Código de Barras: 034264467149 / 034264467132 Classificação Fiscal / NCM: 8509.40.50 CEST: 21.041.00 Selo de Segurança: OCP NCC Certificações: Inmetro Código da Certificação: NCC Medidas Embalagem [LxAxP]: 220 x 200 x 140 mm Peso: 1,34 kg Garantia: 12 meses', 179.9, 179.9, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-7rdxm-mbpikc67tica6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23794190031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
