INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193427367', 'Caneta gel Gelocity Quick Dry 0.7mm Preta Bic', 'INMETRO 004111/2024 Experimente cores vivas e escrita super macia com as canetas de gel Gelocity Quick Dry da Bic. Estas canetas de gel de ponta média de 0,7 mm e secagem rápida são perfeitas para escrever no dia a dia no trabalho, escola ou casa e têm tinta de fluxo fácil que escreve fluidamente e sem esforço. Detalhes: - Cor: Preta - Retrátil - Leve - Secagem rápida - Caneta em gel - Ponta fina de 0,7 mm - Escrita macia e suave', 28.05, 22.44, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-7rdys-m0vy1ofqmw5q13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616550287%2F22193427367', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15186191909', 'Vinho Pulenta Estate Iii Cabernet Sauvignon 2018 750ml', 'Este Cabernet Sauvignon da Argentina, apresenta notas de frutas vermelhas maduras como morangos, cerejas e amoras. Uma nota de piemntão assado também aparece no paladar. De final longo e persistente com taninos aveluladados.', 223.08, 223.08, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/d488cec9dac0aae3003112d3f4ff3fde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F15186191909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20107178955', 'Gin Seagers 1000ml', 'No ano de 1934 o Sr. Francis Burdett Peach teve a então revolucionária ideia de trazer para o Brasil o Gin Seagers. Francis recebeu permissão e a fórmula original da renomada empresa Seagers Evans Co, empresa britânica produtora de prestigiados gins. No Brasil, o Gin Seagers é produzido pela Destilaria Stock há mais de 80 anos, utilizando a mesma fórmula, sob a supervisão da Seagers Evans Co. Esse é um dos motivos do Seagers ser líder do mercado de gins no Brasil, além de seu preço competitivo quando comparado aos semelhantes importados. Seu estilo é o London Dry Gin, com sabor e aroma majoritariamente de zimbro, além de notas cítricas de cascas de laranjas e especiarias.', 69.9, 69.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/4ebf0100ff79c39b5a2e9a5ebd639e92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F20107178955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12873960322', 'Vinho Latitud 33 Malbec 750ml', 'O nome Latitud 33º faz referência à latitude, no Hemisfério do Sul, onde se localizam os vinhedos que dão origem a este vinho. Este tinto que traz a uva emblemática da Argentina, é muito agradável no paladar e fácil de combinar com receitas cotidianas. Este tinto traz a uva emblemática da Argentina de forma expressiva, frutada e harmoniosa. Da vinícola Latitud 33º, este Malbec respeita a variedade típica à altura com um breve amadurecimento em barricas de carvalho. É um vinho muito agradável ao paladar e fácil de beber que não poderíamos deixar fora de nossa seleção. De coloração vermelho escuro com tons azulados, este Malbec é poderoso e elegante. Aromático, tem um caráter frutado de ameixas secas, cerejas e geleia, integradas com notas sutis de chocolate amargo, figos secos e caramelo. A princípio, é sacarose e com taninos amigáveis e redondos, mas revela untuosidade e acidez refrescante. É um vinho muito versátil que você pode provar sem pestanejar.', 59.9, 59.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/d52010a6f46e366981b56c4c6aa5a64d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F12873960322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
