INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993255264', 'Seal Up Pó Solto Facial BM Beauty', 'Seal UP, nosso pó facial, é ultramicronizado, com fórmula exclusiva enriquecida com Niacinamida, que traz inúmeros benefícios à pele. SEAL UP é a prova d''água, resistente à oleosidade e ao suor, tem o poder de selar, matificar e fixar a maquiagem sem pesar, garantindo conforto com maior durabilidade, proporcionando pele aveludada com acabamento perfeito. Contém 15g Ingredientes Talc, Polymethylsilsesquioxane, Aluminum Starch Octenylsuccinate, Silica Dimethyl Silylate, Phenoxyethanol, Aqua, Niacinamide. Pode conter: CI 77891, Triethoxycaprylylsilane, Aluminum Dimyristate, Disodium Stearoyl Glutamate, Titanium Dioxide, CI 77499, CI 77492, CI 77491. IMAGEM MERAMENTE ILUSTRATIVA', 89.9, 89.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-7reqp-m80p9dal0i35d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314305321%2F23993255264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208681869', 'Bucha Amortecedor Sup E Inf Traseiro Dianteiro Vw 7100 7110', 'BUCHA AMORTECEDOR SUPERIOR E INFERIOR TRASEIRO E DIANTEIRO VW 7100 - 7110 - 7120 - 8100 - 8120 - 8140 - 8150 - 9150 Dimensões: Ext. 37mm x 32mm x Int. 19mm x Comp. 44,5mm NOSSOS PRODUTOS, VOCÊ NEGOCIARÁCOM UMA EMPRESA SÉRIA QUE ALÉM DE CONHECER BEM SEU VEÍCULO É LÍDER DE VENDAS NOMERCADO LIVRE. QUALIDADE QUE PROPORCIONA OCONFORTO E SEGURANÇA DO CONDUTOR; *PRODUTO NOVO, TESTADO E APROVADO; *EMPRESA 100% DENTRO DAS NORMASFISCAIS; * GARANTIA: GARANTIA LEGAL DE 90 DIAS CONFORME CÓDIGO DE DEFESA DO CONSUMIDOR (ART. 26, II) POR PARTE DA LOJA E TAMBÉM A GARANTIA PROPORCIONADA PELO FABRICANTE. ------------------------------------------------------------------------ CÓDIGO DA PEÇA: R612 APLICAÇÃO POR MODELO DE VEÍCULO: VOLKSWAGEN: VW: 7.100 - 7.110 - 7.120 - 8.100 - 8.120 - 8.140 - 8.150 - 9.150 - L 80 Ônibus: 8.120OD - 8.140CO CKD - 8.140CO/CE - 8.150E - 8.150EOD - 9.150EOD - 9.150OD Delivery: 10.160 - 5.150 - 8.160 - 9.160 FORD: Novo Cargo: 815 - 816 CONTEÚDO DA EMBALAGEM (O QUECHEGARÁ NA SUA CASA/EMPRESA): 01 (UMA) BUCHA DO AMORTECEDOR OBSERVAÇÕES: Produto alternativo de ótima qualidade com nota fiscal e garantia. PARA ENVIARMOS A PEÇA CORRETA E EVITAR INCONVENIENTES, NOS ENVIE O NÚMERO DO CHASSI, MARCA, ANO E MODELO DO VEÍCULO. PARA MELHOR COMPREENSÃO, VAMOS ADOTAR O LADO ESQUERDO COMO SENDO DO MOTORISTA E O DIREITO COMO SENDO DO PASSAGEIRO. ------------------------------------------------------------------------ SEDIADA EM BOTUCATU, INTERIOR DO ESTADO DE SÃO PAULO, CONTA COM UMA EQUIPE DE PROFISSIONAIS ESPECIALIZADOS EM APRESENTAR A MELHOR SOLUÇÃO EM PEÇAS PARA O SEU VEÍCULO E PARA O SEU NEGÓCIO. COM UM PROJETO DE VENDAS ONLINE, ONDE EMPREGAMOS TODO O CONHECIMENTO DO MERCADO FÍSICO A FAVOR DA ASSERTIVIDADE, SEGURANÇA E COMODIDADE DE NOSSOS COMPRADORES. EM CASO DE DÚVIDAS, FIQUE A VONTADE PARA NOS ENVIAR PERGUNTAS E QUESTIONAMENTOS. SE POSSÍVEL INFORME O NÚMERO DO CHASSI, O MODELODO VEÍCULO, O ANO DE FABRICAÇÃO E TAMBÉM SE HOUVE ALGUMA MODIFICAÇÃO. ASSIM PODEMOS SER PRECISOS E EFICIENTES EM SUA RESPOSTA, PROPORCIONANDO UM MELHOR ATENDIMENTO. NOSSOS PRODUTOS SÃO NOVOS E ENVIADOS COM NOTA FISCAL. AGRADECEMOS A SUA VISITA E TORCEMOS PARA QUE AS INFORMAÇÕES ACIMA TENHAM AJUDADO DE ALGUMA MANEIRA SUA BUSCA. CASO AINDA HAJA ALGUMA DÚVIDA, DEIXE UMA PERGUNTA. RESPONDEREMOS O MAIS BREVE POSSÍVEL.', 12.28, 12.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-81zwf-mmxr3mqu0jcw48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1789543177%2F58208681869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
