INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198393082', 'Mesa Dobrável Dupla Vira Maleta Alça Camping Pesca Praia Mor', 'Mesa Dobrável Vira Maleta com Alça Camping Pesca Praia Mor A Mesa Prática Dupla é sinônimo de funcionalidade e praticidade em qualquer ambiente. Seja na praia, em balneários, acampamentos, piqueniques ou churrascos, ela é uma excelente opção de apoio e auxílio. Com pernas dobráveis e alça para transporte, é fácil de carregar e armazenar, já que se transforma em uma maleta. Compacta e versátil, possui três ajustes de altura para atender a diferentes necessidades. As pernas em alumínio tornam o modelo apropriado para uso no litoral. Já a sua ótima estabilidade ocorre por conta da estrutura metálica cruzada, que elimina oscilações. Possui ainda protetores para os pés que não danificam o piso. Descrição do produto Marca: Mor Pernas dobráveis: Sim Alça para transporte: Sim Cacapcidade: 40 kg Uso: Ideal para balneários, acampamentos, piqueniques e churrascos Medidas (Aberta) Nivel 1: 1,20m x 60cm x 55cm Nivel 2: 1,20m x 60cm x 62cm Nivel 3: 1,20m x 60cm x 70cm Medidas (Fechada): 60cm x 6,5cm x 61cm Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 377.69, 229.9, NULL, 'Sports & Outdoors > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rep0-m8jfuodh48tlfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F23198393082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
