INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262000730', 'Caixa de Som Bluetooth Karaokê i2GO Ultra Voice 650 100W – Portátil com Microfones e LED', 'Caixa de Som Bluetooth i2GO Ultra Voice 650 – Potência, Festa e Karaokê em um só produto! Transforme qualquer momento em uma verdadeira festa com a Caixa de Som i2GO Ultra Voice 650. Com som potente, conexão Bluetooth fácil e função karaokê, ela é perfeita para animar reuniões, churrascos, eventos e muito mais! Karaokê Completo para Diversão Garantida!!! Solte a voz e aproveite ao máximo: Entrada para microfone Controle de volume e efeito eco do microfone Modo karaokê com prioridade de voz Ajuste entre música e vocal Ideal para festas, família, amigos e apresentações! Som Potente com Ajuste Profissional Tenha controle total da experiência sonora: Modos de áudio: uso interno / reforço de graves / uso externo Ajuste de Volume geral Graves, Agudos Som forte e de alta qualidade, perfeito para ambientes grandes Conexão Bluetooth Rápida e Sem Complicação Pareamento simples com celular (sem necessidade de senha) Conexão automática via Bluetooth Compatível com Android e iPhone Alcance estável para reprodução contínua Bateria de Longa Duração Até ~10 horas de uso (volume médio + luzes ligadas) Uso contínuo de aproximadamente 4 horas em volume alto Indicador de carregamento inteligente Várias Formas de Reprodução Bluetooth (sem fio), Entrada USB (até 32GB – MP3), Entrada AUX (plug-and-play) Rádio FM Funções Inteligentes Controle completo no próprio painel Botões para Trocar músicas, Ajustar volume, Pausar/reproduzir Função TWS (conectar duas caixas) Indicadores LED de funcionamento (Bluetooth, USB, AUX) Ideal para Festas e eventos, Karaokê em casa, Uso em ambientes externos, Reuniões com amigos e família', 899.0, 699.9, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf