INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201104444', 'Engate Reboque Fixo Gol G3 G4 1999 a 2014 700 Kg - Brucke VW5000', 'Engate Reboque Volkswagen Gol G3 G4 1999 a 2014 Fixo 700 Kg Marca: Brucke Modelo: VW5000 - Compatibilidade: Volkswagen Gol G3 G4 1999 Volkswagen Gol G3 G4 2000 Volkswagen Gol G3 G4 2001 Volkswagen Gol G3 G4 2002 Volkswagen Gol G3 G4 2003 Volkswagen Gol G3 G4 2004 Volkswagen Gol G3 G4 2005 Volkswagen Gol G3 G4 2006 Volkswagen Gol G3 G4 2007 Volkswagen Gol G3 G4 2008 Volkswagen Gol G3 G4 2009 Volkswagen Gol G3 G4 2010 Volkswagen Gol G3 G4 2011 Volkswagen Gol G3 G4 2012 Volkswagen Gol G3 G4 2013 Volkswagen Gol G3 G4 2014 SOMENTE VERSÕES G3 G4 O Engate Reboque para o Volkswagen Gol G3 G4 de 1999 a 2014 Fixo da marca Brucke é a solução ideal para quem busca robustez e confiabilidade. Com uma capacidade de reboque de até 700 Kg, este modelo com ponteira Fixo tem resistência testada e garantida, garantindo que você possa transportar cargas pesadas com segurança! É compatível com carretinhas, trailers, transbikes. - Atributos do Produto: Tipo de ponteira: Fixo Medidas: 17 x 39 x 101 cm, 8kg. Capacidade de reboque tração: Até 700 Kg Capacidade de peso sobre a bola: Até 40 kg Material: Fabricado em Aço carbono Pintura: Acabamento em pintura eletrostática a pó na cor preta Homologação: Produto homologado pelo INMETRO (012587/2022) e regularizado conforme a resolução nº 197 do Contran. Acompanha bola de engate, tomada e acabamento (quando necessário) como nas imagens. Código interno: 860 Instalação: Instalação simples nas furações originais do veículo, sem necessidade de furos ou adaptações. A instalação deve ser feita por um profissional.', 543.43, 489.09, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-8227o-mhjmh