INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398674875', 'Kit com 3 Bíblias Sagrada Tamanho Médio 12,5x19 cm Com Harpa Palavras de Jesus em Vermelho (Kit M)', 'Bíblia Sagrada - LETRAS PEQUENAS - Harpa Cristã - Tamanho Grande - Palavras de Jesus em Destaque - Econômica - Edição Promessas - Versão Almeida - Capa Dura - Kit M Você que ama a palavra do Senhor tem hoje a grande oportunidade de adquirir esse modelo especial Luxo, mais barata com Letras pequenas Fonte Reduzida, Harpa Cristã, Tamanho medio e muito mais, ideal para Revenda, dar de presente, fazer ações de evangelismo ou para o seu dia a dia. Essa Bíblia além de ter preço muito acessível possui diversos atrativos, como: * Possui LETRAS PEQUENAS * As Palavras Ditas por Jesus são destacadas em Vermelho * Harpa Cristã; * Versão Tradicional * João Ferreira de Almeida Revista e corrigida; * Capa Luxo * Possui índice na Lateral da Bíblia Tamanho MÉDIO: 19cm Altura x 12,5 Largura * e muito mais...', 79.99, 72.0, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lih892y3l0n346', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F19398674875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
