INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253968038', 'Short Fightshort Venum UFC Shadow Guard Verde Militar MMA', 'Construído em tecido leve e altamente resistente, o short garante liberdade total de movimentação, permitindo executar com eficiência desde os golpes dinâmicos das artes marciais até os exercícios explosivos dos esportes de força. Seu corte anatômico foi desenvolvido para acompanhar cada movimento do corpo, proporcionando conforto e amplitude sem restrições. A estampa sublimada traz um visual arrojado e marcante, resistente ao desgaste do tempo e das lavagens, mantendo sempre a intensidade das cores. O sistema de fechamento seguro oferece estabilidade durante os treinos e lutas, evitando ajustes constantes e garantindo confiança até nos momentos de maior intensidade. Características técnicas • SKU: BR-VENUM-7200-009 • Peso: 200 Gramas • Composição: 100% Poliéster • Cor: Verde • Shorts: Fightshorts • Esporte: Treino • Fabricante: Venum Brasil • Gênero: Masculino • Tipo de artigo: Bermudas • User level: Beginner, Intermediate, Advanced', 239.9, 169.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-8262v-mjumn0tmxhc567', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054067345%2F58253968038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
