INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393845887', 'Mochila Feminina Chenson Original New Cristal Costas 8485022', 'Mochila Feminina Chenson Original New Cristal Costas 8485022 Confeccionada em PU, material de excelente qualidade, essa linda mochila possui amplo espaço e compartimento para pequenos objetos. O forro em tecido personalizado com o logo Chenson e o fechamento principal com zíper personalizado garantem segurança e praticidade. A alça em PU e o acabamento em costura contrastante são detalhes que acrescentam charme e sofisticação. A mochila ainda acompanha um chaveiro espelho Chenson, com ferragens douradas que complementam o estilo único da peça. Medidas Aproximadas: Altura: 30 cm Largura: 14 cm Comprimento: 24 cm Cuidados: Guarde em um local seco e arejado, evitando locais úmidos. Evite colocar excesso de peso no produto para não forçar os zíperes e costuras. Proteja os objetos cortantes e/ou pontiagudos, evitando o contato direto com o produto. Evite altas temperaturas. Cores claras podem manchar ao entrar em contato com objetos ou roupas de cores pigmentadas. Dicas de Limpeza: Para a limpeza, utilize apenas pano úmido com sabão neutro. Não mergulhe na água e não utilize componentes químicos, solventes ou alvejantes. Não deixe de molho e seque à sombra.', 199.9, 199.9, NULL, 'Women Bags > Top-handle Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-m7mor2xu4duc7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F22393845887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198093849', 'Bolsa Feminina Chenson Monograma Delicado Alça de Ombro com Ferragem Original 3485474', 'Bolsa Feminina Chenson Monograma Delicado 3485474 A Bolsa Feminina Chenson Monograma Delicado 3485474 combina sofisticação e funcionalidade para acompanhar a rotina com elegância. Confeccionada em material sintético de alta qualidade, apresenta estampa monograma exclusiva Chenson, que exibe um visual moderno e atemporal. O modelo possui acabamento refinado, com ferragens metálicas douradas que valorizam ainda mais o design. Conta com alças de ombro em corrente metálica entrelaçada com material sintético, proporcionando conforto e um toque sofisticado ao uso. Seu fechamento superior é feito por zíper e botão magnético, garantindo mais segurança aos pertences. O interior é bem distribuído, com divisórias funcionais que facilitam a organização de itens essenciais, além de bolso interno. Na parte externa, possui bolso com zíper para acesso rápido. Acompanha chaveiro decorativo, agregando charme e personalidade à peça. Medidas Aproximadas: (A) 24cm x (L) 12cm x (C) 31cm Cuidados: - Guarde em local seco e arejado, evitando umidade. - Evite excesso de peso para não forçar zíperes e costuras. - Proteja de objetos cortantes ou pontiagudos. - Evite altas temperaturas. - Cores claras podem manchar ao contato com itens pigmentados. Dicas de Limpeza: - Limpe apenas com pano úmido e sabão neutro. - Não mergulhe na água nem utilize produtos químicos ou solventes. - Não deixe de molho e seque à sombra.', 484.9, 484.9, NULL, 'Women Bags > Tote Bags', 'https://cf.shopee.com.br/file/br-11134207-81zte-ml29ax8usqo1f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F19198093849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
