INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253864176', 'Óculos de Sol Feminino Anitta Aviador Marrom', 'Coleção: Anitta A Chilli Beans se junta à Anitta para criar uma coleção que vive o agora: shapes afiados, design trend e detalhes que transformam cada modelo em peça de estilo. Óculos de Sol Feminino Anitta Aviador Marrom, produzido em aço inoxidável que é um material leve e resistente. A haste dupla de metal vazada com formas triangulares que remetem ao A de Anitta com a ponteira chanfrada. As lentes possui proteção 100% contra raios UVA e UVB, protegendo seus olhos dos raios nocivos do sol reduzindo o risco de desenvolvimento das doenças oculares. A coleção de óculos Chilli Beans com Anitta chega com identidade própria. A assinatura da Anitta, feita à mão, marca cada peça como símbolo de atitude e autenticidade. Aqui, óculos não são só óculos: são acessórios, são moda, são expressão. Eles deixam de ser detalhe e assumem o protagonismo, feitos pra usar, pendurar, misturar, customizar e sair totalmente do óbvio. Ref.: OC.MT.4474.0221', 399.98, 399.98, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/sg-11134201-82606-mjsxhduxw9ab92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356106526%2F58253864176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253211282', 'Maybelline Lash Sensational - Máscara Para Cílios 9,5ml', 'Máscara para cílios preta lavável. Maybelline Lash Sensational proporciona definição em cada fio e longa duração. A Máscara de Cílios Maybelline Lash Sensational conta com a exclusiva tecnologia com 10 camadas de cerdas em seu aplicador, que consegue alcançar até mesmo os cílios menores para um olhar destacado e com um incrível efeito leque. Como usar: Aplique a máscara para cílios da raiz às pontas com movimentos de ziguezague. Para um efeito ainda mais dramático, invista em uma camada adicional antes da secagem da máscara. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 85.9, 85.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-82632-mjfxo5gvs0efc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253211282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
