INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21550881613', 'Cuba Luxo P/ Embutir Cozinha Gourmet Em Aço Inox Tubrax', 'Cuba de cozinha de embutir Tubrax - modelo CAC0019 A cuba de embutir Tubrax é ideal para quem procura soluções para cozinhas/área gourmet modernas com praticidade e estilo. Produzida em aço inox de alta qualidade, com chapa de 0,8 milímetros de espessura e acabamento acetinado, este produto transmite elegância e luxo ao seu ambiente. Manta emborrachada contra ruídos é um diferencial das Cubas Tubrax. Cuba projetada para aplicação somente embutida. ATENÇÃO: Cuba projetada para aplicação SOMENTE EMBUTIDA. Obs: Leves alterações na coloração e acabamento podem acontecer entre diferentes lotes do produto. ESPECIFICAÇÕES TÉCNICAS: - Marca: Tubrax - Referência do Modelo: CAC0019 - Acabamento: Acetinado escovado linear - Material: Aço Inoxidável 304 - Comprimento: 44 cm - Largura: 40 cm - Profundidade: 17 cm - Furo para válvula de 4½ " (Não incluso) - Peso bruto (com embalagem): 3,61 Kg - Garantia: 3 meses contra qualquer defeito de fabricação.', 359.9, 329.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-22110-9vlr4f7nuojv65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F497552438%2F21550881613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14981582420', 'Cabide de Veludo Infantil 50 Unidades bebe ultrafino luxo', 'Este anúncio contém: Kit 50 Cabides Veludo Infantil Slim Antiderrapante As roupas das crianças vão ficar mais organizadas com os Cabides De Veludo Infantil! Quem tem crianças sabe que cuidar da organização das roupas dos pequenos pode ser uma verdadeira batalha! Mas existem acessórios que podem te ajudar a vencer essa guerra de uma vez por todas, como os Cabides De Veludo Infantil! Com um design delicado e tons neutros como o bege e o preto, ele combina com todas as peças, e traz um charme mais especial para o closet dos pequenos! Perfeito para closets, guarda roupas e lojas infantis garantindo a organização e sofisticação de qualquer ambiente. Características: Cores disponíveis: Rosa, Azul, Bege e Preto Curvas delicadas que conservam o formato das roupas; Textura aveludada; Uso indicado: roupas no geral. Dimensões do produto: Largura: 30 cm Altura: 20,5 cm Espessura: 0,4 cm Peso: 55 g Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, com garantia de 3 meses. 2 - Produto a pronta entrega. 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 129.0, 62.9, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/sg-11134201-824i4-mpiavdot6tjicb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F762383390%2F14981582420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
