INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694299167', 'VERNIZ ACETINADO MADEIRA PROTEGIDA (MARITIMO) 0,9L SUVINIL PROTEÇÃO DUPLA INTERIOR EXTERIOR', 'Verniz Suvinil Proteção Dupla Acetinado é um verniz marítimo para madeira com alta resistência contra sol e chuva. Ele mantém o aspecto natural da madeira ao realçar os seus veios. Indicamos verniz marítimo para madeira externa e interna. Ele trará proteção e um visual renovado para a sua casa. Demãos 2 a 3 demãos Secagem Ao toque: 4 a 6 horas Entre demãos: 12 horas Final: 24 horas Peso 0.9 L: 0.812kg Diluição Pintura sobre madeira nova e repintura com 10% de Suvinil Aguarrás em todas as demãos. Para aplicação com pistola diluir com 20% de Suvinil Aguarrás, pressão entre 2,2 e 2,8Kgf/cm² ou 30 a 35lbs/pol². Rendimento Branco e cores 0.9 L - 4m² acabados. Rendimento obtido pelo método ABNT NBR 14942. Variações devido à superfície e/ou aplicação podem ocorrer. Consulte o boletim técnico para mais informações VERNIZ ACETINADO MADEIRA PROTEGIDA (MARITIMO) 0,9L SUVINIL', 99.34, 99.34, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-md6dps598o5wbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F23694299167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297443231', 'Película para Samsung Galaxy A15 - Traseira Hydrogel HD - Gshield', 'DESCRIÇÃO Aumente a resistência do seu Samsung Galaxy A15 LTE com a película de Hydrogel! A Película de Hydrogel da Gshield oferece uma proteção avançada para a traseira do seu Samsung Galaxy A15 LTE, garantindo uma experiência duradoura e sem preocupações. Desenvolvida com a inovadora tecnologia hidro nano pet e TPU Soft Gel, essa película é resistente contra riscos indesejados. O revestimento oleofóbico da película não apenas aprimora a resistência contra arranhões, mas também reduz as marcas de digitais na traseira, proporcionando uma aparência limpa e sem marcas. A adaptação perfeita às extremidades curvadas do seu dispositivo assegura uma cobertura completa do dispositivo. Escolher a Película de Hydrogel Gshield é optar por um escudo de proteção sofisticado, que une tecnologia de ponta e durabilidade para manter a traseira do seu celular impecável. Cuide do seu Samsung Galaxy A15 LTE com estilo e confiança, investindo na excelência em proteção que só a Gshield proporciona. Clique aqui para acessar os manuais dos produtos Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: Gshield Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à traseiraGrau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rcey-ltnwgu34uh9470', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23297443231', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
