INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693884241', 'Coturno Bota Tático Airstep Easy Boot Light 8628 Preta', 'O Coturno Bota Tático Airstep Easy Boot Light 8628-1 Black é a escolha ideal para quem busca durabilidade e conforto em diversas situações. Desenvolvido para climas tropicais, esse modelo possui tecnologia de repelência à água e ao calor, garantindo desempenho em ambientes quentes e úmidos. O design moderno e versátil permite que seja utilizado tanto em trilhas e atividades outdoor quanto no dia a dia. Com um cabedal em couro hidrofugado de 2,0mm e forração interna respirável, o Airstep oferece conforto e proteção com seu zíper YKK lateral, que facilita o calce sem a necessidade de desamarrar os cadarços. O solado em EVA bi componente proporciona leveza e absorção de impactos, enquanto a palmilha anatômica garante maior conforto e gerenciamento do suor. Seu bico costurado e inclinada assegura resistência e formato durável mesmo após uso prolongado. Ficha Técnica: - Cabedal: Couro hidrofugado 2,0mm - Cano e língua: Cordura 1000 - Forração interna: Membrana impermeável e Nylon tridimensional - Solado: Bi componente em EVA e borracha anti-derrapante - Palmilha: Anatômica em Poliéster - Bico: Costurado e inclinado - Peso por pé: 520 gramas (tamanho 40)', 488.92, 488.92, NULL, 'Men Shoes > Boots > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mls70wrxmg3n30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F23693884241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
