INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299651167', 'Ventoinha do Condensador Golf, Fox, Polo, Bora, New beetle e Audi', 'Ventoinha do Condensador – Audi / VW Golf / Fox / Polo / Bora / New Beetle – 9 Pás – 12V – Modelo Pequeno – Trisete Parts A ventoinha automotiva do radiador, também conhecida como eletroventilador, é responsável por resfriar o radiador e o condensador, ajudando a manter a água de arrefecimento em temperatura ideal e garantindo o desempenho do motor. No sistema de ar-condicionado, a ventoinha do condensador é fundamental para a troca térmica eficiente. Este modelo é compacto, com 9 pás, ideal para aplicações com restrição de espaço. 📍 Aplicação: Audi e VW Golf – A partir de 1999 VW Fox – Até 2007 VW Polo 1.6 – De 2003 até 2006 VW Bora – De 2003 até 2006 VW New Beetle – Somente 2006 📌 Com Ar-Condicionado | 9 Pás | Modelo Pequeno 12V ⚠️ Observação Importante: Para os modelos Fox, Polo, Bora e New Beetle, confirme o código original da peça antes da compra, pois há variações de encaixe. 🔧 Compatível com os códigos OEM: 1J0959455C, 1J0959455K, 1J0959455L, 1J0959455M, 6Q0959455L, 6Q0959455P, 6QD959455C, 1C0959455C Trisete Parts | Distribuidora de Peças para Ar Condicionado Automotivo ✅ Produto Novo ✅ Alta durabilidade e desempenho ✅ Envio rápido e seguro ⚠️ Atenção: Todas as informações são de responsabilidade do fabricante/fornecedor Imagens meramente ilustrativas A instalação deve ser realizada por profissional qualificado A Trisete Parts não se responsabiliza por erros de montagem', 314.47, 314.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-820lp-mm8y4bgpr6rka7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1469385638%2F19299651167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
