INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57155735723', 'Kit 2 Rolo Adesivo SCOTCH-BRITE 3M', 'O adesivo do rolo Scotch-Brite é resistente e não rasga. Além disso, seu poder de remoção é maior e a ponta do adesivo é muito mais fácil de ser achada. Esqueça a lâmina de barbear, o durex, o papa bolinha e outras soluções caseiras. O Rolo Adesivo Scotch-Brite é muito mais eficiente e elegante, sendo a alternativa certa para que você deixe suas roupas e estofados sempre com o melhor aspecto! Para utilizar o Rolo Adesivo Scotch-Brite, retire a capa protetora e deslize o rolo adesivo sobre a superfície a ser limpa. Quando a folha adesiva perder seu poder de adesão, remova apenas uma volta até o próximo pacote. Deixa suas roupas e tecidos livres de pó, pelos, cabelos e fiapos, sem danificá-los O único da categoria com o adesivo Scotch-Brite Feito com cabo reutilizável e fita adesiva de alta performance Rolo adesivo 3M prático, eficiente e elegante Adesivo resistente e com ponta fácil de ser achada Fita adesiva de alta performance Perfeita para retirar pelos de roupas sem danificar o tecido Limpa tecidos em geral Cabo reutilizável Rolo de 100mm x 3m Com 20 folhas', 37.8, 37.8, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-82632-mk89r6yu0bgn12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F57155735723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14730444174', 'Vermífugo Milbemax Para Cães De 5kg A 25kg Com 2 Comprimidos', 'Vermífugo Milbemax Para Cães De 5kg A 25kg Com 2 Comprimidos 7891217010325 5420036926672 - Indicado para cães; - Tratamento de Dirofilariose canina; - Auxilia no controle de infestação intestinal; - Uso oral. Milbemax é um vermífugo de amplo espectro indicado para tratar e controlar infestações intestinais por vermes redondos (estágios adultos). É indicado também para a prevenção da dirofilariose canina, tratamento e controle de infestações intestinais por vermes redondos (estágios adultos) tais como Ancylostoma caninum,Toxocara, Toxascaris leonina, Trichuris vulpis e vermes chatos (estágios imaturos e adultos) tais como Dipylidium caninum. Modo de usar Deve ser administrado a partir de 2 semanas de idade, e depois, mensalmente até o animal completar seis meses de vida. Cadelas amamentando devem ser tratadas ao mesmo tempo que os filhotes delas. Os cães adultos devem ser tratados 4 vezes por ano, em se tratando de verminose gastrintestinal e mensalmente, para prevenção da infestação pelo verme do coração. Indicação Cadelas amamentando devem ser tratadas ao mesmo tempo em que seus filhotes. Fórmula Cada Comprimido contém Milbemicina oxima .............................2,5mg; Praziquantel micronizado ..................25 mg; Excipiente q.s.p .................................125mg.', 57.78, 57.78, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh82trakwft325', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482003963%2F14730444174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
