INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798196761', 'Amortecedor Direção - VW Gol Saveiro Parati Santana Passat Voyage 1990 1991 1992 1933 1994 1995 1996', 'CONTEÚDO DA EMBALAGEM: 01 AMORTECEDOR DIREÇÃO CONVENCIONAL - COFAP CÓD. 22010 PRODUTO NOVO, ORIGINAL, COM GARANTIA E NOTA FISCAL. APLICAÇÃO: VW GOL G1/G2/G3/G4 - 1980/2015 VW PARATI G1/G2/G3/G4 - TODOS MODELOS VW VOYAGE - 1980/1997 VW SAVEIRO G1/G2/G3/G4 - 1980/2012 VW SANTANA - TODOS MODELOS VW VERSAILLES - TODOS MODELOS VW PASSAT - 1972/1989 FORD ROYALE - TODOS MODELOS ATENÇÃO: A RESPONSABILIDADE DA COMPATIBILIDADE DO PRODUTO E SUA APLICAÇÃO É DO COMPRADOR; NÃO NOS RESPONSABILIZAMOS POR PREJUÍZOS ADVINDOS DA APLICAÇÃO INCORRETA DO PRODUTO. CONSULTE O FABRICANTE DO SEU EQUIPAMENTO E CONFIRME A COMPATIBILIDADE COM O INSTALADOR. A MARTINS AUTOPEÇAS DISPÕE DE PEÇAS AUTOMOTIVAS PARA TODA A LINHA LEVE E MÉDIA DE VEÍCULOS, SE NÃO ENCONTRAR O QUE PROCURA, DEIXE UMA PERGUNTA E RESPONDEREMOS O MAIS BREVE POSSÍVEL.', 176.5, 176.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rbm6-m6344wd4trkac8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F538200526%2F22798196761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258303104', 'Alicate Decapador Automático 3 em 1 Corta Decapa Crimpa Fios e Cabos Profissional Forte Luatek LWJ-130', 'O Alicate Descascador de Fios Luatek LWJ-130 é a ferramenta essencial para eletricistas, técnicos de manutenção e entusiastas de projetos elétricos. Fabricado em aço carbono No.45 de alta resistência, com 21cm de comprimento, combina descascamento, crimpagem e corte em um único equipamento, garantindo agilidade, precisão e segurança em todas as suas tarefas. Ele conta com múltiplas funções integradas: descascador de fios ajustável para cabos de diferentes espessuras, crimpador para terminais isolados e não isolados, e cortador de fios integrado, eliminando a necessidade de ferramentas separadas. O design ergonômico com empunhadura antiderrapante em laranja e preto reduz a fadiga em usos prolongados, enquanto a estrutura reforçada suporta uso contínuo em ambientes profissionais. Ideal para trabalhos elétricos residenciais e comerciais, instalação de redes, manutenção de equipamentos, projetos de eletrônica e bricolagem, ele assegura descascamento limpo sem danificar os fios, crimpagem firme e corte preciso, tornando-se indispensável em qualquer caixa de ferramentas. Quantity:1 indication:0.34 Custom Product:No', 138.0, 35.98, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820ly-mmrguu0a4phd0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58258303104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209685430', 'Tesoura de Aviação Profissional 10" Corte Esquerdo Aço Manganês Chapa Calha Gesso Resistente', 'Olá! Precisa de precisão total para fazer curvas para a esquerda? 🛠️ Se você é um profissional que trabalha com calhas, rufos ou gesso acartonado, sabe que ter a tesoura com a orientação correta economiza tempo e evita o desperdício de material. Nossa Tesoura de Aviação de 10 polegadas (Corte Esquerdo) foi feita para facilitar sua vida! Projetada especificamente para cortes curvos à esquerda e cortes retos, ela possui lâminas em Aço Manganês 55 de altíssima resistência. O mecanismo de alavanca dupla permite cortar chapas metálicas com o mínimo de esforço, enquanto o cabo ergonômico TPR oferece uma pegada firme e confortável, mesmo em jornadas longas. ✅ Recursos e Benefícios: 📌 Corte Esquerdo: Especialmente desenhada para facilitar curvas para a esquerda e recortes circulares. 📌 Material Premium: Lâminas forjadas em Aço Manganês 55, garantindo um fio de corte duradouro. 📌 Alta Capacidade: Corta chapas de aço inox de até 1,0mm e aço laminado de até 1,3mm. 📌 Ergonomia Avançada: Cabo bicolor em TPR antiderrapante com descanso para os dedos e guarda de proteção. 📌 Sistema de Trava: Trava de segurança metálica para manter a ferramenta fechada ao armazenar. 📏 Especificações Técnicas: Modelo: LWJ-2312 Tipo de Corte: Esquerdo (Curvas e Reto) Comprimento: 250 mm (10 polegadas) Material: Aço Manganês 55 + TPR Capacidade em Aço Laminado: 1,3 mm Capacidade em Aço Inox: 1,0 mm', 80.0, 29.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lj-mnk84crx4ikk54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58209685430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899244400', 'Pedaleira Ecosport 03/12 Manual Aço Inox - Não fura o pedal', 'Gravação em relevo antiderrapante; Aparência esportiva e personalizada; Modelagem sob medida; Não fura os pedais originais; Instalação simples feita em minutos; ITENS INCLUSOS: 1 pedaleira para acelerador 1 pedaleira para freio 1 pedaleira para embreagem DESCRIÇÃO: A textura do aço escovado e a gravação em baixo relevo aumentam a aderência dos pedais garantindo mais esportividade na pilotagem. A instalação é simples e pode ser realizada em poucos minutos, pois as pedaleiras são fixadas com fita-dupla face 3M de alta performance. Este método de fixação foi testado e aperfeiçoado exaustivamente até chegarmos numa fixação firme e duradoura, o que é imprescindível para um local com tanto atrito e movimento. Projetadas especificamente para instalação no Ecosport com câmbio manual, estas pedaleiras cobrem os pedais originais com perfeição. A sola dos seus calçados normalmente estão sujas, contendo todo tipo de sujeira, o que colabora para o rápido desgaste dos pedais do seu Ecosport. Por serem produzidas em aço inoxidável elas nunca perderão o brilho. Instale este conjunto de pedaleiras que além de proteger os pedais contra o desgaste também vai proporcional um visual realmente esportivo. VEÍCULOS COMPATÍVEIS: Ford: • EcoSport 2003 Manual • EcoSport 2004 Manual • EcoSport 2005 Manual • EcoSport 2006 Manual • EcoSport 2007 Manual • EcoSport 2008 Manual • EcoSport 2009 Manual • EcoSport 2010 Manual • EcoSport 2011 Manual • EcoSport 2012 Manual DADOS TÉCNICOS PEDALEIRA: Matéria prima: aço inox 304; Espessura: 1,2 mm; Acabamento: escovado; Fita dupla face: 3M VHB; GARANTIA: 1 ano', 160.27, 160.27, NULL, 'Hobbies & Collections > Souvenirs > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdy4-m027hjnq23a9d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1103244663%2F21899244400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23705072610', 'Bobina Ignição Cerato Soul 1.6 2009 A 2014 Gauss Gc4286', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação KIA MOTORS CERATO 1.6 16V GASOLINA 2009 até 2013 SOUL 1.6 GASOLINA 2009 até 2014 SOUL 1.6 CVVT GASOLINA 2009 até 2010 SOUL 1.6 FLEX 2011 até 2014 Conteúdo Da Embalagem 1 Bobina de Ignição Tipo de Veículo para Carros Marca A Gauss nasceu em 1997, atualmente, com mais de 20 anos de atuação, a Empresa fabrica e comercializa cerca de 28 milhões de peças por ano, que são divididas em 4 linhas de produtos (Elétrica, Injeção, Ignição e Arrefecimento). Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de Garantia: 6 meses Valor unitário. Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. Código do Fabricante GC4286 Combustível FLEX GASOLINA Quantidade de Pinos 2', 101.05, 101.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbk8-lluismoy895m32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23705072610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
