INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9154004155', 'Guidão Modelo Original Aço Pro Tork Cromado e Preto Moto CB 400 Il 1982 1983 1984 1985', 'Os Guidões Modelo Original Pro Tork são perfeitos para substituir aqueles que já vem instalado em sua moto direto da fábrica, pois seguem os padrões da principais montadoras no país. São produzidos em Aço Tubular com parede de 1,9 mm, ou seja, são super resistentes e garantem maior vida útil ao produto. Especificações: - Modelo: Original; - Marca: Pro Tork; - Fabricado em Aço Tubular 1,9 mm. Aplicação: - CB 400 Il 1982; - CB 400 Il 1983; - CB 400 Il 1984; - CB 400 Il 1985. - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. O produto é 100% compatível e não necessita de nenhum tipo de adaptação. - Para instalar o produto, leve sua moto à uma oficina especializada. Nós não nos responsabilizamos por danos causados pela má instalação do produto.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma01mlfs5loi06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F9154004155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398675833', 'Teclado para Notebook Asus X Series X550LN', 'Teclado compatível com Asus X Series X550LN O teclado compatível com Asus X Series X550LN foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Asus. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: X550LN Moldura: Sem Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC717-AS-0056 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: X550C, X552E, X550L, X550CA, X550LN, 0KNB0-612BBR00, X550C-XO113H, MP-11N66PA-5281W, X552EA, X550, V143362AK1, NSK-US41B, X552, K56CACB, K56CCA, X550LA, K56, MP-12C76PA6920W Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 75.53, 41.0, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mqs6hgidl4pa05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23398675833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
