INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797550545', 'Turma da Mônica - Fábulas Inesquecíveis', 'Fábulas são histórias curtinhas, às vezes representadas por animais, que terminam com um ensinamento para a vida. Este livro encantador traz dez fábulas clássicas, representadas pelos divertidos personagens da Turma da Mônica. Temas como amizade, generosidade, honestidade e superação ganham um toque especial com a participação de Mônica, Magali, Cebolinha, Cascão, Chico Bento e companhia. O texto acessível e as lindas ilustrações vão despertar o interesse das crianças pela leitura. ?? A Tartaruga e a Lebre ?? A Cegonha e a Raposa ?? A Raposa e as Uvas ?? Os Dois Amigos e o Urso ?? O Pastorzinho Mentiroso ?? A Galinha dos Ovos de Ouro ?? O Leão e o Ratinho ?? A Assembleia dos Ratos ?? A Menina do Leite ?? A Cigarra e a Formiga', 21.39, 21.39, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lvub3wcum1tz69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23797550545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293064323', 'Demon Slayer - Kimetsu No Yaiba Vol. 8', 'Usando a Dança do Deus do Fogo, Tanjirou lança a técnica "Céu Límpido e Azul" em Enmu, o oni dos sonhos, mas quais serão as consequências desta batalha?! Além disso, qual a verdadeira identidade daquele que aparece diante do grupo do garoto? E finalmente Kyoujurou Rengoku, o Hashira das Chamas, entra em ação. O que Tanjirou viu além das palavras ditas por alguém tão poderoso?!', 45.65, 45.65, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd4v-lvtrfmt96iqx32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22293064323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294312856', 'Lona De Polietileno Verde 5m x 4m Vonder', 'A lona de polietileno verde 5 m x 4 m da Vonder é a solução ideal para quem busca proteção temporária em diversos tipos de atividades, como agricultura, construção civil, náutica, camping, pesca e utilidades domésticas. Impermeável e resistente, ela oferece proteção eficaz contra intempéries, sujeira e umidade, sendo versátil para diferentes necessidades de cobertura. Fabricada em polietileno de alta e baixa densidade, possui aditivo contra raios UV e cantos reforçados com fio sintético na bainha, garantindo maior durabilidade. Conta ainda com ilhoses posicionados a cada 1 metro para facilitar a amarração. Apesar da resistência, não é indicada para cobertura de cargas em veículos, uso sobre superfícies aquecidas ou como cobertura permanente de telhados. Características: Modelo: 6132054000 Referência: 6132054000 Medida da lona: 5 m x 4 m Espessura aproximada da lona de polietileno: 150 micra Cor da lona: Verde Distância entre ilhoses da lona: A cada 1 metro Massa aproximada: 2,12 kg Benefícios: Impermeável e resistente à ação do tempo Cantos reforçados com fio sintético para maior durabilidade Com aditivo que protege contra raios UV Versátil para aplicações agrícolas, recreativas e industriais Facilidade de amarração com ilhoses a cada 1 metro Conteúdo da embalagem: 1 Lona de polietileno.', 126.44, 88.93, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/sg-11134201-7rdwm-mdc661mcayq6d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23294312856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
