INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8750400136', 'Par de Halter 9kg Emborrachado PVC Vinho ( 2 unidades de 09kg )', 'Halter fabricado em ferro cinzento com revestimento em borracha plastissol PVC. Com indicador de peso gravado no ferro garante que a peça não perca o numero de seu peso. Resistente à água, óleos, fungos, ataque químico, anti-chama, dielétrico e intemperismo,alem da maciez para manipulação. OBS.: Vendido em Pares ( 2 peças ). Este halteres dispensa o uso de barras, pois tem o design moderno que facilita a prática dos exercícios e pode ser usado em casa ou na academia. Ideal para quem quer trabalhar os membros superiores e prático para quem gosta de se exercitar a qualquer momento. Conteúdo da Embalagem: 02 un. Halter 9kg Emborrachado PVC Vinho Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa. INSTITUCIONAL', 360.0, 360.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/73058981d555ca8877ec783efbc44d60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F8750400136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23919269984', 'TOKYO REVENGERS - VOL 1 - JBC', 'Tokyo Revengers gira em torno de Takemichi Hanagaki, um jovem de 26 anos mal sucedido na vida, profissionalmente e em relações amorosas. Vive com problemas financeiros e ainda descobre que sua ex-namorada foi assassinada por uma gangue de Tóquio. A notícia mexe bastante com Takemichi e, ao entrar numa estação de metrô, ele é empurrado nos trilhos e quando estava prestes a ser atropelado algo surpreendente acontece: Takemichi viaja 12 anos no passado, para sua época de escola. É a chance dele consertar o passado para mudar o futuro!', 43.1, 43.1, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-821cy-mhawun7gx2q655', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F23919269984', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299500015', 'Kit Creamy Ácido Glicólico Redutor de Linhas e Ácido Mandélico Gel Antiacne (2 produtos)', 'Kit Creamy Ácido Glicólico Redutor de Linhas e Ácido Mandélico Gel Antiacne (2 produtos) Esse Kit Contém Creamy Ácido Glicólico - Creme Redutor de Linhas 30g: de uso noturno para todos os tipos de pele. Creamy Ácido Glicólico auxilia na uniformização do tom, melhora a textura da pele, deixa os poros menos aparentes e previne sinais da idade. Creamy Skincare Ácido Mandélico - Gel Antiacne 30g: para peles oleosas e acneicas. Creamy Ácido Mandélico uniformiza o tom e textura da pele, reduz a oleosidade e combate a formação de acne. Com 7% de ácido mandélico, o Gel Creamy Ácido Mandélico é o primeiro produto com efeito peeling noturno suave de uso diário. Conselho de Aplicação Redutor de Linhas: aplicar sobre a pele seca e preferencialmente hidratada, evitando a região dos olhos, os cantos do nariz e da boca. Espalhe 1 ou 2 pumps sobre a pele do rosto, pescoço e/ou do colo, se desejar. No início do uso, recomenda-se usar em noites alternadas até que a pele não apresente nenhum sinal de irritação. Lave a pele pela manhã e aplique protetor solar. Gel: Uso noturno aplicar sobre a pele seca e preferencialmente hidratada, evitando a região dos olhos, os cantos do nariz e da boca. Espalhe 1 ou 2 pumps sobre a pele do rosto, pescoço e/ou do colo, se desejar. No início do uso, recomenda-se utilizar em noites alternadas até que a pele não apresente nenhum sinal de irritação. Lave a pele pela manhã e aplique protetor solar. Sensações transitórias de ardência podem ocorrer nas primeiras aplicações e tendem a desaparecer com o tempo.', 425.45, 199.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxv-m18t2ai8r52558', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F20299500015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098199054', 'Océane Nadia Tambasco Hair Makeup - Maquiagem Capilar Preto 4g', 'Océane Nadia Tambasco Hair Makeup - Maquiagem Capilar Preto 4g É um produto inovador que proporciona uma rápida e prática cobertura de raízes brancas ou desbotadas entre as colorações, conferindo um aspecto natural e uniforme ao cabelo. Sua fórmula é enriquecida com ativos que ajudam a nutrir e proteger os fios, como a queratina e o óleo de argan. Além disso, sua embalagem compacta e prática permite que seja levado para qualquer lugar e utilizado sempre que necessário. Modo de Uso basta aplicar o produto diretamente sobre as raízes ou áreas desejadas e espalhar com as pontas dos dedos ou com a ajuda de um pincel para um resultado mais preciso. Em seguida, finalize com um pente ou escova para distribuir o produto de forma uniforme.', 112.55, 63.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rati-ma46s53jdt4be4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21098199054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
