INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994156348', 'Perfume Colônia Frutas Vermelhas 60ml P/ Cães E Gatos - Pet Clean', 'Perfume Frutas Vermelhas Pet Clean - 60mL Deixe o seu pet ainda mais cheiroso com o Perfume Frutas Vermelhas da Pet Clean. Desenvolvido especialmente para cães e gatos, sua fragrância suave e frutada proporciona uma sensação refrescante e duradoura, ideal para manter seu companheiro limpo e perfumado entre os banhos. Benefícios: - Fragrância agradável: Aroma doce e suave de frutas vermelhas que agrada humanos e pets. - Uso seguro: Fórmula desenvolvida para animais, com pH balanceado e dermatologicamente testada. - Toque final ideal: Perfeito para usar após o banho ou sempre que quiser renovar o cheirinho do seu pet. - Fácil aplicação: Embalagem com borrifador que facilita o uso e evita desperdícios. Modo de Uso: Borrifar o produto a uma distância de aproximadamente 15cm da pelagem, evitando a região dos olhos, boca e mucosas. Pode ser usado sempre que necessário. Informações Adicionais: - Conteúdo: 60mL - Indicação: Cães e gatos de todas as idades - Fragrância: Frutas Vermelhas - Marca: Pet Clean Com o Perfume Frutas Vermelhas Pet Clean - 60mL, seu pet fica ainda mais encantador, com um cheirinho irresistível de carinho e cuidado!', 21.55, 13.9, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhw86a1ewxkz29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22994156348', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
