INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209358259', 'Eletroventilador Chevrolet Corsa 1994 Até 1998/ S10 2.8 00', 'Eletro ventilador do Chevrolet Corsa 1994 Até 1998/ S10 2.8 2000 - 12 Volts Sobre o Produto: O eletro ventilador é um componente do sistema de ar condicionado que tem por objetivo proporcionar um fluxo de ar eficiente, baixando a pressão e a temperatura do fluido refrigerante no condensador. O conjunto de ventoinhas é composto por um defletor, que se destina a fixar o sistema ao veículo e, em alguns casos a melhorar o fluxo de ar, um motor elétrico, e uma hélice. PRODUTO A PRONTA ENTREGA ENVIO IMEDIATO Empresa consolidada no Paraná, atuando no ramo de importação e distribuição com qualidade e agilidade. Informações importantes: * Recomendamos que a instalação seja realizada por profissional qualificado. * Não nos responsabilizamos por instalação incorreta ou mau uso, sob risco de perda da garantia. * Pedidos confirmados até às 13h são despachados no mesmo dia. Após esse horário, finais de semana e feriados, envio no próximo dia útil. * Imagens meramente ilustrativas. Dúvidas? Estamos à disposição. Atendimento: Segunda a sexta, das 8h às 18h.', 249.9, 237.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/br-11134207-820l5-mndattpxwkche2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1528132983%2F58209358259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15107295146', 'Protetor Solar Clareador Hidratante LAIKOU Proteção Corporal SPF50 + PA +', 'Descrição do produto: Proteção UV do protetor solar do rosto LAIKOU Clareamento facial protetor solar corporal creme de protetor solar SPF50+ 30g 30g Clareamento; Clareamento 50g; Ouro 50g; 2gx15pcs / Caixa Vida útil da Prateleira: 3 anos Fps: 50+ Funções: Protetor UV/Refrescante Ingredientes principais: BISABOLOL, TITANIUM DIOXIDE, ETHYLHEXYL METHOXYCINNAMATE, CAMPHOR DE 4 METILBENZILENZILENZILLENO, BUTYL METHOXYDIBENZOYLMETHANE Pele Problema Pele Problema Danos ultravioleta de raios ultravioleta Envelhecimento da pele causado pela pele UVA Queimaduras solares causadas pelo UAB Use nosso protetor solar agora Proteja a pele dos danos causados pela luz solar Bloqueie os raios ultravioleta Resiste a UVA e UVB Proteja a pele do ambiente poluído Ilumine o tom da pele e evite o aparecimento da melanina Modo de usar Aplique a quantidade adequada do protetor solar no rosto, pescoço, braço e perna uniformemente antes de maquiagem ou sair, massageie suavemente até que seja absorvido.', 46.0, 28.09, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/cn-11134207-7qukw-lfhr31rt3q9ka9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250961519%2F15107295146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
