INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597501393', 'Aditivo Limpeza de Valvula INTAKE VALVE CLEANER 200ML STP 5 unidades', 'INFORMAÇÕES GERAIS: Contém: 05 frascos com 200ml Modelo: ST-2070BR DESCRIÇÃO Fórmula concentrada, de forte ação, ajuda a eliminar depósitos nas válvulas de admissão, evitando problemas na passagem do combustível injetado. Excelente para motores de alta performance e tecnologia. MODO DE USAR Despeje todo o conteúdo no tanque do combustível. Um frasco trata até 50 litros de combustível. Caso necessário, repita a operação. Não prejudica catalizadores e nem sondas lambda. Pode ser utilizado juntamente com outros tratamentos STP para combustível. BENEFÍCIOS 1° Protege contra a oxidação e a corrosão. 2° Restaura a potência e melhora a aceleração do motor. 3° Tratamento superconcentrado para limpeza dos bicos injetores e do sistema de injeção de combustível. 4° Elimina falhas na partida, causada por mau funcionamento de injetores. 5° Mantém o sistema limpo por mais tempo, formando uma película protetora. 6° Reduz o consumo de combustível e a emissão de gases poluentes. 7° Indicado somente para motores a gasolina;', 222.0, 185.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lor8b08ud0uyfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F751090683%2F19597501393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
