INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893178883', 'Deo Colônia Masculino Strong 15ml - Fragrância Fougère para Dia - Perfume de Bolso - Amakha Paris', 'Para ocasiões formais e importantes, eleve sua presença com o poderoso Perfume Strong Aromático. Esta fragrância excepcional é uma escolha sublime para transmitir exuberância e autoridade, adicionando um toque de sofisticação a cada passo. As notas deste perfume trazem uma mistura equilibrada de frescor e masculinidade, criando uma aura de confiança e distinção. Cada borrifada deste aroma é uma declaração de sua elegância e determinação, revelando sua presença marcante em qualquer ambiente. Use este perfume para deixar uma impressão memorável em eventos formais. Deixe sua exuberância e poder se destacarem, mostrando ao mundo sua verdadeira grandeza em momentos importantes. Família olfativa: Fougere Ambarado • Notas de Topo: Lavanda, Anis, Limão, Alcarávia, Manjericão, Bergamota, Sálvia Esclaréia e Íris • Notas de Corpo: Vetiver, Sândalo, Patchouli ou Oriza, Cedro, Bagas de Zimbro ou Junípero e Cardamomo • Notas de Fundo: Musgo de Carvalho, Couro, Âmbar, Almíscar e Fava Tonka Indicações: • Para usar: Dia ou Noite • Ocasião: Elegância, Passeio ou Social • Perfil: Confiante e Comunicativo Inspiração - Azzaro', 50.0, 32.5, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m7jrkoerzy0m34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F23893178883', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899672981', 'Mouse Bright Espanha com fio USB Preto 106', 'Se você busca conforto e agilidade ao realizar suas atividades diárias no PC ou notebook, o Mouse Bright Espanha com fio USB é uma ótima escolha. Moderno e compacto, o mouse possui um design anatômico, tem tecnologia óptica, conexão USB e botão de rolagem. O Mouse Bright é fácil de instalar, basta conectar o cabo na entrada USB do seu computador, e é compatível com diversas versões de Windows.', 14.99, 14.99, NULL, 'Computers & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mqp1c8qmmj29c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F20899672981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
