INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599542192', 'Teologia do Novo Testamento | I. Howard Marshall', 'HÁ MUITO QUE O PÚBLICO EVANGÉLICO ESPERA POR UMA TEOLOGIA DO NT COMO ESTA. AO LONGO DESTA OBRA I. HOWARD MARSHALL TRAZ PROFUNDAS REFLEXÕES, FRUTO DE MUITOS ANOS DE ESTUDO, PESQUISA E ENSINO NA ÁREA DO NOVO TESTAMENTO. POR ISSO MESMO, NÃO É UMA TEOLOGIA QUE SE SUCUMBE À TENDÊNCIA DE ENXERGAR NO NOVO TESTAMENTO UMA DIVERSIDADE QUE SEJA IRRECONCILIÁVEL. PELO CONTRÁRIO, O AUTOR DEFENDE A EXISTÊNCIA DE UMA TEOLOGIA NEOTESTAMENTÁRIA FORMADA A PARTIR DOS DIVERSOS TESTEMUNHOS QUE ENCONTRAMOS NOS LIVROS DO NT. E DESSA FORMA, A PARTIR DA ANÁLISE INDIVIDUAL DOS DOCUMENTOS QUE COMPÕEM O NT, VAI PASSO A PASSO CONSTRUINDO UMA SÍNTESE DESSA TEOLOGIA, PROVANDO ASSIM SUA TESE: DIVERSOS TESTEMUNHOS, UM SÓ EVANGELHO. 16x23cm 656 Páginas', 109.9, 99.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-m1glplhc2tkt30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21599542192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493945448', 'Kit Deus que Destrói Sonhos + Como se tornar um cristão inútil | Capa Dura | Rodrigo Bibo', 'Somos sacerdotes de all-star O convite ao discipulado e à vida cristã não é um chamado para ser o protagonista da história, mas para ser parte de um povo. Deus não procura quem sonha com cargos e títulos ou quem deseja receber medalhas. Ele está à procura de verdadeiros adoradores, de cristãos comuns que testemunham do evangelho sem precisar subir no palco. Afinal, no reino dos céus não há lugar para especiais, orgulhosos, para quem quer ser o primeiro, mas para gente arrependida e para cristãos “inúteis”! 12x18cm 176 Páginas', 69.9, 64.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9osbjxsiqm1b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22493945448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21408530160', 'Bíblia de Estudo | Letra Média | Joyce Meyer | NVI | Floral', 'A Bíblia da Vida Diária com notas e comentários da autora Joyce Meyer Bíblia Sagrada, com a linguagem na versão NVI (Nova Versão Internacional). Dentre as versões bíblia ela se torna uma das mais modernas e prezervando a clareza do texto, permanecendo fiel aos Escritos originais. Incluindo panorama bíblico e mapas. A Bíblia pode ser de difícil leitura e compreensão. Seu objetivo ao oferecer a você esta Bíblia exclusiva com suas notas e comentários é construir pontes sólidas entre as palavras da Bíblia e a sua vida diária. Joyce Meyer espera que a BÍBLIA DE ESTUDOS JOYCE MEYER o ajude a aplicar as verdades da palavra de Deus à sua vida através de suas contribuições, que incluem: INTRODUÇÃO AOS LIVROS, que incluem um breve relato no início de cada livro da Bíblia. PRINCÍPIOS PARA A VIDA, que traçam uma linha entre as palavras do texto e a experiência do leitor. ARTIGOS PARA A VIDA DIÁRIA, que se concentram em passagens específicas e trazem a percepção e os ensinamentos de Joyce. COLOCANDO A PALAVRA EM AÇÃO, que traz algumas das perguntas diretas de Joyce para incentivar a reflexão, e em seguida, a ação. DECLARE A PALAVRA, que apresenta versículos adaptados para serem feitos como orações individuais de confissão, trazendo as promessas da Bíblia para um nível totalmente novo e pessoal. A abordagem simples e direta de Joyce em relação à vida tornou-a admirada por muitos como mestra, mentora, e amiga. Ter acesso a seus pensamentos e ensinamentos ao estudar a Bíblia dará uma nova dimensão às palavras de vida e você se sentirá como se tivesse a própria Joyce Meyer como sua companheira de estudos. 1679 Páginas 14x21cm', 154.9, 144.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/ca5a1a60bad8e74f8ce0caa7786ec786', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21408530160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56461314100', 'Revista Lições Bíblica Juniores Aluno 3º Trimestre 2026', 'Adequada para alunos de 11 e 12 anos, a revista Pré-Adolescentes, a cada trimestre, dá novos conhecimentos a respeito da Palavra de Deus. Totalmente formulada de acordo com orientação pedagógica e didática, com conteúdos didáticos atualizados. Tema: Tempo dos Juízes Lição 1 – A Desobediência Do Povo De Deus Lição 2 – Deus Escolhe Libertadores Lição 3 – Otoniel e os Mesopotâmios Lição 4 – Eúde e os Moabitas Lição 5 – Sangar e os Filisteus Lição 6 – Débora E Baraque na Batalha Contra os Cananeus Lição 7 – Gideão Enfrenta os Midianitas Lição 8 – Abimeleque Lidera Israel Lição 9 – Jefté Livra Israel dos Amonitas Lição 10 – Jefté Batalha Contra os Efraimitas Lição 11 – O Nascimento E Vida De Sansão Lição 12 – Sansão Livra Israel dos Filisteus Lição 13 – Mica e o levita em sua casa 20X27 CM 64 Páginas', 17.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823rl-mot028w9np4wd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F56461314100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898548731', 'Atlas Geográfico Escolar', 'Este Atlas foi elaborado com cuidadosa pesquisa especializada, utilizando fontes nacionais e estrangeiras para trazer até você, leitor, um conteúdo conciso e atualizado. Aqui você encontra mapas detalhados dos planisférios, dos continentes e do Brasil - Regiões e Estados -, além de informações sobre astronomia e as camadas da Terra. 27x20 cm 68 Páginas', 26.9, 21.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ravd-maag0o2mu1wh56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22898548731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194056847', 'Manopla Bola Alavanca Câmbio 5 Marchas Vectra 1997 A 2005', 'Manopla Bola Alavanca Câmbio 5 Marchas Vectra 1997 a 2005 Indústria Brasileira A NAT Indústria disponibiliza aos seus clientes um alto padrão de qualidade na fabricação de peças de reposição e acessórios automotivos. Todas as peças são fabricadas com qualidade original, mantendo sua funcionalidade e melhor custo-benefício. A Manopla de Câmbio da NAT possui uma instalação simples e intuitiva. A Manopla de Câmbio é confeccionada em PVC de alta resistência e acabamento emborrachado. Aplicação: - Vectra 1997 a 2005 Tipo de Encaixe: - Encaixe sob Pressão Informações: - Qualidade de Original - Tamanho e peso idênticos ao Original - Produto Nacional - Ótimo acabamento Emborrachado - Instalação simples, rápida e intuitiva - Para Câmbio Manual. Garantia: - 3 meses Cor do Produto Pode haver divergência na tonalidade do produto vista no site e a do produto ao vivo, devido a calibragem de brilho do monitor das telas de computadores e celulares. Não nos responsabilizamos por essa alteração. - Imagens meramente ilustrativas Garantia do vendedor: 3 meses', 44.97, 44.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7ravj-maelntkss5zl2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353832716%2F23194056847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
