INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50557816297', 'Painel de Festa Retangular Copa Futebol Brasil Hexa 2026 Decoração 1,50x2,20m Sublimado Em Tecido', '*** ATENÇÃO: NÃO FAZEMOS AJUSTES DE MEDIDA OU ARTE NOS PAINÉIS VERTICAIS RETANGULARES DESTE ANÚNCIO. VERIFIQUE AS MEDIDAS E MODELOS ANTES DE FINALIZAR A COMPRA *** >>> PAINEL RETANGULAR VERTICAL EM TECIDO 1,50x2,20 COM ACABAMENTO PASSA VARÃO NA PARTE DE CIMA, COM UTILIZAÇÃO EM ESTRUTURAS >>> PAINEL NÃO POSSUI EMENDA!!! ** ITEM INCLUSO: 1 Painel em Tecido Malha New medindo 1,50m de largura por 2,20m de altura ** Não acompanha qualquer item utilizado para demonstração de utilização do material com fotos reais. DETALHES DO PAINEL VERTICAL RETANGULAR EM TECIDO: + Tecido Malha New (Que estica e não amassa). + Tecido Leve com ótimo caimento + Gramatura: 140g/m de excelente qualidade. + Composição do Tecido: 95% Poliéster e 5% de Elastano. + Acabamento em overloque evitando que o cilindro desfie. + Acabamento passa varão para fixação do painel vertical retangular. BENEFÍCIOS DO PAINEL VERTICAL RETANGULAR: - Não reflete luz do flash - Pode ser lavado várias vezes - Pode ser passado a ferro - Fácil transporte e armazenamento - Não amassa com facilidade, ótimo caimento - Alta durabilidade - Não retém água, se molhar vai secar rapidamente - Não perde coloração A cor do Painel pode variar devido a configurações de brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. Nosso material possui uma cor bem viva, bem vibrante. PRODUÇÃO E ENVIO: - TODOS OS PEDIDOS ACOMPANHAM NOTA FISCAL. - O painel retangular é enviado em até 1 DIAS ÚTEIS após pagamento aprovado. - Possui garantia contra defeito de fabricação. - O envio é feito em embalagem individual e com todo carinho. - Os prazos para entrega variam de acordo com o seu CEP, não nos responsabilizamos pelos prazos dados pela plataforma da Shopee. *** Tem alguma dúvida antes de finalizar sua compra? Envie uma mensagem para nós que ajudaremos você! Temos vários anos de experiência no mercado em itens sublimados. ***', 89.9, 69.9, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/br-11134207-820m9-mmc4brvbnll200', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F50557816297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997432386', 'Polia Correia Alternador Nissan Frontier 1998 a 2015 - 183877 - 4289', 'Polia Correia Alternador Nissan Frontier 1998 a 2015 183877 4289 2.8 TURBO (70x30,5X17mm) REFIL É o componente que está montado no eixo do rotor do alternador, e por meio de uma correia de distribuição, o alternador gira conforme a velocidade do rotação do motor(Rpm). Esta correia pode ser do tipo trapezoidal ou do tipo poly-V.', 63.64, 63.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmc-lmqi68oep1dl16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18997432386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892311097', 'Bóia Tanque Sensor Nível Renault Clio 2000 a 2005 - 179074 - T010025', 'Bóia Tanque Sensor Nível Renault Clio 2000 a 2005 179074 T010025 (NACIONAL) 1.0/1.6 8/16v Combustível: Gasolina e/ Convertidos Gasolina para Álcool (MARWAL) O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 122.57, 122.57, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rblb-ln0khgta5gqfbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23892311097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497064244', 'Sonda Lambda Focus 1.6 1.8 2003 a 2009 Zetec Rocam Pré Cat - 1906 - 782040040', 'Sonda Lambda Focus 1.6 1.8 2003 a 2009 Zetec Rocam Pré Cat FORD - Focus 1.6 8v / 1.8 16v 2003/2007 - Zetec Rocam (4 FIOS - 40cm) (Pré Catalisador) (Convencional) A sonda lambda, sensor de oxigênio, sensor de O2, por vezes também chamado sensor EGO (do inglês exhaust gas oxygen), é um dispositivo que envia um sinal elétrico à injeção eletrônica do automóvel indicando a presença de oxigénio nos gases de escape, possibilitando o controle da quantidade de combustível a enviar para o motor.', 234.39, 234.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbku-ln0lzpnaht11fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23497064244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
