INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097672242', 'Termo-Interruptor (Cebolão) Vw Santana 1985 a 1993 - 842574 - 7058676', 'Termo-Interruptor (Cebolão) Vw Santana 1985 a 1993 842574 7058676 1.8 8v Gasolina - 86º / 76º - 2 Pinos No trânsito é importante o acionamento da ventoinha do radiador. A peça responsável por isso é o Interruptor Térmico. São comutadores (Liga-Desliga) que acionam diversos produtos no sistema de arrefecimento em função da temperatura. Localizado no radiador, aciona a ventoinha quando a temperatura ultrapassa a temperatura ideal de trabalho, evitando assim o superaquecimento do motor.', 52.06, 52.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd43-luf7dsa7mrbs9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20097672242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
