INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898525140', 'Limpa Inox Electrolux 500ml Limpeza e Proteção', 'Encontrar o produto ideal para deixar nossos eletrodomésticos lustrados e brilhando como novos é um desafio diário. Com o limpa inox Electrolux, você vai poder deixar sua cozinha mais linda do que nunca. Diga adeus àquelas sujeiras e gorduras que teimam em ficar na superfície do seu fogão. Este produto para limpar fogão inox vai deixar fogão sempre limpo e bem cuidado. Altamente eficaz na remoção de marcas de oxidação superficial, a solução limpa inox Electrolux é muito fácil de usar. Basta borrifar a quantidade desejada sobre a superfície em inox, aguardar alguns segundos e depois passar um pano de microfibra em movimentos circulares. Caso deseje uma limpeza mais profunda, é só incluir o polidor de inox Electrolux junto com o produto para limpar inox que sua geladeira, fogão, panelas e demais eletrodomésticos estarão perfeitos e em ótimo estado de conservação.', 29.9, 29.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7ravq-ma39px446h5o01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F22898525140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
